window.POEM_DB=window.POEM_DB||{};POEM_DB["ming_003"]={"n":"欧大任","dyn":"明","poems":[{"t":"三河水","f":"古风","c":["三河水，万军泪。","泪滴三河水不流，胡笳吹落蓟门秋。","河水流不住，胡笳过何处。","谁使十年来，移营两屯戍。","君不见胡骑已驰墙子关，汉军尚哨熊儿峪。"]},{"t":"燕京篇","f":"古风","c":["万年天府国，佳气满燕州。","锦绣三千里，金银十二楼。","微闾作镇连恒岳，太行苍苍尽幽朔。","环流瀛海入扶桑，襟带滹沱出新漷。","海岳效灵符帝历，象纬分明拱辰极。","缥缈天中玉殿高，岧峣汉表金茎直。","千官朝谒建章宫，燎火光中望六龙。","词客麒麟争献颂，山人芝草亦输供。","春日鸡鸣宫钥启，春花吹入千门里。","垂柳清波涨御沟，疏槐夹道通官市。","列署周庐若散星，九衢走马如流水。","朱轮翠幰过何穷，绣户雕栊对相起。","观灯斗草竞繁华，芍药开时万树霞。","银缸照夜金张宅，宝槛移春许史家。","尘逐妖童九华扇，蝶迎倡女七香车。","百壶芳醑欢新曲，千啭娇莺度落花。","娇莺啼向歌屏上，平乐新丰惯来往。","誇胡未诏长杨游，承恩曾谒甘泉仗。","此时至尊在西苑，阆水蓬丘开别馆。","禁籞青烟晓色浓，宫池黄鹄春波暖。","通天台峻出层城，五色玄都绛节迎。","仙官法箓随舆度，侍女香炉傍辇行。","鸾舆玉辇万灵朝，西望明庭亦不遥。","九霄青鸟年年至，八骏瑶池日日邀。","苍龙愿捧轩辕驭，昆崙更接崆峒路。","一闻八伯《白云歌》，不羡相如《大人赋》。"]},{"t":"送张治中孺觉赴留都","f":"五言律诗","c":["谁似张京兆，名驹快月题。","驿程扬子外，官阁秣陵西。","射雉芜深翳，藏乌柳暗啼。","词人非六代，莫更唱《前溪》。"]},{"t":"夏日同刘仲修李惟寅诸子出城访丘谦之得飞字","f":"五言律诗","c":["西来初弛担，策马问郊扉。","以我思乡泪，沾君去国衣。","齐梁游已倦，江汉赋将归。","一叶秋风里，何年向洛飞。"]},{"t":"晚霁过梅关","f":"五言律诗","c":["千峰收积雨，迢递出梅关。","日向猿声落，人从鸟道还。","中原开障塞，南海控瓯蛮。","万国来王会，秋风战马闲。"]},{"t":"经王子新故居","f":"五言律诗","c":["独有山阳笛，难寻溪上庐。","人琴俱已矣，台沼更何如。","暮燕归新社，春泉满坏渠。","今来悲转切，未报秣陵书。"]},{"t":"秋晓经西苑","f":"七言律诗","c":["日上觚棱照綵游，西宫夜醮火初收。","沧池波色青门晓，长乐钟声碧树秋。","名岳采芝诸使出，中天筑馆万灵游。","汉家词客头将白，汾水年年望御舟。"]},{"t":"赠阎永平擢宪副备兵关西","f":"七言律诗","c":["承明一出岁悠悠，佩印西秦第一州。","此去护羌兼戊己，曾闻归汉对春秋。","醉中胡月悬烽堠，战后边笳满戍楼。","章句自惭投笔吏，看君华发早封侯。"]},{"t":"伏日姚唯之陆华甫董述夫见过","f":"七言律诗","c":["官舍莺啼绿树阴，炎天步屧尔能寻。","楼前过雨山俱出，阶下生烟竹更深。","讲肆不妨开马厩，诗篇何必到鸡林。","酣歌气与秋空远，丹壑谁知静者心。"]},{"t":"秋夜登广陵城","f":"七言律诗","c":["西风淮水下邗沟，何处关山独倚楼。","赋后芜城荒井径，书来瓜渚断江流。","青天寒色千砧夕，沧海潮声万弩秋。","满目苍苍见平楚，不知歌吹在扬州。"]},{"t":"过喻水部邦相留酌得颜字","f":"七言律诗","c":["楚歌何自入燕关，闻是恩深早赐环。","兰芷并含公子泪，芙蓉双照逐臣颜。","句因谢客题精舍，疏与匡君乞障山。","他日清觞那可共，天涯吾已倦知还。"]},{"t":"出郊至南海子","f":"七言律诗","c":["万树周阹起夕烟，汉家宫囿带三川。","誇胡几幸长杨馆，讲武曾驱下杜田。","敕使日调沙苑马，诏书春散水衡钱。","西游不数诸侯事，尚忆词臣扈从年。"]},{"t":"玉河堤上见新月时入直署中","f":"七言律诗","c":["弦月纤纤照马蹄，竹书犹把署中栖。","沟前垂柳穿林影，禁里新莺过水啼。","缇骑纷随秦苑北，朱旂深护汉宫西。","倦游不记长安道，一望关河怨解携。"]},{"t":"送董侍御惟益按滇中","f":"七言律诗","c":["按部西南天地间，威棱久已伏诸蛮。","沧江可渡曾通驿，铜柱犹存不置关。","晴雪玉连华马国，秋风花满碧鸡山。","便宜封事应条上，羌笮行看六传还。"]},{"t":"江陵女歌","f":"五言绝句","c":["涉江朝采莲，涉浦夕采兰。","送欢三峡渡，忆妾六盘关。"]},{"t":"明明","f":"古风","c":["太一明明，十二紫宫匡卫成，五岳泰华恒嵩衡。","皇帝坐明堂，左右以股肱。","群吏奉法，民不知兵。","征繇息，庾禀盈。","沐日浴月五谷生，烟火万里狗吠而鸡鸣。","六七十翁敖户庭，自未尝至闾井行。","比屋为宾主，妇子治糁羹。","考钟拊鼓，弹丝吹笙。","灵芝华华槃舞终，嘉福穰穰熙和蒸。","为我谓客，且安坐而酌兕觥，今我不乐将何营。","击壤游以嬉，天地惟曼宁。","百昌并，四海正，陛下万载人太平。"]},{"t":"芳树","f":"古风","c":["芳树翠葳蕤，照我东西厢。","嘉祀承蚃肸，郁鬯百醴芗。","一人庆成，九门有闶。","卿云缦缦朗景长，戛鸣球镛奏笙簧。","万民愉，庶物康。","凤凰秋秋，鸿鹄将将，辟邪天禄纷而翔。","茝兰结佩玑璇英，千秋万岁奉我皇。"]},{"t":"艳歌行","f":"古风","c":["日出东南隅，陌上光景杲。","妾心畏蚕饥，闺中起常早。","言采陌上桑，少年逢路旁。","驷马立踟蹰，遣吏下请将。","妾跪长太息，妾家有夫侍中郎。","侍中五日一洗沐，门前车马烂生光。","君自有妇妾有夫，钱刀何用徒区区。","君可速归去，勿复问罗敷。","采桑采桑朝露多，闺中蚕饥愁奈何。"]},{"t":"长歌行","f":"古风","c":["驱车出彼东门，遥望丘垄巑岏。","白杨萧萧古坟，下有公子王孙。","牛羊旦上，狐狸夕蹲，我心见之烦冤。","天地无极，阴阳递迁。","人命鼎鼎，百年昼短夜长，何不秉烛开筵。","青阳忽已度，白日无留光。","功名恐卑薄，不得铭旂常。","迨此閒暇日，为乐殊未央。","主称千金寿，宾奉万年觞，何用恻恻悲伤。","朝望三山，夕望十洲。","骖驾白鹿遨游，桂树夹植道周。","八骏蜚而征，双凫何悠悠。","乔松邈矣难俦，前有双樽酒。","吾今亦复何求，愿言乐矣忘忧。"]},{"t":"短歌行","f":"古风","c":["乐乐自生，人穷反本。","生世几何，倏忽已晚。","去者日疏，来者日亲。","水流同源，木生同根。","父母兄弟，岂伊异人。","况有旨酒，云胡弗欢。","白日冉冉，明膏继夕。","调轸鼓丝，乐我亲戚。","春有催耕，秋有促织。","岁事方勤，及此游息。","今日同堂，明日异乡。","听我短歌，心如之何。"]},{"t":"独漉篇","f":"古风","c":["独漉独漉，摩肩击毂。","但欲去速，不忧车覆。","有狐绥绥，阪田之垂。","我欲疾驱，手无戈殳。","煌煌黼裳，翩翩四牡。","出入道途，称者盈口。","敝裘毁车，谁知贤愚。","珠玉在途，瓦砾何殊。","原也悬鹑，于彼蓬蒿。","端木驷马，举世贤豪。","嗟念古人，竭力躬耕。","一日及养，三公匪荣。","富不可求，荣不可冒。","我岂不闻，我不敢告。","富而可求，智者媚灶。","从吾所好，卿勿复道。"]},{"t":"燕歌行","f":"七言古诗","c":["黄云闇淡天雨霜，边风萧萧草木黄。","捣衣早寄关塞长，念君北征穷朔方。","明月流辉照洞房，蟏蛸在户熠耀光。","金炉兽炭苏合香，锦衾角枕七宝床。","清漏迢迢夜未央，断猿哀雁摧肝肠。","忧来抚瑟弹清商，君今不在谁为详。","揽衣出户涕沾裳，望而不见增忧伤。"]},{"t":"鞠歌行","f":"古风","c":["白日暄，朱草繁，黄鹄从风离哉翻。","时罕遇，岁徂迁，婵娟思媚谁为言。","剑在地，玉在山，剖璞飞光良独难。","管仲奔，鲍叔言，智伯既灭豫让冤。","嗟往者，不可攀，抚心感激涕汍澜。"]},{"t":"豫章行","f":"古风","c":["豫章有古树，群鸟巢其枝。","嗟我贱与贫，妻子长寒饥。","入室惨不乐，但闻悲风萧萧鸿雁飞。","仗剑将远去，弱子当门啼。","妻顾向我言弃妾，尚可奈此呱呱儿。","高车驷马，下有崄巇，不如家中共餔糜。","归来归来，东门牵犬君奚疑。","阪下粟，可以炊。","机上布，可以衣，愿君百岁无相离。","噫嚱唏，富贵不可求，贫贱不可去。","上有仓浪天，勿复虑。"]},{"t":"白头吟","f":"五言古诗","c":["涉江采幽兰，兰叶何离离。","严冬十二月，兰色一何衰。","采兰复采叶，赠君与君别。","兰生自有香，耐可芳馨歇。","雎鸠江上飞，欲去还迟迟。","岂不惜毛羽，由来是雄雌。","妾有绣罗裳，葳蕤自生光。","与君相决绝，东西各翱翔。","磐石结蒲苇，缱绻不得将。","今日乐相乐，别后莫相忘。"]},{"t":"塘上行","f":"五言古诗","c":["蒲生无定根，夙昔在涧湄。","雨露一沾润，移植金银池。","贱妾初事君，自许黄发期。","昔如春花鲜，今似秋草萎。","繁华自零落，膏泽不复施。","寒暑一何速，盛衰难自持。","谗言岂必深，君恩宁中移。","弃置固其理，妾心常依依。","嘅彼白华人，辛苦今独知。"]},{"t":"淋池歌","f":"楚辞体","c":["淋之池，太液浒。","水涡涡，隰膴膴。","文梓船兮翠云旗。","薜荔裳兮芰荷衣。","美人乐兮憺忘归。","隰膴膴，水涡涡。","隰有兰，水有茄。","采兰佩兮采莲歌。","飞凫浴鹭随渌波。","遨且游兮秋已多。","日暮天长愁奈何。"]},{"t":"招商歌","f":"楚辞体","c":["飕飕渠上风，湜湜水中沚。","昼卷夕还舒，宛结双莲子。","吴娃越女音节和，夜凉继日棹击波。","水有鱼兮沚有莎，君不游兮何以歌。","歌玉凫，奉金觚，君乐饮酒乐只且。"]},{"t":"怨歌行","f":"五言古诗","c":["高台风萧萧，下泽波湛湛。","春草绿已萎，游子岁月深。","驾言御松舟，写我繁忧襟。","昔来睢鸠鸣，今已蟋蟀吟。","遨游将安归，弭棹回塘阴。","胡马嘶陇首，塞鸿翔汉南。","我欲往从之，江永思难任。","伫立睇川涂，一寄瑶华音。","行行采兰苕，聊以纾我心。"]},{"t":"蒲生行","f":"五言古诗","c":["瀰瀰塘下水，凿凿水中石。","鲂鲤自唯唯，葭菼何泽泽。","中洲有王睢，交鸣共昕夕。","念我同心人，邈哉山原隔。","葛生蒙棘中，而我谁与息。","寒雨岁且阴，朔风惨原陌。","白日忽遄飞，芳馨已非昔。","公子未西归，积思故无极。","渚鸿来何时，延伫空堂侧。","抚瑟望所欢，仰视浮云白。","逝此将安之，肝肠结如织。","安得谖草花，宽我长忧戚。"]},{"t":"苦寒行","f":"五言古诗","c":["同云暗九野，薄霰周八埏。","厚地凝积雪，凄风肃高天。","天地亦闭塞，原阪何萧然。","大漠惨飞沙，塞门出黄烟。","胡马向月嘶，鸿雁长翩翩。","穷兽潜窟穴，饥鸟号墓田。","中河结流澌，日照古台边。","贫士叹无衣，布褐卒岁年。","出户行负薪，敲冰汲寒泉。","藜藿恒不充，何由挟重绵。","出见贵公子，连骑扬金鞭。","冠剑服狐裘，徒御皆绮纨。","燕姬侍朝宴，吴娥奉宵筵。","酒酣揽雕弓，射猎南山前。","归来命胞人，四座齐称贤。","岂知草玄客，闭关独高眠。","商歌自一时，苦寒非所叹。"]},{"t":"桂之树行赠黎氏","f":"五言古诗","c":["桂树郁苍苍，下荫白玉堂。","堂前凿方池，中有双鸳鸯。","君家何烜赫，绣衣照西京。","玉斧凛白日，威名闻四方。","御史府中居，神羊夹门枢。","东方来车骑，过者立踟蹰。","三子灿鸾凤，嗈嗈衔宝书。","入室共称寿，奉觞拜堂除。","白鹿可以晡，青霞鍊为腴。","谢君王箱药，宴饮吹笙竽。","丈人请为欢，饮酒延万年。","永言歌寿昌，听我桂树篇。"]},{"t":"江南曲","f":"古风","c":["江南忆采莲，莲叶何田田。","木兰为楫，文梓为船。","刺船榜歌莲叶边，鸳鸯双飞遂不前。","双飞双浴比颜色，唶我欲执何由得。","回桡榄结双莲花，日暮江南望江北。"]},{"t":"紫骝马","f":"五言律诗","c":["生长出边疆，碛西飞鞚长。","气薄三河少，恩倾大郡良。","横行蒲类海，射取鹿蠡王。","骄嘶朝紫禁，散尽玉门霜。"]},{"t":"铜雀台","f":"五言律诗","c":["邺宫久寂寞，铜台今独悲。","墓田不可望，陵树朝离离。","茵烟沾罗席，松风吹穗帷。","妾命由来薄，君恩讵能思。"]},{"t":"黄竹子歌","f":"五言绝句","c":["青青黄竹子，持许作团扇。","马上白面郎，含羞不相见。"]},{"t":"乌栖曲 其一","f":"七言绝句","c":["月落未落乌将栖，可怜夜夜夜半啼。","闺中少妇停梭泣，泪湿鸳鸯不成疋。"]},{"t":"乌栖曲 其二","f":"七言绝句","c":["大艑长樯铁鹿子，布帆直过梅根渚。","石城儿女颜如花，问郎今夜宿谁家。"]},{"t":"别诗","f":"五言古诗","c":["晨风忽萧萧，白露一何早。","嗟我思故乡，送君就长道。","骊驹在玉门，岂得长宴好。","长安多贵游，冠簪杂羽葆。","子独万里行，令予结怀抱。","惆怅枌榆情，临岐思如捣。","赠子玉连环，佩子金光草。","离别岂不悲，荣名以为宝。"]},{"t":"泊枞阳眺览盛唐遂忆汉武之游","f":"五言古诗","c":["行役届皖城，放舟下枞阳。","原隰郁膴膴，江波浩汤汤。","忆在元封中，君王狩朱方。","大江深且广，及兹一苇航。","慷慨盛唐歌，意气临八荒。","弯弧射蛟台，皇武何可当。","六龙奋遨游，宝鼎开灵昌。","八骏将安归，黄竹悲哉伤。","宸游事既往，六合无回光。","春沙莽草露，洲曲鸿雁翔。","不见楼船还，空馀蕙兰芳。","追昔有虞氏，恭己垂衣裳。","缦缦卿云飞，跄跄仪凤翔。","圣人重无为，君子贵豫防。","览古动悽恻，延伫增彷徨。"]},{"t":"首夏侍督学莆田林公药洲游眺","f":"五言古诗","c":["青阳布芳陌，朱明届炎陬。","仙城久标胜，旧苑开灵洲。","丰泽溢嘉荣，百卉纷以柔。","菡萏耀金塘，紫薇间朱榴。","清川带蒲藻，凫雁唼喋浮。","游鱼乐渊深，鸣鸟依林幽。","昔闻川上叹，今悟沧浪讴。","君子务玄赏，于焉事遨游。","温颜重延接，列坐亲绸缪。","见眷良已勤，越分非所由。","仰瞻九曜石，俯睇琅玕丘。","懿彼凤与凰，翩翩不可留。","何由附高翼，鉴辉翔九州。","来仪亮有期，千秋赞皇猷。"]},{"t":"答梁公实","f":"五言古诗","c":["古人重胶漆，良会期盍簪。","结交诚匪易，伊好方自今。","夙昔抱孤操，谁能察悁忱。","美人椷素书，诒我绿绮琴。","感君缱绻意，契我平生心。","清宵为君弹，宛转谊更深。","许与从此始，箴儆信所钦。","奇情托双亮，不必同裯衾。","七襄岂成报，俟尔金玉音。"]},{"t":"答黎惟敬","f":"五言古诗","c":["鱼目混夜光，荆玉迷瓦砾。","溟鲲搏扶摇，斥鴳困丛棘。","哲士多苦心，微言岂能析。","黄钟久不闻，大雅竟谁力。","之子振玄藻，翩翩起南域。","抗志入云霄，戢羽媚泉石。","游息竹素园，结托丘樊客。","手中握灵蛇，至宝固无敌。","夙昔晤清颜，幽怀契岑寂。","赠我锦绣章，宛转琅玕色。","知君意绸缪，何以报胸臆。","思为中洲鸿，奋起云间翼。"]},{"t":"登芙蓉山","f":"五言古诗","c":["结发窥山笥，冥心睹河编。","怀奇信所遇，戒游及兹年。","芙蓉控韶郡，石室飞云烟。","发鞍度兰坂，緤鞚披萝阡。","岩幽路回转，涧曲泉连涓。","高岭既郁律，遥林复绵芊。","霏霏阴涧合，蔼蔼阳条鲜。","暖日丽韶石，绪风流浈川。","周览盈徙倚，长谣缔延缘。","愧匪尚平适，久钦康乐贤。","自非恋嘉苗，曾是怀灵荃。","阰兰已堪结，洲莽亦可搴。","美人迥不至，何由布中悁。","日夕空伫立，咏言白驹篇。"]},{"t":"泛浈江至脩仁水寻范云饮水赋诗处","f":"五言古诗","c":["陆陟心苦艰，江行意超忽。","扬舲恣击汰，理榜欣乘筏。","昔闻范内史，于焉自怡悦。","赋诗散郁陶，饮水辨清淈。","今游属暮春，远放遵南粤。","三枫睇已遥，五渡嗟应没。","爰思雊雉驯，尚想甘棠茇。","命驾税山椒，弭盖依林樾。","明霞带远峦，瑞霭屯崇碣。","樊薄粲朱樱，原陵苞绿蕨。","感兹时物迁，惧尔芳馨歇。","代更道岂殊，事往迹空揭。","凄凄怀古吟，心赏不可越。","鸱夷迥泛湖，子牟怅怀阙。","采兰向中洲，眷此何由达。","沿洄发棹讴，愉乐陶嘉月。"]},{"t":"秋林为朱仲熙赋","f":"五言古诗","c":["陶令中林居，羲皇夙遐慕。","灵境谐清赏，冥里契良晤。","昊天一何高，俛仰感晨暮。","祝融解炎鏕，蓐收肃凉辂。","清商谷响动，皓魄川光布。","云雁薄层霄，山猿啸零露。","鸣蛩稍已希，委叶满涧户。","对景谢繁丽，乐辰切冲素。","寄怀齐物篇，颇拟思玄赋。","志士自苦心，幽人有贞度。","年欣松柏荣，情比金石固。","峨峨壶公山，千龄仰脩步。"]},{"t":"吴而待见过","f":"五言古诗","c":["夙昔敦情盟，结交展情素。","乡国盛才贤，夫君美无度。","词华灿锦舒，论难欻湍赴。","析疑发蔀蒙，嗜古薄章句。","秦人篆隶工，楚史丘索富。","披衿共一时，迈往殆独步。","伊余事幽讨，弱植寡所遇。","与君同舍居，缱绻构良晤。","声应慰莺求，道远惭骥附。","已传五君咏，颇忝七子赋。","三载怅离群，分飞阻欢趣。","君淹北海鲲，余困西江鲋。","难逢骏骨招，反受蛾眉妒。","兹晨献岁初，忽已青春暮。","君从海上来，访我林间户。","纚纚语夜深，佳期怆难屡。","移舟对尊酒，江烟足游豫。","葱茜映回汀，葐蒀杂芳树。","欣赏入冲襟，微言得新悟。","终宴时未几，戒途忽西鹜。","彼美眇何之，沿洄不能溯。","怦怦感斯别，恻恻冀有遇。","愿言崇明德，勉副心所慕。","述旧遂成篇，因之报亲故。"]},{"t":"游江门寻陈徵君隐居","f":"五言古诗","c":["萧晨戒征舻，薄戾江门涘。","仰瞻碧玉楼，言访白沙里。","白沙遁世人，蚤脱朱门屣。","玉署重徵君，金闺谢惇史。","归来掩衡扉，被褐聊隐几。","耕同石户农，道访襄城子。","抠衣已龂龂，入室方济济。","歌商出金石，奏雅中宫徵。","馀韵今百年，精庐有遗址。","宅犹诸葛存，台拟灵光岿。","藤留处士蓑，苔绝幽人履。","空言炳丹青，清风激顽鄙。","嗟予愧斯文，未免乡人耻。","饮河泳道馀，高山徒仰止。","茅茨空寂寞，弦歌恍盈耳。","依依郑公乡，千秋表南纪。"]},{"t":"秋怀四首 其一","f":"五言古诗","c":["浩浩沧溟波，萧萧枫树林。","凉飙一夕至，岁序已骎寻。","苕荣委金令，和响收阳禽。","出闻蟪蛄鸣，入听蟋蟀吟。","顾瞻陇坂上，白露忽已深。","触物易为感，忧人怆悲襟。","万恨痛在目，辀张间辰参。","愤切深情恸，忧思谁可任。","往者长已矣，来者方自今。","悠悠宇宙间，谁为相知心。"]},{"t":"秋怀四首 其二","f":"五言古诗","c":["落日照古原，步出北门山。","西京昔云季，墟墓多遘患。","取土已过坯，摧墉无遗磗。","珠襦达襚道，玉椀出人间。","荆棘生颓陇，狐兔穴幽埏。","樵牧踯躅歌，便房宁复完。","佳城何郁郁，今见白日寒。","南武雄一州，今不保重泉。","千秋万岁后，人事空长叹。","恻怆雍门吟，泪尽不能言。"]},{"t":"秋怀四首 其三","f":"五言古诗","c":["出门万里行，少小怀远志。","朅来婴祸患，况感清商气。","块处哀愤盈，行吟百忧至。","破涕不成欢，在心难弃置。","飞蓬恋本根，零落将安寄。","已知昨日非，终身竟谁是。","凝霜被草莱，清露沾兰蕙。","金石亦可销，繁华难久恃。","颓魄无复圆，驰晖倏惊驶。","勉副平生怀，康途策良骥。"]},{"t":"秋怀四首 其四","f":"五言古诗","c":["洪钧播万物，元气囿群形。","日月递照灼，岁时代迁更。","四十冉冉至，将来耻脩名。","道远期力及，晷刻不暂停。","先正有遗言，拳拳宜服膺。","雌守信抱朴，天全在遗荣。","自得澹无为，夸父岂足矜。","翩彼黄鹄飞，宁与燕雀争。","少年成丑老，朝槿陨夕英。","自非王子乔，谁能阅千龄。","高楫餐霞客，延年学长生。"]},{"t":"田舍二首 其一","f":"五言古诗","c":["结庐向东皋，僻居绝尘鞅。","夙晨巾我车，蓑笠时独往。","禾苗动绪风，田畴亦已广。","秉耒良自勤，烹葵事晨饷。","烟火欢新炊，浊醪洽邻党。","百年尚悠悠，所愿谐心赏。"]},{"t":"田舍二首 其二","f":"五言古诗","c":["人事夙昔寡，林野多欢娱。","衣食计不免，山泽久已癯。","屏迹展奇兴，茅庐带荒墟。","墙下植桑柘，蚕月得所须。","未谋千日酒，且有三岁畬。","缅怀古田舍，终欲从君居。"]},{"t":"岁除閒居作二首 其一","f":"五言古诗","c":["閒居岁已除，物役免纷逼。","月穷会玄枵，昏中丽东壁。","偃仰一室内，乱帙理书籍。","家无儋石储，乐分敢求益。","中馈进盘蔬，浊醪会亲昵。","所欣怡母颜，馀者不足惜。","来日幸自多，去日岂复得。","一觞且共持，笑语陶今夕。","山楹植幽兰，芳馨未云息。","素志良独勤，冲襟稍能适。","人爵非所营，勖哉慎明德。"]},{"t":"岁除閒居作二首 其二","f":"五言古诗","c":["遵养顺时晦，逃虚寡尘鞅。","倏忽兹岁周，荏苒华年往。","卉木自衰荣，阴阳递消长。","蓬室诚寂寥，悠然寄心赏。","久已谢交游，稍足供俯仰。","出门聊骋望，天地一何广。","曾身戒深省，孟气贵善养。","蒙庄托逍遥，鲁连事倜傥。","平生晞古心，微尚不可枉。","贫贱良亦难，富贵岂能强。","履运悟玄言，沂风继幽响。","愿释区中缘，永协沧洲想。"]},{"t":"游西樵山","f":"五言古诗","c":["弱龄诵图经，雅志爱丘壑。","良朋订远游，名山赴幽约。","杪秋天宇清，始至谐夙诺。","心迈易跻攀，步健轻岑崿。","晓行陟诸峰，周览淩峻削。","皛皛游氛敛，霏霏寒气薄。","霜木耸巘高，风泉洒空落。","迹绝洞疑扃，云攒岫如幕。","搴萝上松门，临坪出烟阁。","桂丛隐可招，暂托幽人乐。","地远声总销，谷虚神更跃。","眷言怀昔贤，来者视犹昨。","窅默得天游，何用耽人爵。","毕婚非达言，从此访灵岳。"]},{"t":"过乌利岩寻乌利仙修炼故迹","f":"五言古诗","c":["仙灵有窟宅，瑶木带岩扃。","我行访名山，始识乌利名。","万里从罡风，飘飖云中行。","借问此何所，乃是真人庭。","餐霞结灵气，晞发朝阳升。","羽化入帝乡，倏忽见云軿。","愿言从之游，斋洁练我形。","纵身天汉上，谢彼尘世荣。","玄洲邈何在，咫尺昆崙城。","从此游无穷，延年以长生。"]},{"t":"送梁思伯二首 其一","f":"五言古诗","c":["神鲤乘波化，翔鶤待风游。","丈夫志四海，岂能甘一丘。","骊驹驾在门，我友适燕州。","殷勤挈尊酒，饮饯城南楼。","顾瞻两鸳鸯，将离难久留。","匪无新相知，孰如故绸缪。","行役不可辞，道路非所忧。","赠子古别离，佩子双吴钩。","勖哉树芳绩，佳期岂无由。"]},{"t":"送梁思伯二首 其二","f":"五言古诗","c":["晨起秣征马，北上遵太行。","前瞻督亢亭，俯见军都场。","皇居槩太清，宫阙俨相当。","汉家徵茂异，缨弁群趋跄。","子去蚤上书，青云方激昂。","公车旦夕召，佩玉承恩光。","睇彼黄鹄飞，霄汉纷翱翔。","何当假修翼，引领增慨慷。"]},{"t":"吴明卿住白鹿洞寄怀一首","f":"五言古诗","c":["余昔过湓城，严冬滞风雪。","望山魂爽飞，泥潦不可越。","石镜思一窥，松门未由谒。","将巢庐阜云，空弄蠡湖月。","归来岁十奔，风壤殊楚粤。","缅怀白鹿踪，世往声华揭。","榛莽掩精庐，云霞护缃帙。","硕儒遗教存，弦歌满岩穴。","有美山阿人，避諠得栖拙。","聆涧锵鸣璆，扪崖引藟葛。","身将山泽癯，道以沉冥悦。","场藿谢嘉招，烟萝企前哲。","仰止行可跻，独往志孰辍。","折麻寄深衷，所思在天末。"]},{"t":"任嚣城","f":"五言古诗","c":["周道荡无网，秦政急纷挠。","闰位讵久居，阳九厄洪造。","迅飙疾燎原，华域横流浩。","咸阳羸为吕，箕敛半枯槁。","三百饰离宫，观海临驰道。","刻石方颂勋，倏载沙丘鲍。","南尉志规鼎，绝岭闯江坞。","设险百雉成，割据谁免讨。","洛食卜涧瀍，周京合丰镐。","奠极镇八鳌，坤灵资富媪。","岂凭南海僻，竟授龙川宝。","羁縻剖内符，僭窃系左纛。","豫往骤悲来，万化随电扫。","历尽峻垣颓，运革崇墉倒。","萌隶营薪藋，离离见秋草。","千龄垒可培，委土存师保。"]},{"t":"南越武王赵陀墓","f":"五言古诗","c":["故国多荆榛，累累带丘陇。","北眷天井冈，莫辩尉陀冢。","缅惟称制时，中原已云滃。","闭关并扬粤，画甸赋秸总。","闽蛮渐东羁，瓯骆尽西拥。","黄屋并汉仪，威边自尊宠。","陆生隃岭来，班轮再南軵。","奉藩谨上书，正极众星共。","桂蠹贡虽入，湟溪道仍壅。","志远蒿里催，运往朝台耸。","黍苗被隧涂，麇鹿交町疃。","金凫幸不飞，银海岂能涌。","登垄踯躅歌，空有牧竖踵。","谁为雍门弹，千秋泪汹汹。"]},{"t":"虞翻园","f":"五言古诗","c":["仲翔出会稽，材本东南美。","注易思深湛，裁书岸魁垒。","酒失获微愆，仙论积深憝。","一落交南州，蛾眉奈谗毁。","讲授颇窥园，苛林莳华蕊。","曲池今亦平，高台昔曾岿。","海滨遂弃捐，霸略岂不伟。","赐环竟无期，怀璧果何罪。","青蝇终吊客，斑竹歌山鬼。","拟招湘水魂，请慰延陵诔。"]},{"t":"刘王郊台","f":"五言古诗","c":["五季乱豺虎，历数未有归。","南汉骄自王，帝粤保南陲。","白龙表上瑞，圜丘祀苍祇。","乾亨首纪元，升坛列金枝。","荐德羞币玉，涤牲黩郊牺。","上帝肯居歆，祝史虚陈辞。","君昏社已屋，废台委山陂。","燔柴不复登，茂草鞠荒基。","鲁侯昔僭郊，已叹周公衰。","甘泉与雍畤，秦汉多陋仪。","矧兹蛟蜃国，禾黍岂足悲。"]},{"t":"菊湖","f":"五言古诗","c":["勇退返初服，澄心鉴天湖。","湖滨颇有菊，涧上亦有蒲。","考槃结蕙帐，捐佩思蒪鲈。","明公昔膴仕，赤舄逊硕肤。","裘马临淮海，图书归益都。","白麻竟不起，台衮何为乎。","夷尚且盍归，辞相千载孤。","山颓木已稼，西州恸行途。","江表复何赖，邻屋将瞻乌。","古礼重祭社，湖草今渐芜。","寒泉荐秋英，终古怀生刍。"]},{"t":"罗浮","f":"五言古诗","c":["丹丘峙海隅，灵岳标云际。","蓬莱一岛浮，合影发灵秘。","日观齐石楼，朱明通地肺。","天鸡始一鸣，扶光彻幽蔽。","仰瞻控鹤天，俯瞩轩鸾地。","罡风扬扶摇，轻举非人世。","余本餐霞人，弱岁窥山笥。","言归白玉京，将谒青阳氏。","璿房暂可栖，玉树犹堪翳。","洞中拾朱草，日暮倚苍桂。","守一观我心，中夜存元气。","殷勤绿字篇，重订碧山契。"]},{"t":"太霞洞","f":"五言古诗","c":["岭南总百粤，清淑夙鸠凝。","兹山罗浮麓，支分自南衡。","交广古邹鲁，风序蔼冠缨。","哲人今挺生，钟彼川岳灵。","餐霞隐中洞，白云为之扃。","白云时出山，霖雨四海盈。","归来保太玄，飘飖入朱明。","曾城望不远，导我升天行。"]},{"t":"春中田庐作","f":"五言古诗","c":["卜居南冈下，榛曲带平津。","桑麻二三里，墟落八九邻。","前村夜来雨，晨兴事耕耘。","日夕荷锄归，浊酒燃荆薪。","掩户读我书，自谓羲皇人。","怅望白云交，悠悠颍川滨。"]},{"t":"首夏病起出南村田庐迟潘少承","f":"五言古诗","c":["负疴谢来往，春尽开荆扉。","邻翁念童雉，炊黍馌田归。","蚕幼桑叶尽，麦熟野雉飞。","耕织日可就，而我生计非。","开卷得心赏，千载非今时。","幽居无世缘，微君孰相知。","竹陂有来径，浊酒宜共持。","任真穷百年，已矣甘息机。"]},{"t":"四月八日观浴佛","f":"五言古诗","c":["心猿持不竞，意絮飞初定。","热恼除焦煎，贪嗔戒急缮。","皈依趋道场，圆照启禅镜。","兹晨方大寤，天竺降祥庆。","丈六挺金身，说法众生听。","苦行曾六年，沐浴竹园静。","罽宾留象尊，波斯转轮正。","兰汤俨若存，螺发新逾瑩。","礼罢鹫山钟，讲馀鸰堂磬。","沙弥结夏时，正可求自性。","清凉五罪销，寥廓六尘净。","以此度世人，平等超三乘。","请谢八关斋，忏悔已恭命。","至理归无生，悠然发高咏。"]},{"t":"感寓四首 其一","f":"五言古诗","c":["焦明不知凤，斥鴳不知鹏。","高驾肃通衢，下笑蓬累行。","君看叔孙氏，孰与鲁两生。","笑傲岩穴下，焉知棉蕝成。","万世在吾后，传者非公卿。","我心已尘石，请谢世上名。"]},{"t":"感寓四首 其二","f":"五言古诗","c":["起坐每达旦，忧来不遑宿。","按剑惜隋珠，刖足羞荆玉。","张仪不遇还，反受苏秦辱。","方齐击睢时，岂识为张禄。","尘埃谁免侵，天运有来复。","升沉久已知，岂就季主卜。"]},{"t":"感寓四首 其三","f":"五言律诗","c":["尺木不可量，斗水不可觞。","孟尝一言听，足高而志扬。","所以鲁连子，长往东海旁。","弃之纳履去，贫贱庸何伤。"]},{"t":"感寓四首 其四","f":"五言古诗","c":["旷望车马途，名利争鸿毛。","缤纷市中子，长揖交钱刀。","时来有钟鼎，命达称贤豪。","摩肩仍击毂，倾辀常所遭。","虿尾怀螫毒，讵能解天韬。","炯鉴岂在远，膏火不可逃。","柱下识溪谷，汉阴惭桔槔。","愿从千古士，尚志潜蓬蒿。"]},{"t":"寄陈士鹄","f":"五言古诗","c":["别促苦日多，心长诉江永。","嗟予方介居，靡使不可聘。","夫子茂徽音，嘤鸣协声应。","朗月恋携手，双襟一何净。","离群倏二周，曷日聆新咏。","临川怀所钦，欲往谢疲病。","君乎倘相从，引领候荒径。"]},{"t":"户部黄公祠","f":"五言古诗","c":["沧溟汇东流，五岭雄南纪。","斗牛光曜祥，秦汉人文起。","黄公绝代贤，磅礴钟灵委。","权奇产骥材，仁厚歌麟趾。","弱冠腾声华，颖脱从此始。","熙熙孝宗朝，赐第金门里。","抟风薄层霄，逐电绝九轨。","文章足润身，黔黎正资理。","试吏更海邑，搉商届江汜。","飘飘江汉谣，蔼蔼闾阎喜。","尸祀畏垒民，吏隐漆园子。","风云会紫庭，日月开朱邸。","郎署密含香，使辀远传棨。","武宗肃南巡，督饷先驱使。","方纾扈跸劳，遽达悬车旨。","明农即故山，齐物吟秋水。","中兴论旧功，上德尊耆齿。","赐金贲衡门，扶杖瞻宸扆。","诗成寄幽怀，酒进介繁祉。","徵车道尚迟，撤瑟事长已。","慇勤有道碑，悽楚延陵诔。","乡人吊墓钦，过客式闾企。","阖棺评月旦，祭社列簠簋。","景行仰俊民，弦匏播休美。","回首于氏门，应名郑公里。","家传小戴经，世秉曲台礼。","煌煌光我明，芳猷自天启。","西望龙山云，临风荐兰芷。"]},{"t":"赋得蓬岛长春寄中丞林公","f":"五言古诗","c":["蓬山冠三岛，瀛海渺八荒。","清虚敞神居，鸾凤相翱翔。","黄金为宫阙，白玉为室堂。","琼蕤披藻搆，珠树列绮窗。","扣阈彩烟飞，榜题丹曜光。","灵葩丽曲戺，异药纷翠房。","五芝浥露色，六草迎风香。","中有神仙人，逍遥绿发长。","服之丹霞衣，系以紫云裳。","骖虬谒上帝，羽盖腾龙骧。","徘徊阊阖间，嗽吸沆瀣浆。","拜受三真术，永保四明方。","从此游泰清，延年寿无疆。"]},{"t":"放歌行","f":"古风","c":["恻恻复恻恻，四座长叹息。","劝君绿酒放我歌，汉室方隆似磐石。","汉初定鼎河陇头，长安宫阙似云浮。","烟花甸服三千里，锦绣山河百二州。","赤帝之子为汉祖，四叶神孙称帝武。","泰山梁甫盛礼仪，宝鼎芝房传乐府。","欲麾羽骑靖宛胡，先遣楼船出齐鲁。","此时佳气何郁哉，复道层楼对凤台。","承露东连三殿矗，相风南向九关开。","九关鸡鸣天欲白，咸阳春满千人宅。","使者横行半凿空，书生上奏皆驰画。","北伐齐分五道军，西来尽召诸侯客。","待诏时登金马门，酣歌晚聚铜驼陌。","卖珠小子宴北宫，牧豕孤儿揖东阁。","柏梁台中盛赋诗，玉堂殿下承恩泽。","承恩更有过侯王，赐第开门近建章。","校猎常驰射熊馆，遨游多入斗鸡场。","庭中列侍羽林士，门下传呼谒者郎。","羽林谒者通朝籍，剑客庖人沾玉食。","叱咤吹嘘有鬼神，弹冠结授生颜色。","吁嗟汉室盛衣冠，寂寞何人独考槃。","岂无旅邸空书牍，尚有公车未拜官。","慷慨为君歌一曲，出门何处望长安。"]},{"t":"阊门行","f":"古风","c":["朝望吴都城，夕入吴都郭。","目送三江流，心怀五湖乐。","吴都郭外阊门西，阊门女儿娇欲啼。","锦屏朱户唱桃叶，青丝玉壶唤客提。","皋桥泰娘年十七，起舞持杯向人泣。","揽环掩袂不胜情，自说吴都异前日。","忆昔吴王都此邦，馆娃宫中兰麝香。","三千珠翠空成队，十二金钗谩作行。","梧桐园中梧叶秋，西风飒飒吴王愁。","黄金白璧竟何在，昨日红颜今白头。","可怜不特繁华事，富贵看成草头露。","故国山河今已非，姑苏台前鹿麋路。","劝君对酒莫言归，华堂一曲白纻衣。","千年往事如流水，且向尊前醉落晖。"]},{"t":"游虎丘夜至枫桥寻陈复甫不见赠同游郭郡博","f":"七言古诗","c":["江南野客未归去，尚爱吴中奇绝处。","朅从白马涧边行，又向长洲苑西赋。","禽逐桓王墓道田，马嘶伍子祠门树。","西来暂憩虎丘山，玉霤金堂偶一攀。","秋清檞叶满岩户，日静苔藓封柴关。","闻昔吴中全盛日，阖闾城在江湖间。","王图寂寞暮云散，伯气销沉秋草斑。","高坟已无壮士守，鱼肠扁诸何日还。","兹游幸遇清时乐，尊中有酒良非薄。","为访周南太史来，况逢博士先生约。","剑池亭下共分题，石井泉边更深酌。","赵曲银筝向水调，越歈锦瑟临风作。","须臾月出东山头，乘兴更寻招隐客。","闻道山人湖上归，解衣夜向枫桥泊。","欣然驾我木兰舟，西风瑟瑟飘绮裘。","波光浩渺白露冷，山色惨淡玄鹤秋。","手携玉笛吹月下，高云不动江水流。","云深水远望不见，芙蓉杜若增离忧。","蒪鲈信美岂不恋，沧洲廊庙吾何求。","明朝万里各有别，为赋吴趋子夜游。"]},{"t":"约游西湖不果独归金陵寄越中诸故人","f":"七言古诗","c":["前日吴江与君约，扁舟共载西湖乐。","六桥烟里纵兰桡，三竺云边望芝阁。","舟中卧病生离忧，我归金陵君越州。","南屏武林不可见，江波渺渺令予愁。","忆君舟系净慈寺，岳王坟下生秋思。","有美湖山足逸游，伤心定赋江南事。","眼中应是故交稀，谢客风流白纻衣。","遥知不是沧洲客，芸阁石渠迟尔归。"]},{"t":"泰山歌寄王公仪","f":"楚辞体","c":["峞乎岌哉，泰山岩岩齐鲁东，天孙主治名岱宗。","拔地一万八千丈，但见瑶台琼阙淩苍穹。","石道屈曲十八盘，然后天门日观开晴空。","蛟螭作梁渡东海，三更日射扶桑红。","上则九峰八峪四崖六岭，其下汶漯济涓流汹汹。","白鹤皎皎玉女侧，黄河水与银汉通。","仙之人兮驾玉虹，珊珊环佩摇青葱。","俯拾冰玉采金碧，侗侗之珠万颗纷玲珑。","大夫松树倚天半，碑篆犹记秦皇封。","登仙台前炼丹液，明月嶂下翻芙蓉。","行云肤寸触石起，倏忽雨电八极同。","雁飞冥冥不敢过，登高一笑窥洪濛。","王夫子，夙昔玉皇吏，曾宴幔亭峰。","紫髯白面烟霞气，脱挽请缨游侠风。","朅来献策阊阖殿，布衣谒帝蓬莱宫。","绛灌不容长太息，谪向江海随飞鸿。","悠悠白日未回照，鞭麟东去寻盖公。","谪仙自古才有数，操椎博浪沙，射书聊城中，差足纵横一代雄。","君不见安期先生颜如童，鹿走曾亦千重瞳。","翩然玉舄渺安在，阜乡一去今无踪。","丈夫历落在天地，岂使泰山乔岳空巃嵷。"]},{"t":"忆昔行寄邓山人因怀王应瑞龙子文","f":"古风","c":["忆昔学书剑，北游赋骊驹。","逢君大庾岭，倾盖城南隅。","春风三月下章水，看花直过金陵市。","金陵风雅盛文儒，汉室西京恐未如。","东阁尽闻开相府，布衣不遣待公车。","归来抱策南海曲，两举乡书未蒙录。","落日羞过醉尉亭，闲云独卧王官谷。","躬耕下噀岁全荒，垂钓中洲乐偏足。","相逢杯酒日纷纷，四海知心独有君。","君今八十吾非少，别后音书那可闻。","王生薄宦离家远，涿邑行人未应返。","龙子留都复上书，南来不得寄双鱼。","梅花岭下空相忆，铁汉楼西横浦驿。","时来握手定有期，归鸿为我传消息。"]},{"t":"送王参戎赴西府","f":"古风","c":["君不见西瓯自昔蛮夷国，谷永招降拓疆域。","郁林千寨拜衣冠，乌浒万家成部落。","后来征剿徒纷纭，肉食何人建长策。","将军年少事文儒，早向桥边受素书。","敕下九重分玉虎，府开五筦给铜鱼。","楼船西向浔州去，直到韩公断藤处。","诏书节制两江兵，武靖楼头画角鸣。","夜火船归武宣县，秋风马跃伏波营。","辕门置酒排高宴，幕府羽书速飞电。","霜满牙旗冻不翻，月明刀斗严如战。","四姓徭民罢鼓鼙，五屯獞户投戈剑。","将军此去策勋名，伫看飞书报玉京。","诸蛮从此应安堵，望见西瓯乐太平。"]},{"t":"残岁行","f":"七言古诗","c":["北风残岁夜不止，茅屋哭声愁满耳。","野人篱落少炊烟，时向山樊拾荆杞。","连年荒歉困征求，富者卖田贫卖子。","府帖催科减折收，县家督责严驱使。","左江征戍半未归，老稚何人托生死。","陇上方嗟旧业荒，仓中催纳新粮起。","里胥乘势横索钱，升斗不容相汝尔。","孤婺亦遣卖丝麻，免使呼号怨乡里。","昨朝复闻贼近村，贾客渔翁五路奔。","白昼鸣锣向墟市，黄昏上屋攫鸡豚。","吁嗟往岁多馀积，今岁辛勤饭不得。","父老犹思弘治时，乐岁官清无盗贼。","南国书生破褐寒，临风三叹益悲酸。","尺书不得干明主，何日苍生有环堵。","迎新履庆在明朝，残岁萧条泪如雨。"]},{"t":"南岳篇送何衡州","f":"古风","c":["荆南万里云盘错，巀嶪衡山号南岳。","职方尽入楚人墟，舆地分封麋子国。","此山上应翼轸星，仰睇苍苍入紫冥。","天边返照开云梦，雪后飞花满洞庭。","祝融峰下仙人障，紫盖朱陵复东向。","柱隔芙蓉一万重，碑藏岣嵝三千丈。","玉牒文章经几秋，玄夷使者故相留。","湖上只今通汉水，湘东自古建衡州。","衡州太守黄门客，赤墀青琐承恩泽。","献纳三年作近臣，尚方剑借雷霆侧。","出守专城五马车，十郡诸侯总不如。","黄堂初布行春令，紫禁犹怀谏猎书。","寇恂谁借归河内，龚遂当年留渤海。","湘中父老西上书，愿得襜帷更三载。","此日驱车朝五云，人识衡州旧使君。","千官拜舞冠簪列，三殿追趋鹓鹭群。","已道虞庭咨岳牧，更看汉室分符竹。","诏下何时远赐金，徵还旧省新鸣玉。","君不见望之雅意归本朝，入补公卿事不遥。","好将勋业齐南岳，阊阖明恩在九霄。"]},{"t":"夜听谭七吹笛因忆金陵张六","f":"七言古诗","c":["谭君置酒烧银烛，为我停杯吹紫玉。","正逢兰佩赠佳人，何事竹枝奏离曲。","数声袅袅斗柄低，断雁哀猿入耳啼。","霜满洞庭悲落木，萤流长信恨空闺。","倚阑只诉君心苦，别客听之更悽楚。","此夕同游石井山，明朝独下松陵浦。","忆昔江东落魄行，张郎视我犹弟兄。","春园袅娜闻花下，夕馆参差醉月明。","六载分携别离久，何人共把长干酒。","千里音书不可来，梦中时见白门柳。","槯藏今已非少年，弹铗哀歌瓮牖边。","慵书班氏谁曾问，学剑相如只自怜。","看君暂得同欢笑，犹胜金陵隔烟峤。","窈窕离愁不可挥，请君三弄江南调。"]},{"t":"八排山行赠曾大夫抚徭","f":"古风","c":["君不见八排山，黄茅萧萧高入天。","军寮马箭贼满野，戍兵夜走烧坪下。","阴风吼地时吹角，桂阳城北狼星落。","左里先飞校尉书，连山已建中军幕。","大夫白晢微有鬒，司马行军使者车。","不妨羊祜常裘带，由来却毂事诗书。","中军策应亲戎马，复领蛮兵号横野。","纵金伐鼓羽旗飞，白日欢呼奏凯归。","谁知兵后风尘起，徭落千人向湟水。","征戍应含玉箸啼，甲兵未拟银河洗。","大夫下令复专征，玉勒银鞍出郡城。","慷慨聊将单骑去，艰难岂惜一身行。","群徭罗拜马前谒，尽遣归农解金甲。","八排岭下听铙歌，从此征夫免荷戈。","勒铭思向韩山石，饮马期归桂水波。","功成已在班师后，幕府何时方草奏。","男儿本自树功名，志士何曾怀印绶。","高节悠悠未策勋，誓将肝胆报明君。","汉家卫霍论功日，令人却忆李将军。"]},{"t":"夏太常画竹引为冯用唯赋","f":"古风","c":["冯郎慕竹世希有，桑梓园中攀玩久。","云是先人旧所题，手泽犹存言不朽。","今晨访我芙蓉溪，玉轴青绫手自携。","开图忽见夏卿画，挂向堂中色惨悽。","吁嗟此幅不易得，败素残缣俱可惜。","蜩蝮蛇蚹古所难，坡陀沙屿今虚忆。","雾干霏霏洒不乾，风梢瑟瑟暗生寒。","鹧鸪啼处雨声急，帝子愁时春日残。","修篁密筱阴翠满，咫尺由来千里远。","西风何处洞庭秋，白云回首潇湘晚。","君不见文洋州，筼筜谷中谁可俦。","渭滨千亩有馀地，彭城一派无奔流。","又不见萧协律，幽姿远思谁能匹。","天竺寺前烟杳冥，湘妃庙口云沾湿。","萧郎华彩已彫零，文守丹青漫有名。","黄筌赵頫不可作，千载坛场惟夏卿。","冯郎对此山轩下，琼玖琅玕宁论价。","玉树应留彩凤栖，沧溟会见神龙化。","君家世德重当时，卫武风流淇澳诗。","青霄更拂三花树，湛露同沾万岁枝。"]},{"t":"送别曲","f":"七言律诗","c":["朝汉台前山矗矗，客子晨餐入车宿。","鸡声十里送君行，劝饮尊前歌别曲。","远游何处长安道，策马东风入关早。","妾身愿作双车轮，日夕随君辗青草。"]},{"t":"秋夜吟","f":"古风","c":["独夜一沉吟，妾意比君深。","别时春未尽，别后岁将阴。","岁将阴，芭蕉写恨鸾何去，豆蔻缄情鲤亦沉。","鲤沉书不到，虫响露方侵。","独宿不堪况今夜，边鸿听尽无归音。","霜天如月房如水，冷光射灯灯欲死。","可怜犹及梦中逢，回首征途八千里。"]},{"t":"美人叹","f":"古风","c":["妾家长安陌，深闺畏人识。","耻同宋家东，羞过李城北。","照日爱同心，迎风思比翼。","琴瑟向户弹，机杼当窗织。","织成锦字正怀春，弹罢金垆待薰夕。","不分朝霞洛浦中，岂随暮雨巫山侧。","对镜时矜绝代容，临池自爱倾城色。","倾城绝代人罕知，三五二八怜芳姿。","幽兰颇诵美人赋，彤管闲吟静女诗。","正当二月繁花日，已见三星在户时。","匏瓜织女几回看，世无蹇脩良独难。","皎皎轻烟停水际，娟娟明月出云端。","纵然台上逢萧史，愿向山中待伯鸾。","讵惜盛年鸳偶少，自怜中夜凤楼寒。"]},{"t":"鹤舒台吟赠邝子乾","f":"古风","c":["千岁鹤，万丈台。","台崔嵬，鹤毰毸。","仙禽已入青霄去，昔日翩翩安在哉。","鹤不来，台独在。","忆霓裳，思羽盖。","手把芙蓉不可招，飞光缥缈云霞外。","君居台下今几年，练玉餐霞骨欲仙。","桂花松子时时满，岩瀑山烟日日悬。","君不见东海安期闲浩荡，阜乡亭侧长相望。","行留玉舄更何时，邀余同向青霄上。"]},{"t":"赠别梁六入京","f":"七言古诗","c":["梁君善画兼善诗，渡江别我游京师。","是时九月霜已落，河桥把袂无柳枝。","君为太师之孙子，胸中万卷蟠经史。","十载閒居隐旧山，一朝徒步干明主。","马卿未遇家故贫，狗监片言能致身。","上林游猎不足数，早为君王奏大人。"]},{"t":"海上谣","f":"古风","c":["我昔何所游，鼓柁祢衡鹦鹉洲。","今日是何日，天涯飘泊沙棠舟。","举头日近长安远，浮云万里令人愁。","天吴出没摇九首，连天白浪牛声吼。","南海庙前枫树青，帆飞失却扶胥口。","早潮东下暮潮还，歌罢扣舷仍饮酒。","醉归越王城，北望越王台。","越王昔日繁华地，只今零落生青苔。","贵亦不足羡，贱亦不足憎。","乘桴者何人，而有万古名。","卢敖汗漫应相待，欲破长风海上行。"]},{"t":"苦贫吟寄赵仲履","f":"七言律诗","c":["廉士苦贫贫不苦，愧乏肥甘奉慈母。","儿痴粝食朝不啼，妻瘦鹑衣夜犹补。","古来贫者有原生，异世与尔为弟兄。","故人结驷能相访，为听歌商金石声。"]},{"t":"十四夜侍家慈楼上玩月","f":"楚辞体","c":["去年待月雨青楼，忆母离居海上洲。","今年待月宝翰楼，奉母闲登楼上游。","四方无云海生色，镜光将满升东璧。","长河韬映列宿微，昨夜那能似今夕。","有酒有脯，儿女罗陈。","母子兄弟，岂伊异人。","满酌千岁卮，寿我北堂母。","弟能吹笙兄击鼓，如何不饮歌且舞。","君不见天上十二楼五城，黄金宫阙白玉京。","婆娑桂树植其侧，中有仙人岁长生。","长生兮久视，寿母兮孙子。","天伦乐事乐何如，曲肱之外浮云耳。"]},{"t":"喷玉岩长句","f":"古风","c":["天泉百道下晴潭，淙淙西岭霾烟岚。","跳珠翻雪不知数，独称喷玉千丈岩。","喷玉天泉水，源从山上起。","倏看闪电来，半在青天里。","洒流横激湿行云，溅沫时惊过鸟群。","狂飙万里吹难断，皓月三更影不分。","初疑白鸾在树出，更疑宝剑倚天立。","寒气飒飒猿狖号，冷光泠泠山鬼泣。","左潈右射洗青空，崩崖快泻双石谼。","几见嵚崟下赤日，遂令澒洞来悲风。","曾闻天台之南雁宕北，绝巘飞泉削苍壁。","偃盖低飘□□松，明霞侧映五色石。","匡庐九叠屏风张，银河倒挂三石梁。","香炉郁葱吐云散，瀑布夭矫惊龙翔。","台山庐岳遥相望，我昔扁舟恣长往。","玉岩之水澄我心，归来福地何萧爽。","漱石枕流奚所营，朝餐金液暮赤英。","仙人招我彩云里，便御茅龙朝太清。"]},{"t":"超然台放歌","f":"古风","c":["登高作越吟，倚剑歌转哀。","木叶纷交下，征鸿亦徘徊。","西樵之游同数子，半酣太叫超然台。","此时万里飞蓬转，但闻悲风萧萧天上来。","绛宫朱阙远明灭，洞天福地空崔嵬。","仙乎仙乎不可见，浮丘洪厓安在哉。","笑骑鸿鹄过琼岛，便应从此归蓬莱。","蓬莱方丈是何处，白云袅袅帝乡去。","天外虚传二凤楼，人间岂见三花树。","云车风马自千秋，旦夕蟪蛄何用愁。","君不见周太子，缑氏山头鹤来去。","又不见轩辕君，鼎湖水上龙缤纷。","浊世之居若脱屣，人生胡为在尘滓。","任也江湖落魄生，形骸肮脏无所成。","往来每拟淩云赋，梦中时作升天行。","大鹏或被斥鴳笑，平生禽尚吾同调。","布袜青鞋淩绝峤，临风更向蓬池啸。"]},{"t":"东南叹","f":"七言律诗","c":["东南夷寇经年月，吴越丁男厌骸骨。","尚书持律保孤城，赤县苍生日流血。","四方遣使募材官，椎髻花蛮拜将坛。","鸣呼此恨终何已，夜向星前把剑看。"]},{"t":"北风谣","f":"古风","c":["玄冥号怒海若愁，天地惨淡黄云秋。","三江波涛尽汹涌，五岭草木长飂飗。","燕山层冰蓟门雪，北风吹落轩辕丘。","猿狖昼啼，鸟雀啁啾。","白日无色，山鬼幽忧。","夜中何处吹觱篥，戍妇听之双泪流。","念君此去戍万里，石城壁立东海头。","男儿出门誓报主，倭奴未灭为国仇。","边头明日有远信，封书更寄金锁裘。","金锁裘，不胜束。","锦字书，不能读。","楼船戈甲几时回，北风忍听军中曲。"]},{"t":"登高丘而望远海赠梁岳","f":"古风","c":["登高丘，望远海，冥冥海风生白波，十丈汹涌冰嵯峨。","有似瞿唐下三峡，篙工舟子不敢过。","是时严冬十一月，雨霜吹作燕山雪。","四野苍茫鸿雁饥，枯树半死木叶脱。","嗟君萧飒风沙颜，冒寒苦欲趣入关。","云涛不见西洲渡，咫尺那分北郭山。","君不见披发之翁狂渡河，其妻止之徒咨嗟。","家中餔麋尚可住，君今欲渡将如何。","请君登高丘，与君望远海，一曲箜篌至今在。","长风破浪岂无时，万斛之舟且须待。"]},{"t":"寄丁戊山人傅木虚歌","f":"古风","c":["吾闻勾漏为二十二之洞天，窟穴勾曲非人寰。","上有石峰千丈之崟岌，下有清溪万折之潺湲。","普照岩前云出入，白沙洞口云沾湿。","仙坛佛塔互低昂，宝盖灵幡复披拂。","石鼎丹炉五百春，幽栖今有傅山人。","道穷要眇归玄牝，心自虚无养谷神。","闻君昨游豹子石，马退茅亭有仙迹。","玉銮隐约不堪攀，玄圃峥嵘望何极。","嗟余曾入大罗天，名在丹台石室边。","蓬莱一谪违真侣，蹩躠风尘独可怜。","王烈素书尚能识，石髓遇之傥堪食。","时观紫气一登楼，愿拜青牛见颜色。","君不见葛洪欲求勾漏丹，邓岳止之犹复还。","乘风万里倏可至，迟尔归来罗浮四百三十二之仙山。"]},{"t":"端州凯宴行","f":"七言古诗","c":["自从大罗山贼来，虔刘妇女驱婴孩。","千家万家室如扫，仓囷杼轴皆尘埃。","幕府专征有成算，汉军达军势如电。","飞符三楚调狼兵，五将前驱我军殿。","笳鼓长麾入瘴茅，空巢不费诸军箭。","羽书驰报请刍粮，士饱马肥思一战。","西风铙吹凯歌归，数十俘囚泮宫献。","谁知首级半农商，血裹淋漓那忍见。","椎牛酾酒飨归士，犷悍狼兵更愁怨。","金花锦帐排军门，诸司尽向端州宴。","吁嗟此事真儿戏，曹幕诸山贼犹炽。","岭南无岁无征戎，愿君勿似大罗功。"]},{"t":"灵台引","f":"七言古诗","c":["雨雪萧萧闭关卧，劲风吹寒激窗过。","篝灯不寐抚髀坐，哀歌中夜无人和。","只今书牍有三千，不似东皋二顷田。","餔糜一饱寒无毡，男号女啼常在前。","曾闻宁生一叩角，下车载之相齐国。","人生穷达未可卜，布衣且寄灵台宿。"]},{"t":"送顾玄纬省觐京师因归无锡","f":"古风","c":["五月麦苗黄，南风藕花白。","水驿北归船，饯送勾吴客。","顾侯昔隐勾吴墟，闭户颇窥千卷书。","前年忽忆罗浮胜，捧檄忻乘使者车。","到官十日理山屩，四百峰头采灵药。","未论勾漏有稚川，且喜永嘉得康乐。","春来种秫无公田，禄米只充酤酒钱。","闲寻我辈屏驺从，往往寄饷云霞篇。","侯年方及四十四，思玄已著还山赋。","台省诸公不可留，林泉发兴翩然去。","东门出祖苦匆匆，酒绿蕉黄荔子红。","帆席挂时沾暑雨，蒪鲈归日及秋风。","秋风先到潞河渚，宁亲上寿尚书府。","挂冠即向神武门，扬舲共指春申甫。","第二泉头日快哉，彗山犹有读书台。","笔逢棐几题诗去，棋掩幽窗赌墅回。","小山桂树长吟讽，孤鸿渺渺挥弦送。","访古朝登季子祠，寻幽夕宿张公洞。","君不见张长公，君不见邴曼容。","宦情何有六百石，禄食岂必三千钟。","从此著书年月久，玉检瑶编藏小酉。","他时我亦卧罗浮，书成寄我山中否。"]},{"t":"樵山杂言送严寅叔","f":"楚辞体","c":["山木兮青青，山泉兮泠泠。","君不顾兮忽惆怅，松落色兮泉无声。","昔与君兮卧空谷，泉为琴兮松为屋。","思共济兮苍生，耻自投兮荆玉。","群龙集兮纷相迎，送君出兮谒承明。","眇不才兮独留，云霏霏兮媵予而上征。","君将行兮一停车，饮君酒兮揽君袪。","霖雨沛兮今方须，樵之云兮将何如。"]},{"t":"内兵行","f":"古风","c":["金陵留都根本地，内兵三十有七卫。","祖宗养士二百年，士饱马肥日嬉戏。","计司稍缓散刍粮，众怒甘心黄侍郎。","坐令军士发愤怨，谁为国家存纪纲。","昔年云中曾再变，边镇承平骇闻见。","将无纪律军益骄，张李被害城萧条。","总制必征有中主，洗城汹汹讹言嚣。","皇心本欲诛首恶，劳苦边军岂恩薄。","瓒乎代镇反侧安，绾也抚绥耄倪乐。","留都近事鉴匪远，事定旦夕威不损。","孝陵功德天眷深，万岁金汤固根本。","君不见郭疤子徐毡儿，大同城下甘淩迟。","皇灵四振况京辇，慎勿干纪劳王师。"]},{"t":"潘启猷宅观梁思伯西樵山障子歌","f":"古风","c":["丹丘崒嵂三千丈，紫峤茏葱一万重。","南池堂中开画障，彷佛溟渤之仙峰。","细认梁生作，乃是西樵山。","罗浮相伯仲，秀拔南海间。","梁生此障师董源，颇似米氏兼云烟。","深山尚书畏莫敌，小李将军不敢前。","忆昔梁生共邛杖，更携黎子西樵上。","山中洒墨展生绡，酒酣为我图苍莽。","眼底干岩暮霭生，耳边百道飞泉响。","柴扉松径入萧掺，洞客林僧对清爽。","出山倏已四三年，只今茅屋閒披赏。","梁生已去掌丝纶，黎子金闺作近臣。","猿啼蕙帐岁经岁，鸟唤烟萝春复春。","潘郎近亦理征策，心向云霄卖云壑。","谢安四十卧东山，大笑为君谢逋客。"]},{"t":"题大司马王公伯安画像","f":"七言古诗","c":["吴楚妖祲见封狐，铸山煮海繁有徒。","豫章城上夜吹箛，直趋皖下窥以觎。","公时在赣不待餔，挺身易服乘渔䒀。","勤王万里方号呼，吉州集众亲鼓桴。","速据巢穴收洪都，遂擒逆贼清江湖。","绥厥士女将献俘，皇师奋遏仍天诛。","逡巡居东逊硕肤，力辞封赏赋遂初。","西粤不靖两江洿，蒲轮起公镇苍梧。","总制专征授赤鈇，穷兵治叛民何辜。","保障边境安獠奴，疏复岑氏存卢苏。","开边安南岂庙谟，宁忤宰相触噫乌。","实轸岭外困且痡，膏泽潜润民始苏。","不然畲山昔尽锄，况帝已赐金仆姑。","良知在心谁可诬，皇天知臣臣不孤。","居夷浮海平生途，毁功绌爵何有乎。","忆公曾上珠江舻，我骑竹马观雕弧。","南康蔡生貌此图，三纪犹识面与颅。","墓上宿草计已芜，畏垒尸祝何处无。","即今南北缨曼胡，空想我公真丈夫。"]},{"t":"大司寇见素林公木兰归客图歌","f":"七言古诗","c":["承平昔在成化间，林公初出木兰山。","内竖妖僧肆荧或，危言下狱投边关。","孝宗之世持滇宪，焚佛辇珠入京甸。","千厓孟密詟天威，陈臬湖湘速归传。","木兰五载白纶巾，敕起防江作重臣。","名齐台省四君子，世识维扬一俊人。","开府西江列双戟，上书请禁吴王逆。","一辞院印十年归，投老木兰山下客。","西征有诏自天来，头白令公何壮哉。","蓝鄢直视狐兔穴，豺狼未灭令心哀。","江津再捷不受赏，回首木兰理烟桨。","刘濞窥关恶已成，谁为剧孟谁袁盎。","今皇御极求老成，入司邦禁动引经。","权家戚畹畏如虎，乞身八疏辞宸扃。","平生三仕还三已，半向木兰弄烟水。","仰天长啸一挥毫，万叠云霞落冰纸。","壶公千丈高嵯峨，长者陂寒水不波。","孤鸿冥冥白驹皎，思公不见将如何。","潘君爱画世无匹，百年元气视此笔。","愿君宝之藏石室，再拜贞观魏公笏。"]},{"t":"夏日江村闲游二首 其一","f":"五言律诗","c":["乡园惟旧业，凫鸭自为家。","宅比岷阳近，田依杜曲斜。","回堤侵芋叶，荒渚带蕉花。","愧谢纶竿叟，江烟度岁华。"]},{"t":"夏日江村闲游二首 其二","f":"五言律诗","c":["南陆当炎日，西淋近水乡。","葡萄沾雨熟，菡萏出波长。","溪引观鱼槛，池开射鸭堂。","兰桡自来往，何必下潇湘。"]},{"t":"雨夜寄郑二","f":"五言律诗","c":["流萤窗外过，疏雨夜深闻。","重以离弦感，翻怜别袂分。","书成藏海岳，剑在感风云。","闻道侯芭去，何人问古文。"]},{"t":"晚霁园中邀陈梦庚","f":"五言律诗","c":["端居谢人境，扶病出丘樊。","朱草时能卷，绿蘅日以繁。","酒非杨子宅，竹似蒋生园。","旧雨无来客，期君策短辕。"]},{"t":"卧病","f":"五言律诗","c":["一月掩柴门，交游少过存。","检方分药石，散帙杂兰荪。","司马常称疾，东方自避諠。","僻居元寂寞，何必卧郊园。"]},{"t":"次韶州","f":"五言律诗","c":["腊月渡浈水，系舟韶石间。","山高连汉徼，树远接秦关。","禹甸通诸粤，尧封尽百蛮。","九成台下路，犹想翠华还。"]},{"t":"游宝积龙华诸寺至东山次方思道韵","f":"五言律诗","c":["横浦多名胜，乘春到上方。","岭云通佛栱，江日抱禅房。","城倚秦关壮，天连楚水长。","绀园催暝色，钟磬隔微茫。"]},{"t":"送黄洛","f":"五言律诗","c":["客子有行役，南游路可怜。","江光帆影外，春色鸟啼边。","闽客书应到，吴侬曲已传。","异乡看尔去，惆怅送河船。"]},{"t":"少司寇大庾刘公出示郑少谷所书李空同何大复诗同赋","f":"五言律诗","c":["郑老忧时士，李何晞古心。","斯人不可作，吾党只沾襟。","白雪寡和曲，朱弦三叹音。","抚卷怜余晚，千秋遗恨深。"]},{"t":"清明日过万安县","f":"五言律诗","c":["节序过寒食，扁舟客更愁。","他乡对童仆，故国忆松楸。","暮雨江边树，春莺水上楼。","凭高独凝睇，把酒意悠悠。"]},{"t":"渡扬子江","f":"五言律诗","c":["大江限南北，击楫此经过。","不见长安近，其如行路何。","烟中沉楚树，鸿外渺湘波。","谢眺怀京邑，新林引望多。"]},{"t":"憩元阳羽人山房次张节韵","f":"五言律诗","c":["炼师何处去，缥缈凤笙家。","沧海随风驭，蓬莱驻日车。","林栖珠树鹤，云覆石坛花。","知有登仙路，何年蹑紫霞。"]},{"t":"凤凰台","f":"五言律诗","c":["昔日凤凰下，今留台上名。","千秋不复见，一望石头城。","翠竹几回首，白云空复情。","箫声何处听，彷佛似秦京。"]},{"t":"夏日同陈世鸣凭虚阁宴集次陈徐二子壁间韵四首 其一","f":"五言律诗","c":["伏日登禅阁，萧萧松桂秋。","云霞开绣户，城阙隐朱楼。","山绕乐游苑，池穿太液流。","爱君延赏意，弥觉异乡愁。"]},{"t":"夏日同陈世鸣凭虚阁宴集次陈徐二子壁间韵四首 其二","f":"五言律诗","c":["故事南朝日，风流忆谢墩。","薜萝延翠霭，箫鼓送黄昏。","钟阜深藏寺，玄湖曲绕村。","帝城瞻王气，犹自护朱门。"]},{"t":"夏日同陈世鸣凭虚阁宴集次陈徐二子壁间韵四首 其三","f":"五言律诗","c":["地远堪遗世，山空忽似秋。","虚疑梁苑雪，不尽楚江流。","草树三吴色，云烟六代愁。","夜深凉月白，长啸碧峰头。"]},{"t":"夏日同陈世鸣凭虚阁宴集次陈徐二子壁间韵四首 其四","f":"五言律诗","c":["二妙题诗处，招邀载酒来。","阁虚频送暑，昼永数衔杯。","日月周京旧，山河禹甸回。","登高虽欲赋，愧尔子云才。"]},{"t":"夜过赵大理","f":"五言律诗","c":["过逢情缱绻，杯酒慰羁栖。","夕院桐飘叶，秋园鹿引麛。","薄云吴苑北，疏柳汉宫西。","共听高城漏，乡关梦欲迷。"]},{"t":"灵谷寺","f":"五言律诗","c":["六代钟山寺，千秋白下门。","寒云栖宝殿，秋日下朱轩。","原庙衣冠出，鼎湖弓剑存。","愿资灵觉力，长护孝陵园。"]},{"t":"同王子新陈世鸣徐伯元卫朝卿晚游燕子矶","f":"五言律诗","c":["金尊开梵阁，皂盖俯芳洲。","日落青山远，江寒白雪流。","楚云归浦晚，胡雁带边秋。","为谢朱门客，将持宝剑游。"]},{"t":"夜集谭大理宅同侯比部舜举","f":"五言律诗","c":["寓直推能赋，论交更一寻。","月悬郎署冷，山绕帝城深。","白纻传新曲，黄花寄赏心。","不知城漏永，星汉夜沉沉。"]},{"t":"夜登太白楼","f":"五言律诗","c":["狂歌采石月，高卧谪仙楼。","珠斗当窗见，银河拂槛流。","朔鸿飘塞色，羌笛入边愁。","何处思公子，峨眉夜夜秋。"]},{"t":"溪堂暑夜","f":"五言律诗","c":["炎威薄中夕，凉气上渔台。","丹霄清露下，空水惠风来。","鱼跃菱花散，龟游莲叶开。","西园明月色，空忆邺中才。"]},{"t":"赠何于逵游衡山","f":"五言律诗","c":["闻女衡州去，南寻岣嵝来。","搴萝紫盖侧，采秀朱陵台。","白鹤翔云下，芙蓉照日开。","悬知登岳赋，应待仲宣才。"]},{"t":"怀唐一允治","f":"五言律诗","c":["忻逢炎景息，调轸向中霄。","白露连秋汉，鲜云卷夕飙。","怡情持蕙草，含思抚兰苕。","忆女音尘阔，高城望独遥。"]},{"t":"寄刘希曾","f":"五言律诗","c":["刘向擅幽讨，名家富典坟。","披縢睹河籍，削竹缉山文。","白马高谈变，青羊别路分。","瑶华枉承赠，西望庾关云。"]},{"t":"秋日溪上寄大庾何隐君","f":"五言律诗","c":["商风吹陇首，木叶下江波。","桂旆飘云去，兰桡击汰过。","三秋寻白社，九月入青萝。","丛桂劳招隐，王孙意若何。"]},{"t":"越王台与陈五别","f":"五言律诗","c":["登高聊送远，惆怅欲沾衣。","江晚征鸿度，关寒落叶飞。","粤台曾北望，汉使已西归。","君去看衰草，无劳怨夕晖。"]},{"t":"讯张伯邻","f":"五言律诗","c":["闻道张平子，四愁今复歌。","龟山不可望，凤野故相过。","岁月青枫古，江湖白雁多。","城南读书处，消息近如何。"]},{"t":"同郑克一送郭三归桂林郡","f":"五言律诗","c":["汝去度郁水，西江路更西。","东风芳杜晚，落日子规啼。","旅思遥旌旆，乡心切鼓鼙。","悬知他夜月，相忆在兰闺。"]},{"t":"除夕怀二弟次江西所寄韵","f":"五言律诗","c":["柏酒遥思汝，椒盘独对予。","三冬鱼素远，千里雁行疏。","功业逢宾戏，江湖著子虚。","所欢家庆集，持报豫章书。"]},{"t":"送陈梦庚读书中宿山用留别韵","f":"五言律诗","c":["避俗人踪远，精庐寄万峰。","山云藏虎豹，峡雨动鱼龙。","鸟下斋前食，灯残讲后钟。","问奇应有客，载酒日相从。"]},{"t":"寄龙子文","f":"五言律诗","c":["闻汝近移家，开堂览物华。","岭梅南向暖，江雁北征斜。","学士楼前竹，将军庙口花。","旧游如梦里，惆怅在天涯。"]},{"t":"怀薛考功仲常二首 其一","f":"五言律诗","c":["南曹今北上，消息近何如。","白下多新句，昆陵少定居。","龙分愁别剑，雁断忆传书。","岁晚偏萧索，何人荐子虚。"]},{"t":"怀薛考功仲常二首 其二","f":"五言律诗","c":["别汝秦淮上，音尘望履綦。","汀洲劳远梦，枉渚失佳期。","萧艾何为者，椒兰今若兹。","所思犹万里，惆怅采江蓠。"]},{"t":"秋夜同黎惟敬宿清泉精舍","f":"五言律诗","c":["斜汉双星夜，高梧一叶秋。","兰膏欲凝结，桂楫尚夷犹。","有梦随湘水，无书寄陇头。","娟娟松桂月，相忆在南楼。"]},{"t":"答谟弟秋夜宿浈阳峡口见寄","f":"五言律诗","c":["风波一以别，知尔独沾襟。","贫贱辞家早，松楸积恨深。","青山一片石，孤子百年心。","夜听南楼雁，秋来好寄音。"]},{"t":"答宪副邓公见访以周正订疑垂问","f":"五言律诗","c":["贱子诸生后，名公大父行。","订疑怀竹简，乘兴到云房。","鲁史麟编旧，周正凤历长。","微言何以答，游夏愧升堂。"]},{"t":"饥乌","f":"五言律诗","c":["饥乌疑不下，野鹤寡相亲。","贫贱逢多难，风波几故人。","漳滨谁问病，河渚愿依邻。","去矣从吾好，劳劳何足陈。"]},{"t":"柴门","f":"五言律诗","c":["拙性非栖遁，閒身久避諠。","田园秋计尽，墟落夕烟繁。","去日不复得，愁心谁共论。","平生有微尚，偃仰愧柴门。"]},{"t":"诸将","f":"五言律诗","c":["汉家七十战，诸将几人同。","木樵时望月，刀斗夜临风。","鏖战皋兰北，追奔大漠中。","褊裨皆万户，尺寸未论功。"]},{"t":"村夜","f":"五言律诗","c":["风竞南氛恶，天高北斗明。","孤灯无雁字，双泪有猿声。","匣暗蛟龙跃，枥寒骐骥鸣。","闲来忧转切，谁为答升平。"]},{"t":"访苏四丈绍节隐居","f":"五言律诗","c":["委巷绝尘鞅，寻君独到门。","径荒自松菊，溪馥足兰荪。","世路知音少，沧洲吾道存。","弦桐奏山水，清夜竟忘言。"]},{"t":"病起斋中即事","f":"五言律诗","c":["幽歹谁相问，秋凉病稍宽。","闭门黄叶积，欹枕白云残。","茅屋新成业，汀洲早戒寒。","閒来疏懒甚，书不到长安。"]},{"t":"秋晓渡鱼塘海寄郑二","f":"五言律诗","c":["晨榜催宵发，荒烟浦溆迷。","津遥微见树，村近稍闻鸡。","宿莽渔先起，残荷鹭尚栖。","羡君高枕卧，谁念庾安西。"]},{"t":"黎惟敬梁公实约过草堂不至","f":"五言律诗","c":["却扫柴门下，孤村少客过。","授经非博士，贷粟有监河。","溪涨凫鹥满，园荒杞菊多。","草堂终日待，枉策意如何。"]},{"t":"霜夜拙清楼闻笛","f":"五言律诗","c":["何处悲声起，寥寥入陇头。","落梅怨遥夜，折柳送清秋。","月白思乡曲，云黄出塞愁。","谁知郿县客，听尔泪双流。"]},{"t":"初秋夜梁用宾陈潜甫区惟鼎过宿斋中","f":"五言律诗","c":["下榻留佳客，玄谈夜不眠。","钟声沉浦树，月色淡江烟。","地胜南皮会，时危北海贤。","茅斋慰岑寂，何异瀼西田。"]},{"t":"酬粱彦国过洲上约同游西樵","f":"五言律诗","c":["枉策劳相过，秋宵共掩扉。","候虫当砌响，落叶近窗飞。","月色砧偏急，溪声渔渐归。","怜君招隐士，将拂薜萝衣。"]},{"t":"月夜同黎惟敬梁思伯泛芙蓉溪得秋字","f":"五言律诗","c":["旧约寻烟浦，君来属暮秋。","墙阴含竹色，月影入溪流。","笛有邀桓步，舟仍访戴游。","锦袍怜一醉，非是恋沧洲。"]},{"t":"西樵山下经故相方文襄公第","f":"五言律诗","c":["相府青山下，风吹戟户开。","昔时朝士至，今日路人来。","鹤语留华表，星文坼上台。","千秋一洒泪，徒有雍门哀。"]},{"t":"晚过九龙洞","f":"五言律诗","c":["疲马入云谷，柴门方解骖。","乍从双瀑下，忽过九龙岩。","石古苍烟积，峰横落日衔。","期君负书笈，来此卧松杉。"]},{"t":"水帘房","f":"五言律诗","c":["珠箔不可卷，石房云出门。","岩霏侵几席，寒瀑湿兰荪。","触户时逢鹿，窥书或有猿。","眷言绝尘鞅，聊以涤烦諠。"]},{"t":"寻宝峰寺故址","f":"五言律诗","c":["昔人卓锡地，闻有化城开。","寺是何年废，山经几劫灰。","雨花今寂寞，霜草独徘徊。","念此亦几坏，浮生益可哀。"]},{"t":"伦中郎彦群访予山馆不值","f":"五言律诗","c":["公子能相访，主人方远游。","空惭开径待，不为看山留。","题凤门犹掩，笼鹅帖未酬。","他时愿乘兴，来听竹斋秋。"]},{"t":"雪夜同梁仲登泛舟赤花海过水栅十里乃还二首 其一","f":"五言律诗","c":["进帆赤石海，似入武陵溪。","雪浪飞花过，汀洲宿鹭迷。","断猿霜碛外，哀角烧林西。","欲访情人去，何时到会稽。"]},{"t":"雪夜同梁仲登泛舟赤花海过水栅十里乃还二首 其二","f":"五言律诗","c":["摇艇冲溪雪，苍茫路不分。","冒寒琴独抱，遵渚雁为群。","月下闻河激，烟中遇鄂君。","新林今夕望，小谢最能文。"]},{"t":"锦溪馆月夜怀黎惟仁","f":"五言律诗","c":["夜久众諠息，幽人月下吟。","潮来疑涧响，家远似山深。","送客烟中屦，期僧石上琴。","何由共玄度，于此长禅心。"]},{"t":"送滕先生罢官归海盐","f":"五言律诗","c":["槜李兵未解，罢归何所如。","始宁寻别墅，善福寄精庐。","避地堪招隐，看山更卜居。","汉家求绝学，应访伏生书。"]},{"t":"春晚雨中寄梁仲登","f":"五言律诗","c":["念汝离群久，还山已换衣。","夕猿添客泪，春草待人归。","花事纷将减，莺声半已稀。","子荆愁绝处，零雨正霏霏。"]},{"t":"梁思伯过洲上","f":"五言律诗","c":["三径蓬蒿长，谁寻仲蔚门。","箪瓢忘晏设，文史入宵言。","散帙或焚蒳，钓鱼时放䑳。","问津人罕到，不必记桃源。"]},{"t":"同郑何二子宿光孝寺颛上人房","f":"五言律诗","c":["释子期过宿，诃林访化城。","宗雷多内学，支遁是平生。","池月澹禅性，铃风答梵声。","此中堪出世，不寐听寒更。"]},{"t":"寻陈士鹄郭外幽居","f":"五言律诗","c":["瀼西还此地，河上独精庐。","野路渔樵外，江郊霜露馀。","天寒一瓢酒，岁晏五车书。","愿就于陵子，灌园何所如。"]},{"t":"罗浮杂咏四首 其一 蓬莱阁","f":"五言律诗","c":["夜静传真诀，飞仙暂此留。","飙轮过碧水，羽盖入丹丘。","鹤语千峰月，松吟万壑秋。","沧桑今可待，双舄几时游。"]},{"t":"罗浮杂咏四首 其二 单道开石室","f":"五言律诗","c":["衣褐南来客，罗浮路不迷。","初行秦甸外，肯止邺城西。","餐石何须煮，编茅尚可栖。","千秋蝉蜕地，谢豹为谁啼。"]},{"t":"罗浮杂咏四首 其三 王野人庐","f":"五言律诗","c":["鸡犬云中去，遗墟在观原。","岭猿啼蕙帐，山叶积柴门。","夜月穿萝到，春林入涧喧。","樵苏无可问，知是野人园。"]},{"t":"罗浮杂咏四首 其四 轩辕仙人试剑石","f":"五言律诗","c":["仙客携长剑，星文乍有无。","步光开石窌，飞景骇山都。","龙化何时出，虹流片影孤。","越金曾敛锷，持此问风胡。"]},{"t":"寄大行惟和","f":"五言律诗","c":["闻道皇华使，偏承汉主恩。","风云随玉节，岁月待輶轩。","戏綵歌华黍，分庭拜采蘩。","何时张博望，飞旆出河源。"]},{"t":"同黎惟敬梁思伯游西樵宿云谷洞得存字","f":"五言律诗","c":["改岁吾重到，烟萝迹尚存。","七松吟暝壑，双瀑溅云根。","夜冷猿啼树，秋深叶满村。","山林惭大隐，兹夕兴飞翻。"]},{"t":"翠岩在碧云村外","f":"五言律诗","c":["风泉鸣日夕，山翠入虚无。","霁后寻芜径，云中得奥区。","鹤来窥绿检，仙去长青蒲。","谢客时攀叶，松门兴未孤。"]},{"t":"同张中卿吴而待黎惟敬梁思伯何少羽游崇胜寺得霞字","f":"五言律诗","c":["步入招提境，鸣钟日未斜。","僧开白莲社，峰度赤城霞。","一径苔仍滑，双林桂已花。","皈依更何日，听尔演三车。"]},{"t":"九日同梁仲登黄贤甫登刘王郊台","f":"五言律诗","c":["把菊复载酒，登台酬赏心。","荒榛满天地，片雨暗山林。","代迥华风变，云愁霸气沉。","十年长剑在，吾欲扫氛祲。"]},{"t":"秋日梁少傅邀游徐道士馆得羊字","f":"五言律诗","c":["烦嚣忻暂息，落日过山房。","坐久积庭叶，磬清闻洞章。","青城时度鹤，白石忽成羊。","笑问乘云去，何时到帝乡。"]},{"t":"悼马","f":"五言律诗","c":["羡女龙媒种，西来渥水旁。","平生空慷慨，垂死独凄凉。","细草青春软，黄沙白日长。","中涓求骏骨，持此报燕王。"]},{"t":"定海门楼眺望","f":"五言律诗","c":["把酒烽烟后，登楼草树平。","山连刘氏苑，江绕粤人城。","荆北羁王粲，交南老葛生。","故乡频徙倚，怀古一含情。"]},{"t":"吉赞渡逢暮雨","f":"五言律诗","c":["音书愁里隔，烟火望中分。","五渡船船雨，千峰树树云。","洛神波上袜，湘女竹间裙。","赋客空相忆，瑶华一寄君。"]},{"t":"宿罗二山居","f":"五言律诗","c":["华盖馀秋色，幽居一院云。","疏松度明月，高卧对夫君。","檐下鸣蛩近，灯前落叶闻。","西山鸾鹤在，应自远人群。"]},{"t":"西斋梦后作","f":"五言律诗","c":["焚舟方得计，策蹇更如何。","远道非难及，虚名只厌多。","风泉鸣涧壑，云屋带藤萝。","宁戚何为者，犹劳叩角歌。"]},{"t":"答友人","f":"五言律诗","c":["贫贱谁相问，生涯知者稀。","年丰犹粝食，冬冷自荷衣。","事免心劳拙，形因战胜肥。","幽期倘不负，日日扫柴扉。"]},{"t":"喜梁师说李少偕入社得情字","f":"五言律诗","c":["乐志新成趣，柴门扫雪迎。","岂期簪绂客，而有薜萝情。","蒋径过羊仲，梁园待马卿。","北山旧猿鹤，莫遣怨寒盟。"]},{"t":"夏夜遇雨斋中颇有秋意","f":"五言律诗","c":["独宿高斋夜，萧然松桂幽。","海风频送暑，山雨渐成秋。","散帙青藜过，鸣琴白雪流。","潘安犹寓直，谁遣二毛忧。"]},{"t":"同罗曜文夜饮从弟华宅","f":"五言律诗","c":["闻有一斗酒，相携倒接䍦。","主人非北海，词客似南皮。","山月照弹瑟，溪风吹钓丝。","秋怀今夕赋，偏赏惠连诗。"]},{"t":"别友人归江月","f":"五言律诗","c":["复与故人别，相逢知几年。","客帆归海曲，别酒醉江天。","草色愁中雨，江声梦里船。","凭将尺素寄，双鲤到河边。"]},{"t":"夜坐西斋","f":"五言律诗","c":["拥褐观心坐，翛然万念澄。","焚香齐乱帙，煮药候残灯。","榻在稀逢客，瓢空懒寄僧。","住山诸子约，何日遂担簦。"]},{"t":"仲秋八日还山有作四首 其一","f":"五言律诗","c":["夕马飞偏急，相随归故园。","秋烟江水暝，落日渡头喧。","舍者罢争席，老亲欢倚门。","经时无斗粟，负米向何村。"]},{"t":"仲秋八日还山有作四首 其二","f":"五言律诗","c":["岂是倦游者，还山意绪真。","青云疑畏路，黄鹤待归人。","童应蓬门少，宾来橡饭新。","明朝谁载酒，应得慰家贫。"]},{"t":"仲秋八日还山有作四首 其三","f":"五言律诗","c":["青冥吾独后，白发每能先。","世岂高人慢，天惟醉者全。","歌吟偏海月，渔钓自江烟。","骨相今如此，栖栖敢受怜。"]},{"t":"仲秋八日还山有作四首 其四","f":"五言律诗","c":["嗒然一室内，生理更如何。","天地有高枕，江湖仍短蓑。","书成千载事，剑倚众人歌。","未厌烟皋冷，秋裳且薜萝。"]},{"t":"陈潜甫于风雪中见访闻将寻张苏二逸人怅然怀之","f":"五言律诗","c":["冷落人踪少，柴荆岁欲残。","谁曾怜范叔，尔亦问袁安。","山雪孤窗暗，溪云一棹寒。","未能从二子，江浦羡渔竿。"]},{"t":"得黄希尹金陵书答以四韵","f":"五言律诗","c":["送君白门去，五载尚为郎。","握手知何日，题书问故乡。","潮声江浦雁，秋色石城霜。","一叶西风外，无因到洛阳。"]},{"t":"晚归壁山渡口","f":"五言律诗","c":["岁尽归心促，清猿苦夜吟。","野阴生泽畔，寒烧隔霜林。","戍堡丹枫下，渔舟白苇深。","因思京口宿，曾听万家砧。"]},{"t":"闻倭夷渐逼潮州海上徵兵甚急感事书怀因寄玄纬四首 其一","f":"五言律诗","c":["岂料边烽起，真看到海门。","楼成疑蜃过，舰失畏鲸吞。","士气酣三战，夷兵困七奔。","何当防兽豕，莫使满乾坤。"]},{"t":"闻倭夷渐逼潮州海上徵兵甚急感事书怀因寄玄纬四首 其二","f":"五言律诗","c":["徐吴收战马，闽粤遂夷歌。","水斗潮难至，郊寒垒渐多。","鲸鲵今未灭，舟楫问如何。","尔辈看铜柱，中原有伏波。"]},{"t":"闻倭夷渐逼潮州海上徵兵甚急感事书怀因寄玄纬四首 其三","f":"五言律诗","c":["羽檄纷传箭，龙骧乍拥旄。","千笳吹月落，万甲积山高。","筦库群趋府，渔樵半佩刀。","忧时王景略，头白不堪搔。"]},{"t":"闻倭夷渐逼潮州海上徵兵甚急感事书怀因寄玄纬四首 其四","f":"五言律诗","c":["青岛频多事，苍生今可哀。","使非徐福去，贽岂越裳来。","战色千村暮，潮声万舸回。","赠君惟匕首，行见海氛开。"]},{"t":"海上逢丁戊山人自朗宁至","f":"五言律诗","c":["戎马殊方急，君今何所之。","人群仍纵酒，客路只题诗。","剑倚风尘过，丹成日月迟。","管宁将度海，莫遣世人知。"]},{"t":"同傅木虚集黎惟仁招仙馆得来字","f":"五言律诗","c":["十方游已遍，端为故人来。","把臂八年别，随缘千里回。","清霜疑沆瀣，孤馆即蓬莱。","预恐云軿去，姑山空汉台。"]},{"t":"过潘少承山居","f":"五言律诗","c":["门掩深春草，潘尼爱客过。","世疏金马召，山狎紫芝歌。","交谊偏泉石，才名仅薜萝。","茅斋足萧散，高枕更如何。"]},{"t":"夏夜同顾玄纬汪直卿黎惟仁潘少承梁少嘉集雨青楼听雨得钟字时玄纬将归无锡","f":"五言律诗","c":["王粲将归夕，登楼意万重。","风飘残垒角，云掩隔山钟。","密响过池竹，微凉度涧松。","他宵那可听，寂寞卧西峰。"]},{"t":"潘少承枉宿弊庐","f":"五言律诗","c":["暂别期相见，呼儿开草堂。","客频寻孺仲，人已卧良常。","身世山瓢外，乾坤石几旁。","惟君能信宿，谁复念沧浪。"]},{"t":"答潘少承约游金城寺","f":"五言律诗","c":["尺书前日至，丈室几时开。","客许题诗入，僧期难偈来。","慧风传梵呗，忍草积香台。","便逐戴颙去，斯游亦快哉。"]},{"t":"发舟黄冈渡过鹿门溪出碧鉴海与少承晚泛","f":"五言律诗","c":["山行仍水汎，孤舸逗江干。","海纳诸溪小，星摇大泽寒。","苇花因晚白，枫叶入秋丹。","渺渺人群远，同君且钓竿。"]},{"t":"重阳前一日同陈梦庚龟山眺集","f":"五言律诗","c":["秋兴閒偏逸，家山且杖藜。","竹洲浮屿外，莲社入林西。","恩隔萸囊赐，欢先菊酒携。","明朝还有约，从尔问丹梯。"]},{"t":"九日陪陈梦庚诸子游佛教台还饮桥东草堂","f":"五言律诗","c":["佳赏因君得，怜予大隐情。","花龛传海梵，草阁送江声。","言就竹林宴，欣从菊径行。","龙山千载客，徒有孟嘉名。"]},{"t":"十日陈梦庚潘少承见过","f":"五言律诗","c":["南里陶徵士，西亭谢法曹。","相逢重九后，得句白云高。","三径犹残菊，双尊且浊醪。","悠然堪一醉，木叶满林皋。"]},{"t":"访张勤夫不遇","f":"五言律诗","c":["家僮空应客，寂寞子云亭。","山笥閒三赋，云窗老一经。","剑将何日试，琴岂众人听。","高咏思君曲，江峰万叠青。"]},{"t":"过梁少学斋中","f":"五言律诗","c":["词赋堪招隐，非关桂树留。","餐英含坠露，岸帻醉高秋。","琴许山僧听，诗因海客酬。","过从知不厌，犹似竹溪游。"]},{"t":"黄幼章邀游琪林分得霜字","f":"五言律诗","c":["茗宴适秋凉，琳宫开草堂。","菊侵双涧水，桂落一林霜。","羽客弹瑶瑟，山人送玉觞。","翩翩鸾鹤集，何异白云乡。"]},{"t":"答梁仲登旅馆雨后见怀","f":"五言律诗","c":["江馆听潮夜，悠然思所欢。","雨中佳句至，灯下几回看。","梦远客衣薄，书迟旅雁寒。","天涯霜露早，谁共采幽兰。"]},{"t":"夜集苏四丈绍节宅遂过乃侄信伯","f":"五言律诗","c":["广除凉月夜，高咏思悠然。","白社惭吾后，青山羡尔先。","窗琴风里响，涧水席边悬。","小阮犹多兴，移尊竹卜眠。"]},{"t":"病中问少傅病","f":"五言律诗","c":["梁鸿何所病，莫是忆高恢。","客岂赁舂者，人疑裹饭来。","烟霞仍伏枕，梦寐几登台。","消渴吾犹甚，谁怜羁旅哀。"]},{"t":"大寒闭关三日","f":"五言律诗","c":["浮生万事劳，仲蔚自蓬蒿。","门掩斜阳尽，山连朔吹高。","缁尘凋素鬓，鸟雀识绨袍。","已会沉冥理，何心更续骚。"]},{"t":"元夕同惟仁维乔少居幼通集公瑞宅","f":"五言律诗","c":["病起能乘兴，淹留曲几凭。","夜酣千日酒，春入九枝镫。","欢剧银缸溢，愁深羽檄徵。","自怜老宾客，高会十年曾。"]},{"t":"少承招余夜过山房遣骑邀吴伯纶同会","f":"五言律诗","c":["桂树何年隐，招携月下攀。","尔能寻白社，吾欲老青山。","玩世芳尊合，狂歌白发閒。","今宵得玄度，匹马莫先还。"]},{"t":"闻顾玄纬锡山待沐园产绿芝遥寄此咏","f":"五言律诗","c":["午桥依锡穴，甲第近铜池。","赐沐朝难许，椷縢圃未窥。","九华云下出，三秀石中披。","莫学商山老，放歌行采芝。"]},{"t":"鉴江月夜与少承同赋","f":"五言律诗","c":["秋色白云天，幽人夜不眠。","閒襟山月下，逸韵竹风前。","木落猿啼树，沙寒雁宿烟。","谢庄同徙倚，新赋几时传。"]},{"t":"夜别苏觉夫大雾泛舟归草堂","f":"五言律诗","c":["河梁一分手，野客亦宵奔。","月下卧披氅，烟中闻放䑳。","猿啼知是岸，鸥宿问何村。","曙色襄阳郭，依依见鹿门。"]},{"t":"承诸公过西堂赏菊得儒字","f":"五言律诗","c":["黄花何太瘦，偏足映癯儒。","爱客留诗句，呼儿续酒壶。","径疑陶氏宅，门岂陆家湖。","野外盘餐少，频来兴莫孤。"]},{"t":"答吴伯纶问病","f":"五言律诗","c":["已谢维摩问，劳君忆病身。","莺啼孤榻近，雁过尺书频。","把袂曾同咏，论心孰可亲。","江皋时极目，烟树几迷津。"]},{"t":"答苏四丈遣子相问","f":"五言律诗","c":["予也离群久，还山隐薜萝。","甘贫千卷在，问疾几人过。","岁序朱颜改，风尘白发多。","奉书惭子伯，长笑慰蹉跎。"]},{"t":"答彦国士鹄","f":"五言律诗","c":["故人书总至，忆我钓渔矶。","独抚孤松坐，闲看双燕飞。","抄方劳客寄，送米待僧归。","住岳何年约，唯应共采薇。"]},{"t":"送胡子立","f":"五言律诗","c":["归路五千里，兰陵酒正香。","鹖冠随汉节，鲈饭趁吴航。","帆落淮南雨，衣沾岭外霜。","他时逢校猎，看尔奏长杨。"]},{"t":"社中诸子同咏严子陵先生像","f":"五言律诗","c":["汉主中兴日，斯人不可留。","云霄频凤诏，天地一羊裘。","御榻客星夜，钓竿渔浦秋。","富春徒想望，千载竟悠悠。"]},{"t":"答元颙伯纶干周少承四子凝秀阁联句见怀","f":"五言律诗","c":["高会尊前隔，新愁病后多。","观涛吾欲赋，问月尔能歌。","肮脏千杯酒，飘零一钓蓑。","词源谢衰白，奖借意如何。"]},{"t":"梁彦国罗君礼陈十鹄邀游修上人院","f":"五言律诗","c":["岂是东林日，天容我辈闲。","逢人能白眼，爱客说青山。","赏趣琴尊外，会心鱼鸟间。","虎溪仍一笑，谁遣独醒还。"]},{"t":"怀斌公","f":"五言律诗","c":["曾忆逢师处，餐风二十年。","松青难记岁，头白只安禅。","钟阜宫云外，罗浮海鹤前。","津梁知不远，警锡日南天。"]},{"t":"群盗二首 其一","f":"五言律诗","c":["岭南原乐国，此日困徵求。","几处茅茨在，萧萧江上秋。","岛夷栖澳口，海舰蔽钦州。","谁为纾长策，毋令藿食忧。"]},{"t":"群盗二首 其二","f":"五言律诗","c":["海邑频遭警，东来消息非。","闾阎多战垒，樵牧半戎衣。","何处堪高枕，殊方独掩扉。","更愁兵士犷，吴越羽书飞。"]},{"t":"冬日同潘少承过诃林访梁彦国邓毓元","f":"五言律诗","c":["偶忆许玄度，一寻都讲坛。","疏钟出兰若，片雪到旃檀。","定后鸟初下，诵馀灯未残。","万方多事日，谁识此中欢。"]},{"t":"寒夜同潘少承泛舟闻海珠山钟怀罗君礼吴伯纶","f":"五言律诗","c":["渐过卢城远，猿啼几万重。","夜禅江上月，海梵雪前钟。","林白惊驯鸽，天寒起毒龙。","思君萝幌夕，高卧紫云峰。"]},{"t":"秋日过鹤舒山房","f":"五言律诗","c":["先生常不出，我独问南垞。","父子庞公业，山林戴氏家。","爱君将献曝，留客共餐霞。","岂少衣冠客，何人候小车。"]},{"t":"送元诚叔父北上","f":"五言律诗","c":["汉家频下诏，赋客上金銮。","言从兰棹去，暂辍竹林欢。","白雁江汀晚，黄花驿路寒。","明年燕酒熟，把袂醉长安。"]},{"t":"客往荆州因游燕蓟有赠","f":"五言律诗","c":["远别不堪醒，沙头尽玉瓶。","马知荆路去，雁向蓟门听。","驿雪当阳阪，边笳督亢亭。","因君报亲串，江艇自笭箵。"]},{"t":"黄幼章赴试南宫夜雨枉别","f":"五言律诗","c":["不尽中心约，须臾袂易分。","雨深孤骑去，木落万山闻。","霜雪堪兰佩，关河自雁群。","玄成还世业，凭尔报明君。"]},{"t":"吊王挥使","f":"五言律诗","c":["夫君本儒将，扼腕谢勋名。","泪尽丁都护，才伤襧正平。","十年随骠骑，万里负长缨。","愁听邻人笛，悲风起旧营。"]},{"t":"赠邓绍先生","f":"五言古诗","c":["吴楚幽人少，先生鹤氅翁。","考槃章水曲，卜筑庾关东。","五世长桑术，千秋禦寇风。","道全心更逸，虑澹物俱空。","隐几逍遥得，虚舟浩渺同。","农经翻药荈，轩问察疲癃。","内景篇犹在，先天画未穷。","深居瑶草长，微咏綵毫工。","曾遇壶中叟，更寻河上公。","烟霞双敝屩，天地一冥鸿。","白日金光满，青山石髓丰。","柳垂陶舍绿，杏出董林红。","贤妇齐眉客，曾孙置膝童。","三生长寿域，九转大还功。","岭接梅花国，湖连孺子宫。","西江高士传，名在玉函中。"]},{"t":"过大报恩寺皓上人房","f":"五言古诗","c":["释子期相过，清斋开石房。","鹿驯方听法，院静忽闻香。","塔下慈云护，林间慧吹凉。","谷峦幽意惬，钟磬道情长。","色相窥莲字，皈依礼药王。","心期禅境寂，褰我薜萝裳。"]},{"t":"晓至朝天宫东麓亭二首 其一","f":"五言古诗","c":["风云连紫禁，宫观俯青岑。","独望瑶坛石，闲寻琪树林。","驱马淩晨到，焚香清道心。","坐逢丹灶侣，词寄玉笙吟。","水曲鸣环响，磴古积苔深。","迟我金门友，还携萝径琴。"]},{"t":"晓至朝天宫东麓亭二首 其二","f":"五言古诗","c":["麓亭一以眺，玉箫今复闻。","龙虎朝丹鼎，轩軿下綵云。","玄洞芝苓长，琳宫兰蕙芬。","冶城皆寂寞，王气独氤氲。","遥思谢太傅，因怀王右军。","延览不能去，飘飖鸾鹄群。"]},{"t":"游牛首山弘觉寺南过花岩至祖堂寺遇沧禅师","f":"五言古诗","c":["清晨骑马去，日色照高岑。","路入青松密，山盘紫甸深。","石门开净界，天阙抱祇林。","南国遗踪在，西方累劫沉。","诸天窥色相，双树长禅心。","宝塔怜孤眺，花岩爱远寻。","年多残碣积，坛覆白云阴。","定后幡无影，斋时户有禽。","炉烟参宿霭，经梵送馀音。","池上泉浮钵，亭前地布金。","随缘诠密义，适意散幽襟。","期尔皈依处，空山携玉琴。"]},{"t":"夏日游黎惟敬山池","f":"五言古诗","c":["名家开别墅，野客到閒堂。","园籞朝光丽，山池夕吹凉。","蘋疏浮弱筕，筱长夹重杨。","砌药翻朱萼，渠莲结缥房。","鱼摇鲸尾浪，燕拂桂枝梁。","玉轸调风细，金尊对日长。","心期招隐客，业似草玄郎。","倚石闻金奏，临流荐羽觞。","忻陪河朔会，恍在阆风旁。","安得金鹅蕊，时同薜荔裳。"]},{"t":"陪督学莆田林公游峡山寺","f":"五言古诗","c":["鹫岭开雕宇，龙宫隐绛霞。","地传中宿峡，林侣上清家。","梵语元通汉，炎荒尽入华。","瑶岑迎户矗，金涧绕岩斜。","寺古山偏胜，溪回路转遐。","鱼童搴藻带，鹿女献菩花。","风辔翔霄鹤，云乘上汉槎。","香烟团座盖，宝雾锁窗纱。","日暖多游骑，时清罢建牙。","青鸳瞻万栱，白马演三车。","蒲塞浆为露，桑门饭有麻。","瀑珠凝瑞草，涧玉浥仙葩。","径狭飞旌旆，坰长叠鼓笳。","慈航归未定，觉海思无涯。","衣钵从师授，何劳问释迦。"]},{"t":"峡山游瞩效齐梁体四首 其一 半云亭","f":"五言古诗","c":["飞亭白日下，灵氛紫嶂前。","鸡犬疑淮市，楼台现海边。","洛水陈王赋，巫山楚客篇。","稍昏彤叶卷，欲曙白衣鲜。","纵能成变幻，何处下群仙。"]},{"t":"峡山游瞩效齐梁体四首 其二 葛仙亭","f":"五言古诗","c":["海上元无宅，山中半带霞。","罗浮多石髓，勾漏有丹砂。","弟子羊为石，仙人枣似瓜。","飘飙九芝盖，出入五云车。","山精时照镜，木客日餐花。","虚驾那能度，悬壶即是家。"]},{"t":"峡山游瞩效齐梁体四首 其三 飞来古寺","f":"五言古诗","c":["昔日优婆塞，今来舍利前。","四山皆笠岭，一水是桑田。","地涌青莲宇，经乘白马年。","累劫空成幻，三宿即为禅。","汉后如相见，应知降彩旃。"]},{"t":"峡山游瞩效齐梁体四首 其四 黄帝二庶子祠","f":"五言古诗","c":["归山还采药，仙仗失蓬莱。","芝草青泥长，蒲花白石开。","崆峒访道去，具茨迷路回。","云车过紫府，风驭上丹台。","鼎湖在何处，缑岭欲归来。"]},{"t":"送泰泉先生还朝时有宫詹之召","f":"五言古诗","c":["地控重溟胜，山雄五岭蟠。","钟灵生间气，早岁直金銮。","紬史曾成草，披书半是兰。","师模归胄监，华重陟储端。","恭拜韦贤诏，新弹贡禹冠。","瑶山迎紫翠，少海挹波澜。","鹤禁春将晓，龙楼雪尚寒。","东朝尊四辅，青殿领千官。","琐闼含毫入，琼条插羽抟。","承华锵剑舄，翊善肃鹓鸾。","礼乐卿云缦，恩慈湛露漙。","殊阶优左相，旧学得甘盘。","凤沼天应近，鹏霄路不难。","格天吾道泰，扈圣万方欢。","此日攀征骑，无由奉讲坛。","衣冠陪祖帐，旌旆出江干。","日月逢休运，风云滞弱翰。","天涯瞻望处，北斗是长安。"]},{"t":"夜泊小金山寺闻梵","f":"五言古诗","c":["禅子经行处，泠泠度水濆。","空门正寥寂，觉海绝嚣纷。","散响飘黄叶，馀音袅白云。","鲛人投岸泣，螺女隔江闻。","天籁浑同远，霜砧乱不分。","灵洲鱼跋浪，郁水雁呼群。","乍辨仓莺语，多传白马文。","此时谁共听，洗耳谢尘氛。"]},{"t":"次韵奉酬少司寇刘公介夫见怀","f":"五言古诗","c":["十载秦关别，思君梦往来。","聂都寻水到，庾岭见梅开。","政谢韦贤日，词推沈约才。","游梁情已倦，归洛兴偏催。","岁暮停云望，春深候雁回。","折麻何处寄，愁上越王台。"]},{"t":"出塞","f":"五言古诗","c":["秋风吹大漠，落日望长安。","北地霜威早，南庭朔气寒。","曲新传鼓吹，令肃驻旌竿。","汉节临戎重，胡笳出塞难。","扬鞭清瀚海，仗剑下楼兰。","日逐思鸣镝，天山速据鞍。","狼烟原上直，鸟阵谷中盘。","玉帐云初散，金河月正团。","军容光授钺，将略定登坛。","氛祲何时息，旄头夜夜看。"]},{"t":"寄黄博士汝弘","f":"五言古诗","c":["故人谢簪黻，中岁卧山林。","归去从巢父，忘机到汉阴。","赋成班氏学，隐惬尚平心。","历历淹中术，飘飘邺下吟。","竹藩朱槿合，石牖绿萝侵。","花下尝无酒，丘中独有琴。","曹溪僧共饭，湘浦客能寻。","家庆三荆乐，交情二仲深。","欲帆浈水去，言就玉华岑。"]},{"t":"送督学南昌张公擢湖广大参","f":"五言古诗","c":["重寄绥南服，名藩据上游。","三湘环列郡，四岳领诸侯。","翼轸同分野，荆衡带古丘。","导流嶓冢水，播植厉山畴。","云梦荒先入，沱潜道合流。","周诗江汉美，禹迹岳庭幽。","运际重离治，时当既济忧。","玺书劳赐履，玉节肃鸣驺。","佐理紫薇省，题诗黄鹤楼。","位高今楚牧，职肇古荆州。","雨沛君侯马，星占使者辀。","旬宣询疾苦，屏翰俟谟猷。","有道声先服，淳风俗不偷。","儿童骑竹待，父老爱棠留。","瞻望潜龙宅，曾经建凤斿。","荣光煜霅见，佳气郁葱浮。","宫殿天开晓，园陵露报秋。","澧兰供礿荐，丰芑藉贻谋。","地本帝乡近，恩从戚里稠。","政成鬻熊国，赋陋襧衡州。","吾道推先达，诸生愧谬悠。","别公频引领，计日拜宸旒。"]},{"t":"伏日雨中梁彦国山馆同陈潜甫梁仲登集得蒸字","f":"五言古诗","c":["西岩飞雨入，三伏失炎蒸。","瀑下轻霏乱，云深爽气增。","室虚神已王，境静虑能澄。","河朔风先到，阴山雪欲凝。","听松心更远，看竹兴堪乘。","岂有台如濮，欢逢酒似渑。","文园今日共，莲社昔年曾。","野服初裁芰，山尊曲制藤。","蓬池传细脍，玉井荐寒冰。","倦爱藜床短，酣宜茗椀仍。","秋声惊渐至，晚槛喜同凭。","茅屋新诗少，幽怀愧杜陵。"]},{"t":"夜宿云谷听瀑布泉","f":"五言古诗","c":["东林聊寄宿，高阁傍层峦。","树里泉为瀑，山中谷是盘。","近檐疑雨至，欹枕即江干。","月色照还白，云声落更寒。","遥知沾涧筱，仍想湿陂兰。","洒迥飘成雪，翻空激作湍。","珠英真的的，玉佩自珊珊。","折竹相陵浦，听松句曲坛。","山猿惊果坠，乌鹊绕枝单。","客子魂难定，高僧梦正残。","钧天何处曲，流水此中弹。","谁写瑶琴里，清宵一倚阑。"]},{"t":"答梁彦国","f":"五言古诗","c":["简懒人事绝，劳君忆薜萝。","栖迟甘北渚，离索自西河。","药裹蛛成网，柴门雀可罗。","借书贪疾读，遇酒得微酡。","抱玉悲双刖，怀沙漫九歌。","朱颜将落莫，华发已蹉跎。","尔去瞻垂衮，予归理钓蓑。","秋风怅岐路，落日渺烟波。","送远销魂剧，忧时抚髀多。","子虚逢有问，狗监意如何。"]},{"t":"题潘少承滋兰精舍","f":"五言古诗","c":["深谷多香草，清秋露已霏。","当门含粲茜，入室袭芳菲。","池荫紫茎润，风飘丹颖飞。","佩从江上结，握向省中归。","瑶轸新成曲，山芗已拂衣。","谢庭看玉树，从此倍光辉。"]},{"t":"闻黎惟敬南归","f":"五言古诗","c":["故人犹未达，倦翼又南飞。","上国丹霄远，明时白社归。","风波劳役久，辞赋与时违。","弛担惟书卷，还家尚布衣。","饭牛中夜叹，歌凤此时非。","桑柘孤村暗，渔樵一径微。","病躯亲药裹，高枕对荆扉。","月出期僧惯，庭閒过客稀。","蓝田堪屏迹，汉圃且忘机。","予亦无媒者，行歌共采薇。"]},{"t":"六祖戒坛夜坐","f":"五言古诗","c":["衣钵西来日，师归度岭遐。","独能持大鉴，岂但照恒沙。","祝发从初地，皈心礼法华。","千灯花氏国，大叶药王家。","风静幡无影，尘空镜不瑕。","荒池惟水月，古刹自烟霞。","园入虞翻宅，山馀赵尉衙。","菩提天外树，檐卜雪中花。","僧臈曹溪水，禅风顾渚茶。","南宗诸弟子，相见具袈裟。"]},{"t":"送方明府君敬擢户曹入留都","f":"五言古诗","c":["东都徵卓茂，南省得韦维。","仓部周司禄，民曹汉度支。","渥恩分雨露，清望重纶丝。","凫入丹墀日，莺迁紫禁时。","登朝鸣玉地，列署祝鸠司。","薄赋纾疲户，丰储给健儿。","频年多战伐，三辅已疮痍。","勉为留京计，深酬圣主知。"]},{"t":"泛樵湖访吴而待","f":"五言古诗","c":["舍策出云谷，谋舟问水源。","共寻剡溪去，言访辟疆园。","开径求羊至，升阶兰芷繁。","呼童斸林笋，爱客倒山尊。","悬榻夕还下，赐书时更论。","为君留信宿，兴尽未回辕。"]},{"t":"寄吴伯纶","f":"五言古诗","c":["忆尔下帷地，江边久介居。","门生趋立鹄，都讲报衔鱼。","学擅淹中术，经传壁里书。","东方犹削牍，诸葛已成庐。","簪组心何累，箪瓢乐有馀。","讵能谋伏腊，祇是狎樵渔。","庭草秋烟积，山窗夜月虚。","他时马南郡，幽躅更何如。"]},{"t":"洲上漫述","f":"五言古诗","c":["静觉閒居好，翛然野鹤姿。","明时犹未隐，吾道竟何之。","世路交情异，门墙过客疑。","才无鹦鹉忌，心已白鸥知。","乐在形忘处，肥因战胜时。","云霞双草屩，天地一茅茨。","计拙羞称士，途穷岂为诗。","侏儒徒自饱，肮脏尔何辞。","竞进才何有，躬耕力未疲。","秫田聊岁计，瓜地亦恩私。","秋月松杉净，江烟橘櫾垂。","阮庭无俗物，蒋径得幽期。","近市村醪少，经霜涧菊迟。","谁资鱼菽祭，敢望纻衣遗。","稷契身能许，巢由世不羁。","暂时甘土偶，前日见郊牺。","住岳同僧约，寻溪许客随。","知希惟我贵，柱下有馀师。"]},{"t":"海珠慈度寺与颛炳二释子对月","f":"五言古诗","c":["江绕前朝寺，山开故国楼。","胡床还对月，楚客自悲秋。","叶落禅房冷，钟鸣旅雁稠。","僧逢大小朗，地即凤麟洲。","酒许攒眉去，言从灌顶酬。","寂寥师讲后，幻灭祖灯留。","幡影闲宵梵，潮声急暝流。","袁宏将访道，相约过罗浮。"]},{"t":"小除日作","f":"五言古诗","c":["岁律忽将尽，愁多鬓欲霜。","半生无下秩，万事只沧浪。","才最居人后，閒惟侍母傍。","佯狂歌凤叟，贫病祝鸡乡。","春色梅边入，年华雨里长。","随时归海畔，畏客卧山房。","筋力追欢异，生涯旧业荒。","教儿添耒耜，合耦事耕桑。","暂喜同瘖士，何因作漫郎。","逢新知有日，端拱在明堂。"]},{"t":"苏丈人园亭","f":"五言古诗","c":["秋晚篱门静，茅斋颇自宽。","林香柑子熟，露气菊花团。","奁内茶能给，瓶中粟可餐。","杏收双虎卧，橘堕一猿看。","早秫催儿酿，霜菰荐客盘。","烟凝松几润，月湿竹庭寒。","石铫醒还煮，风琴醉几弹。","自堪蓝尾酒，何愧笋皮冠。","金涧陶弘景，山园管幼安。","丹书窥玉笥，宝剑闳玄坛。","海衲求碑至，渔人认路难。","三桥藏野色，二水带江湍。","井臼通邻舍，桑麻近药栏。","尘缨何日濯，来把钓渔竿。"]},{"t":"九日入道园山谒先君墓焚遗集志感","f":"五言古诗","c":["悽怆感霜露，东阡泪满裾。","眠牛看迤逦，下马觉萧疏。","菊荐精禋上，蒲编手泽馀。","昌言嗟董袭，封禅待相如。","墓有中郎笔，山藏太史书。","诗庭虚旧位，玄冢望精庐。","终愧泷冈表，空趋万石闾。","平生风木恨，攀恋似皋鱼。"]},{"t":"留都二首 其一","f":"七言律诗","c":["紫宸宫阙秣陵前，想见高皇定鼎年。","珠树春浮三殿日，綵斿时拂五城烟。","空寥一望金茎近，霄汉长瞻玉座悬。","千古龙髯攀不及，乌号今在白云天。"]},{"t":"留都二首 其二","f":"七言律诗","c":["佳气茏葱逼上台，汉家基业万年开。","九江秀色流为带，五岳中天耸作台。","绛阙岧峣龙虎在，青云缥缈凤凰来。","二京欲纪中兴盛，惭乏张衡献赋才。"]},{"t":"辛丑元日","f":"七言律诗","c":["千官元会肃金貂，草莽何由听九韶。","楚水舟航淹日月，汉京鹓鹭满云霄。","边防北虏期更戍，凯奏南蛮已入朝。","想见阳和遍寰宇，沧江谁道有渔樵。"]},{"t":"大天界寺","f":"七言律诗","c":["长干路转宝林西，古寺犹看御敕题。","自昔翠华临玉殿，至今黄鹤下丹梯。","松边石蕴烟霞秀，阁上峰连日月低。","一入脩门云卧久，细萝芳杜忆深栖。"]},{"t":"游徐氏西园","f":"七言律诗","c":["上公别业傍金门，开国千秋带砺存。","楼古尚题烽火字，台高犹识凤凰原。","周京白水疏封地，汉主黄山御赐园。","闻道长安足尘土，无如此处问桃源。"]},{"t":"万岁殿","f":"七言律诗","c":["琪园珠瓛净尘埃，当日祈灵别殿开。","草色偏承黄辇过，鹤群还逐翠华来。","合宫旧识唐尧宅，大一空传汉武台。","趋走五云瞻望地，何年仙仗下蓬莱。"]},{"t":"天坛登望","f":"七言律诗","c":["帝京南望九门前，大祀郊丘碧草鲜。","圜殿恍闻仙陛乐，泰坛虚想御炉烟。","河山缭绕彤宫辟，星斗周遭贝阙悬。","歌颂太平多盛事，杨雄何日奏甘泉。"]},{"t":"答薛考功省中玩月见寄","f":"七言律诗","c":["碧天凉夜思徘徊，知有仙郎作赋才。","金镜正悬鳷鹊观，玉绳低映凤凰台。","新林远客空相望，扬子孤舟去不回。","谁谓山公方启事，清尊能待故人来。"]},{"t":"游牛首山用童庶子壁上韵二首 其一","f":"七言律诗","c":["江左祥光拂露盘，城南双阙俯巑岏。","辟支洞口僧卢近，罗什台前辇路宽。","紫阁平临珠斗丽，黄山半入白云寒。","蓬莱咫尺堪回首，鸾鹤翩翩肃羽翰。"]},{"t":"游牛首山用童庶子壁上韵二首 其二","f":"七言律诗","c":["万壑千山绕洞门，断碑苔藓不堪扪。","花岩缥缈标铜爵，玉殿玲珑锁绀园。","却爱楼台淩倒景，独愁钟鼓送黄昏。","翠华尚忆当年事，空向东都父老论。"]},{"t":"少司马石峰陈公哀词","f":"七言律诗","c":["东风吹雨木兰洲，司马山前逝水流。","无复中朝瞻剑舄，空令南海想旌斿。","阡题京兆犹原氏，冢象祁连拟霍侯。","都下有人称故吏，不堪涕泪过西州。"]},{"t":"送萧八出塞","f":"七言律诗","c":["驰驱万里过长安，书寄随登大将坛。","戈指棘门西日落，旆翻榆塞北风寒。","封侯想见从军乐，报主休嗟行路难。","醉别尊前成慷慨，请缨犹欲系楼兰。"]},{"t":"赠陈维藩还楚","f":"七言律诗","c":["两都作客今怜汝，三楚逢人定忆家。","登阁郢云连大别，开门湘水隔长沙。","王孙一笑挥如意，国士相看赠莫邪。","狗监悬知能引荐，马卿词赋不须嗟。"]},{"t":"留别薛考功仲常","f":"七言律诗","c":["江边驻马路将分，画省清歌不可闻。","南海自怜藜杖客，北山谁勒草堂文。","还家日月瞻丹阙，去国衣裳恋白云。","只恐秋深鸿雁少，天涯空自怅离群。"]},{"t":"黄主客赵谭二大理出饯江上","f":"七言律诗","c":["征虏亭边早戒寒，归人双旆动江干。","法曹宠饯搴舟送，客部题诗把袂看。","别后鹓鸿趋紫禁，愁来钟鼓忆长安。","烟波万里怜予远，日暮空歌澧有兰。"]},{"t":"晚次湖口候陈公载黎惟敬二子不至","f":"七言律诗","c":["日暮兰舟驿路催，秋阴黯黯思生哀。","江空独见千帆度，风急谁传尺素来。","万里风尘今拚袂，两都辞赋旧登台。","匡庐彭蠡俱形胜，惆怅难逢谢客才。"]},{"t":"闻边报","f":"七言律诗","c":["大漠秋深万马驰，小王轻徱逐胡儿。","燕歌翻作从军乐，羌笛愁闻出塞悲。","乌垒风传青海箭，雁门霜拂黑山旗。","周疆汉戍千年事，谁建旄头捣裔夷。"]},{"t":"同唐允治南归度鄱阳湖作","f":"七言律诗","c":["湖上秋烟晚渐微，冥冥江鸟逐人归。","鱼书朔塞催骁骑，龙旆燕门发佽飞。","南北路岐双客鬓，风尘天地一戎衣。","出关日远长安路，回首彤云忆禁闱。"]},{"t":"韶州谒舜庙","f":"七言律诗","c":["南狩昔闻衡岳下，岂知韶石有遗思。","衣垂坐处瞻龙衮，乐奏巡时识凤仪。","禹贡瑶琨通海峤，尧封冠带附蛮夷。","只今泪竹苍梧渺，愁见行云向九疑。"]},{"t":"岁暮登楼寄梁二公实","f":"七言律诗","c":["五噫归去卧沧洲，我亦长裾落魄游。","玉琯东回占淑气，金茎北望忆清秋。","垂杨袅袅新临浦，鸣雁翩翩半过楼。","闻道君王好辞赋，梁园车骑莫淹留。"]},{"t":"卜居","f":"七言律诗","c":["淮南桂树久相招，白社归来有药苗。","多病已妨年少日，端居犹愧圣明朝。","南临绝海风烟迥，北望中原涕泪遥。","卜筑江干聊遣兴，岁寒门径转萧条。"]},{"t":"闻陈季谦将至","f":"七言律诗","c":["独有幽怀对薜萝，故人消息尚蹉跎。","已催开径延三益，为想回桡咏九歌。","南浦烟波那可问，北风舟楫近如何。","兼程早赴柴门约，篱下黄华晚渐多。"]},{"t":"古意二首 其一","f":"七言律诗","c":["窦家夫婿远从军，少妇闺中织锦文。","沙幕关山犹在望，玉门音信未堪闻。","可怜芦叶吹秋月，不见菱花落晚云。","谁遣琵琶传塞外，至今犹恨汉明君。"]},{"t":"古意二首 其二","f":"七言律诗","c":["日暮千花损妾颜，春光不到白登山。","千年榆柳依秦塞，万里葡萄入汉关。","北望云州犹可见，西流陇水未应还。","别离已惜容华晚，芳树楼前祇自攀。"]},{"t":"海珠寺送钧弟之江西赋得孺子祠","f":"七言律诗","c":["聘君祠屋楚江干，到日祠前木叶丹。","院近湖光临晚静，阁连山色入秋寒。","霜清揽袂搴洲莽，日落回桡咏澧兰。","尔向豫章寻旧隐，东都应忆汉衣冠。"]},{"t":"九日同黄廷寅黎惟敬游菖蒲涧访玉舄亭故址","f":"七言律诗","c":["九日高台坠露清，千年残观紫烟平。","铁桥不见仙人过，玉舄空留海客名。","鹄岭晓看阊阖色，鸾霄秋送佩环声。","涧边瑶草空相待，游戏玄洲下赤城。"]},{"t":"寄王子新","f":"七言律诗","c":["杨子秋风十载馀，白门消息近何如。","共知城阙能招隐，岂但江潭可卜居。","阮籍独闻苏岭啸，马卿今著茂陵书。","烟波渺渺难逢汝，四百峰头已结庐。"]},{"t":"送赵仲履参藩广西","f":"七言律诗","c":["昔从棘寺绾铜章，此去薇垣紫绶长。","屏翰西南雄五岭，提封东北带三湘。","青春行部开牙旆，白日题诗出射堂。","会见使君勋业重，汉家铜柱更辉光。"]},{"t":"春兴三首 其一","f":"七言律诗","c":["帝城春色正堪怜，紫禁钟声度九天。","已报旌旃临泰畤，更闻车骑幸甘泉。","银涛朝涌三山日，珠树晴飘二室烟。","万岁共听来献寿，千官争向从祈年。"]},{"t":"春兴三首 其二","f":"七言律诗","c":["闻道祈灵下玉銮，春风扈从出长安。","金泥已册崇高邑，宝鼎重开太一坛。","乐府解传朱鹭曲，侍臣多戴鵔鸃冠。","竹宫桂馆瞻依地，遥想蓬莱夜月寒。"]},{"t":"春兴三首 其三","f":"七言律诗","c":["方士神君候祝釐，苍龙阙下拥朱旗。","风回桂观炉烟袅，日闪芝坛扇影移。","白帝始尊鄜畤礼，蒲池亲拜渭阳祠。","独知圣主精禋意，时向郊丘讲盛仪。"]},{"t":"询徐伯元陈维藩二子","f":"七言律诗","c":["青溪何处掩柴关，迢递天涯客未还。","杨柳尚连江令宅，楼台应对谢公山。","乌衣冠盖今何似，白下风流尚可攀。","遥想旧京行乐地，片帆何日楚云间。"]},{"t":"何衡州见访","f":"七言律诗","c":["幽栖蓬户欲张罗，岁晏谁期五马过。","上客衣冠留北海，诸生琴剑老西河。","身归白社思廊庙，门掩青山对薜萝。","无奈相从又相别，不知何地听鸣珂。"]},{"t":"初夏答友人","f":"七言律诗","c":["辛夷花过客来稀，篱落萧然独掩扉。","梅雨欲晴收药去，柘烟初起买茶归。","林香山户枇杷熟，水腻池塘属玉肥。","别后沈郎腰更瘦，病来浑欲不胜衣。"]},{"t":"秋日大仑山房","f":"七言律诗","c":["文笔峰前偃敝庐，衡茅寥寂野人疏。","山中叶落迷樵径，林下猿啼傍客居。","溪冷兰花愁欲佩，霜馀杮叶醉堪书。","弦歌更拟营三径，谁遣门前候鹿车。"]},{"t":"过族兄任充墓","f":"七言律诗","c":["吾家居士老羊裘，逸气平生竟一丘。","隐市未逢无忌访，著书应待所忠求。","瑶琴寂寞诗坛晚，宝剑凄凉宰树秋。","闻道五噫终避世，要离犹可慰同游。"]},{"t":"题唐明皇按荔枝新曲图","f":"七言律诗","c":["弦管催欢太液头，曲中消息奏涪州。","骊宫正想金舆远，羯鼓空馀玉座愁。","花萼稀闻承内宴，霓裳无复侍宸游。","雨淋铃夜西川路，犹忆长安一叶秋。"]},{"t":"同陈公载吴而待梁公实粱思伯集黎惟敬梅花堂得门字","f":"七言律诗","c":["瓜地烟深迷竹径，荷池舟过转花源。","能令野服同招隐，自有幽林足避諠。","谢客宾朋游石井，王郎瓢笠入云门。","须知乐事从真赏，秋水濠梁未可论。"]},{"t":"秋夕城闉纳凉得多字","f":"七言律诗","c":["万里寥天一雁过，沧洲日暮水增波。","不禁玉笛吹江艇，何处瑶华送楚歌。","城上清霜秋早落，桥前乌鹊夜深多。","乘风便欲将归去，寒入琼楼奈尔何。"]},{"t":"吴刺史祠","f":"七言律诗","c":["古庙荒凉貌俨然，石门山下海如天。","香从沉处犹遗浦，井戒贪馀尚有泉。","濮水东归无旧宅，卢城南望起新烟。","秋风不见龙骧节，日落啼鸦送客船。"]},{"t":"怀伦三膳部","f":"七言律诗","c":["名家擢甲擅文章，三载留都尚作郎。","起草曾闻趋建礼，含香今待入明光。","苍龙阙下云霄近，白鹭洲前烟水长。","一别沧江劳伫望，明年鸡树忆翱翔。"]},{"t":"同何库部子时看山过青萝嶂","f":"七言律诗","c":["东来望气过萝阡，南渡家山五百年。","句曲自留陶侍读，始宁今待谢临川。","柴车雨后馀双笠，藜杖云中少百钱。","知尔身轻能济胜，朱明何日更寻仙。"]},{"t":"谒陶氏二忠祠","f":"七言律诗","c":["汉室金吾四海闻，过家恩宠荷明君。","仗分柴禁辞三殿，敕拜彤墀下五云。","田禄独沾新息庙，封营犹纪信陵坟。","欲知世烈重光日，归向中朝早策勋。"]},{"t":"五仙观同陈道吾方绍宣校书答李教授","f":"七言律诗","c":["散帙香芸到几编，璈笙缥缈过窗前。","青牛未遇函关吏，高阁疑逢太乙仙。","石在风尘犹有穗，社残宾客尚馀莲。","书成爱尔能题寄，不是玄经授草年。"]},{"t":"草堂秋日四首 其一","f":"七言律诗","c":["商飙千树送鸣蝉，洛涘閒居颇自怜。","田傍西畴歌帝力，星悬南极祝亲年。","蓬庐日有三荆乐，竹径时从二仲贤。","何处丘中招隐士，开门长啸白云天。"]},{"t":"草堂秋日四首 其二","f":"七言律诗","c":["茅斋江上带沙汀，隐几焚香养性灵。","壁在自藏高士传，书成终愧太玄经。","山川摇落疑湘浦，橘柚芳芬似洞庭。","未得此中甘寂寞，何人虚拟少微星。"]},{"t":"草堂秋日四首 其三","f":"七言律诗","c":["芙蓉开向越江头，晚色萧萧倦倚楼。","目尽关山千里月，风传砧杵万家秋。","秦人独抱漳滨病，楚客难禁泽畔愁。","此际相思正无限，况逢边雁下汀洲。"]},{"t":"草堂秋日四首 其四","f":"七言律诗","c":["荒村一亩闭蓬蒿，浊酒弹琴亦解劳。","蛩响夜寒依草榻，潮痕秋晚落蘅皋。","郎曹不遇嗟三叶，骑省将归感二毛。","勋业百年翻自笑，风云西望汉坛高。"]},{"t":"同曹幼兴潘启纯海楼登望","f":"七言律诗","c":["凭高一望散忧忡，摇落山川恨不穷。","十里松门同谢客，三年江夏识黄童。","天寒远树投归鸟，日落残霞没断鸿。","烽火至今归未得，钓船多在五湖东。"]},{"t":"厓门吊古四首 其一","f":"七言律诗","c":["路尽中原历数新，秋风江上水粼粼。","南巡不返胶舟日，东渡空劳舣棹人。","豫让死能酬国士，屈原终合作波臣。","黍离麦秀无穷恨，谁向行朝忆紫宸。"]},{"t":"厓门吊古四首 其二","f":"七言律诗","c":["航海飘零万里行，孤臣一旅计难成。","空令虎士披千战，那复鸡人报六更。","岛上岂无田氏客，江东惟有汉家兵。","伤心南渡金牌诏，长使遗黎说汴京。"]},{"t":"厓门吊古四首 其三","f":"七言律诗","c":["胡骑长驱入海门，舆图非复旧乾坤。","月情只托方诸泪，春恨空销杜宇魂。","精卫未捐填海愤，鸱夷犹抱入江冤。","巫阳纵遣招难返，日落荒山听断猿。"]},{"t":"厓门吊古四首 其四","f":"七言律诗","c":["间关百战事堪怜，越鸟何心北向燕。","魂逐白鹇游四海，骨无青树记千年。","铜驼草没荒宫外，玉玺光沉浊浪前。","抱石怀沙君莫问，厓门东下水如天。"]},{"t":"酬金陵王子新见怀","f":"七言律诗","c":["著书白下掩柴门，岁晏风尘不受昏。","贫有故人怜鲍叔，老无知己念虞翻。","茅茨寂寞溪云暗，松菊萧条野日暄。","别久悬知最相忆，篇诗遥寄与谁论。"]},{"t":"访傅木虚不遇","f":"七言律诗","c":["山人瓢笠思悠哉，遁迹难逢石壁开。","紫气远从函谷路，白云初过郁洲台。","茅君冉冉三峰下，桂父飘飘五岭来。","我自相寻非兴尽，溪头谁忆棹船回。"]},{"t":"赠易道人","f":"七言律诗","c":["杖策南来寻旧师，璇房瑶室住经时。","葛洪远忆丹砂去，王烈犹逢石髓疑。","南海早传瓜是枣，零陵今有术如芝。","去去三山应咫尺，白云无迹鹤无期。"]},{"t":"怀傅木虚游勾漏未返","f":"七言律诗","c":["葛洪昔日求丹处，闻尔飘飖驾羽车。","风静乍疑鸾啸后，田荒犹识象耕馀。","朝随石室攀圭洞，夜蹑天坛礼玉虚。","龙峤有经何处觅，蒙山应授羡门书。"]},{"t":"送童侍御仲良之宣州","f":"七言律诗","c":["岭南藩幕似君希，去拥缇油渐北归。","春谷泉经溪馆过，敬亭云入郡厅飞。","吏民尽喜迎朱绂，鱼鸟浑忘避绣衣。","闻道宣城名胜地，风流今见谢玄晖。"]},{"t":"送刘安元归杭州","f":"七言律诗","c":["说剑谈诗旧识名，南来倾盖不胜情。","邺中客有刘公干，洛下人推陆士衡。","留舄何年沧海畔，观涛八月虎林城。","送君未尽扁舟兴，我欲桐江放棹行。"]},{"t":"九日泛楼船作军乐","f":"七言律诗","c":["江上重阳霁色鲜，晚携宾从上楼船。","鼓笳月似登楼夜，戈甲秋如下濑年。","沧海东南风九万，浮云西北路三千。","绕歌欲奏从军曲，醉放中流一扣舷。"]},{"t":"寄王光禄应瑞","f":"七言律诗","c":["北征何日赋骊驹，底事南山恋旧庐。","乐署俸钱聊自适，步兵监酒更何如。","心驰远道空成梦，交绝当途未有书。","君去平津东阁上，莫云词客滞公车。"]},{"t":"怀延平龙别驾子文","f":"七言律诗","c":["尺书曾寄武夷君，九曲题诗不可闻。","墨绶暂辞山县长，铜符今领郡参军。","题舆已见陈蕃起，岸帻谁同谢奕群。","想见镡津千里外，何年双剑在风云。"]},{"t":"寄王懋功因询皓上人徐居士","f":"七言律诗","c":["王郎涴壁慕家鸡，文苑名高父子齐。","山拟谢安营白土，宅连江总夹青溪。","江边弄笛人何在，雪后乘舟路不迷。","为访支公与玄度，旧游多在秣陵西。"]},{"t":"答梁比部公实","f":"七言律诗","c":["江阁孤登倚碧空，高恢何处觅梁鸿。","心随去雁层城上，梦入残砧落月中。","林隔七贤前日会，径荒二仲几时同。","萧条欲报东篱事，颇有柴桑处士风。"]},{"t":"招彦国仲登二子入社得欢字","f":"七言律诗","c":["翩翩华盖啸双鸾，翠壁丹厓欲见难。","社待陶公应肯入，坐无车胤不成欢。","兰湖正拟同纫佩，蒲涧曾期共考槃。","雪后东来一乘兴，扁舟无惜剡溪寒。"]},{"t":"以山房桂树移植梁公实拙清楼兼寄此作","f":"七言律诗","c":["扶疏双桂植山幽，移向君家十二楼。","此日骚人暂延伫，他年词客重淹留。","花含合浦千峰露，林侣贲禺八树秋。","早晚飘香满岩户，为开尊酒待同游。"]},{"t":"晓登城北楼同陈潜父梁彦国得天字","f":"七言律诗","c":["乱后孤城客可怜，峤南二月似幽燕。","边声恰听胡笳外，春色浑疑朔雪前。","远牧尚搜沙苑马，频荒谁散水衡钱。","柔条欲寄江潭思，无数征鸿过楚天。"]},{"t":"鱼塘舟中闻海上有警","f":"七言律诗","c":["岛树春深紫翠重，不堪氛祲过西淙。","潮来半带江南泪，雁断频惊海上烽。","遂有黄巾劳汉将，只闻丹徼尽尧封。","健儿何日销金甲，禾黍千村听夕舂。"]},{"t":"珠江晚望寄陈季谦陶惟谦时海上多警，闻古冈贼已就擒","f":"七言律诗","c":["雁尽不传江上信，词人幽抱若为裁。","渔灯晚杂烽烟起，野柝时闻戍鼓催。","台在早占南武拜，波平终见越裳来。","圭峰万树东风里，谁遣江南庾信哀。"]},{"t":"怀唐户曹允治","f":"七言律诗","c":["淡烟碧锁柳千条，尚忆同君白下桥。","万里云霄身独病，十年江汉路空遥。","蒋陵山色飘晴禁，瓜步钟声落暮潮。","旧约为寻东省去，秋风将托木兰桡。"]},{"t":"寄王太守公仪","f":"七言律诗","c":["东望烟波秋可怜，故人消息尚茫然。","闽中雁字三千里，岭下骊歌十五年。","野径萧条餐菊兴，沧江留滞钓鱼船。","他宵平远台前月，尚可从君醉九仙。"]},{"t":"西樵大科峰观日出","f":"七言律诗","c":["明河渐没见长空，海上鸡鸣日已红。","地涌千峰元气里，天连诸水大荒中。","云边乍听罗浮凤，曙后偏惊碣石鸿。","便欲乘风到银阙，扶桑东望思何穷。"]},{"t":"晚登广朗阁","f":"七言律诗","c":["广朗坪前霁色鲜，丹梯一望总堪怜。","云端曲接千重岭，阁上平开万里天。","远树暝悬沧海日，空山秋卧鹿门烟。","风泉细洒琅玕在，石上镌名不记年。"]},{"t":"天峰夜半玩月","f":"七言律诗","c":["绝峤高寒万籁沉，三更海月出东林。","风前独照哀鸿断，霜后全惊落叶深。","羁客此时还欲赋，山僧何意更相寻。","广寒不隔烟霄路，一曲霓裳万古心。"]},{"t":"夜泊海珠江","f":"七言律诗","c":["旅泊江城蜡炬残，愁闻使者募材官。","秋成百粤诛求尽，乱后三吴戍守难。","楼橹月明乌鹊起，海门风急皂雕寒。","谁令白首含毫客，时向霜前把剑看。"]},{"t":"冬夜集赵宪副仲履宅","f":"七言律诗","c":["开尊霜月坐更深，忆向昆明寄短吟。","绿野初归有琴鹤，青门将隐得山林。","忧时尚问诸蛮戍，破虏遥传六诏音。","白首谁怜赵充国，留屯终见老臣心。"]},{"t":"寒食同梁三过双洲别业","f":"七言律诗","c":["杨柳无烟初禁火，孤村寒食自东风。","江云乱向春帆外，山鸟多还夕照中。","绵上田荒怜介子，襄阳坟在忆庞公。","溪园手种千头树，听尽啼乌恨不穷。"]},{"t":"早秋登黎氏山楼","f":"七言律诗","c":["几年词客滞江关，高阁逢秋一解颜。","风急白云多出岫，烟销黄鹤未归山。","艰危好慰苍生望，供奉还陪紫禁班。","后夜松门虚月色，曼容应自早知还。"]},{"t":"九日下道园山还舟飓风起投宿抱旗山下人家","f":"七言律诗","c":["日暮烟波阻异乡，天涯飘泊遇重阳。","来时野老初争席，饭罢山人复馈浆。","风急每惊松子落，雨多偏入涧声长。","谁堪羁旅逢今夕，愁绝关河雁几行。"]},{"t":"同纯伯华甫登先祠南楼","f":"七言律诗","c":["长林风急送清秋，哀角凄凄倦倚楼。","金马未容方朔待，乌衣犹恋谢家游。","芙蓉碧嶂年将改，雁鹜青天晚更愁。","故国山川一回首，赋成宁似滞荆州。"]},{"t":"寄郑克一","f":"七言律诗","c":["落魄还家舌尚存，幽栖江渚自成村。","梅边有鹤归烟艇，菊下何人送酒尊。","闭户已从嵇叔锻，卜邻新灌吕安园。","知君谷口人来少，杖策相从欲避諠。"]},{"t":"溪上馆月夜怀梁宗龙区元宾诸友人","f":"七言律诗","c":["泣玉归来不自聊，屏居谁可慰萧条。","灯前独守庚申夜，月夜还过丁卯桥。","叶落砌蛩偏断续，猿吟山磬转空寥。","美人更在南溪曲，欲往从之烟水遥。"]},{"t":"晓望","f":"七言律诗","c":["牛女氛祲总已销，江南乐上伴渔樵。","天边云拥重轮日，雾里江流万里潮。","绝塞威棱刁斗静，中原消息鼓鼙遥。","健儿早赴留都戍，千载金汤仰圣朝。"]},{"t":"冬日海神庙同梁仲登晚眺","f":"七言律诗","c":["塞鸿飞尽暮云残，词客悲秋共倚阑。","二女渚连还北向，九疑山隔正西看。","荒台枕石波声小，野庙临江树影寒。","乡土岁时浑不恶，越吟空自老南冠。"]},{"t":"寄大中丞莆田林公","f":"七言律诗","c":["药洲曾忆执经游，一别梅关十二秋。","疲病风尘犹闭户，飘零南北自登楼。","家人产薄何尝问，国士恩深未易酬。","闻道蒲轮辞不起，相思欲上木兰舟。"]},{"t":"送杨吏部谪惠州","f":"七言律诗","c":["相国名家世所推，南来佐郡本何期。","省中尚忆山公启，岭外今传谢客诗。","雪过罗浮梅萼早，月明沧海酒杯迟。","天涯不用嗟留滞，宣室归时正受釐。"]},{"t":"岁暮五首 其一","f":"七言律诗","c":["台筑黄金倚蓟堧，河山形胜在幽燕。","入关不待求王猛，蹈海宁知有仲连。","负酒行歌依草泽，呼鹰射猎出蓝田。","天涯岁序逢迟暮，无数飞鸿落日边。"]},{"t":"岁暮五首 其二","f":"七言律诗","c":["千金召募一身轻，慷慨宁辞海上行。","旗帜直能翻海市，楼船何处望山城。","霏霏雨雪期更戍，滚滚波涛待洗兵。","年少终军今不乏，时危谁更请长缨。"]},{"t":"岁暮五首 其三","f":"七言律诗","c":["杨越萧条杀气多，防倭今日更如何。","江东尚想孙征虏，海上应劳马伏波。","舟楫三年频水战，渔樵千里尽夷歌。","谁怜岁晚思归士，奏凯南来免荷戈。"]},{"t":"岁暮五首 其四","f":"七言律诗","c":["八月倭奴东渡江，秣陵关吏走如羊。","海风吹雪军麾动，岛日涵波戍垒长。","想见三千摇组练，愁闻百万失艅艎。","腐儒藿食忧何事，制胜遥知出庙堂。"]},{"t":"岁暮五首 其五","f":"七言律诗","c":["懒似嵇康匕不堪，诗成惟待故人谈。","梦中道路三台北，醉里风烟五岭南。","尊酒便应留几杖，钓竿犹自滞江潭。","西来青鸟飞飞急，欲向云中寄一椷。"]},{"t":"上巳同陈潜甫韨褉锦水上","f":"七言律诗","c":["佳晨元巳一招携，脩禊同君出锦溪。","春服乘风坛树外，夕帆催鸟海楼西。","秉兰近水临芳甸，泛羽随波绕曲堤。","从此花期多乐事，南园东谷乱莺啼。"]},{"t":"暮春游万花庄","f":"七言律诗","c":["莺声渐远百花繁，韦曲寻春更一尊。","共向小桥过竹径，偶随流水入桃源。","栖迟有客方栽杏，寂寞何人独灌园。","闻道汉阴机已息，莫言真隐在江村。"]},{"t":"酬陈在璞卧病城南见寄","f":"七言律诗","c":["伏枕经时最可怜，故人南北各风烟。","交游已绝嵇中散，江汉谁知孟浩然。","云卧青山聊此日，陆沉金马是何年。","郊居若肯寻烟艇，迟尔南楼秋月悬。"]},{"t":"答邓君肃","f":"七言律诗","c":["山楼会里春醪香，驿道书来秋雁翔。","一卧乡关淹岁月，几看松菊老烟霜。","叙年早愧潘安鬓，惜别频回宋玉肠。","闻尔倦游今闭户，汉庭何日奏长杨。"]},{"t":"寄邝子乾","f":"七言律诗","c":["极目扶溪路渐分，冥鸿西去独离群。","太玄已就窗间草，内景常参石上文。","策蹇难寻西涧雪，寄梅应带北山云。","汉庭好少今何日，更拟冯唐老见君。"]},{"t":"闻讨倭兵回","f":"七言律诗","c":["阵云初散雪霏霏，万里铙歌奏凯归。","徐市东来夷戍垒，庾关南下卷戎衣。","瓜期不待征人喜，刍秣空馀战马肥。","为报单于须款塞，倭奴今日已来威。"]},{"t":"寄福懋上人","f":"七言律诗","c":["吴门兵后转萧条，欲访高僧不惮遥。","夜月竹堂谁听梵，秋烟笠泽几扬桡。","买山应被深公笑，入社那辞慧远招。","古寺钟声霜后近，客船何日过枫桥。"]},{"t":"阿耨塔","f":"七言律诗","c":["劫火销沉白马鸣，山中曾有化人城。","龙听佛法千轮相，鸟下僧斋一磬声。","入定锡飞泉已迸，安禅心静月长明。","阎浮世界须甘露，谁洒清泠惠众生。"]},{"t":"朱真人朝斗坛","f":"七言律诗","c":["彩雾沉沉瑞气浓，步虚声过七星松。","笙箫半在丛霄馆，鸾鹤常依见日峰。","宝鼎暂将明水注，金书仍许白云封。","一辞阿母瑶池宴，长听花台午夜钟。"]},{"t":"林维乔携酒邀予过黎氏山楼","f":"七言律诗","c":["谢氏家林宴赏多，况逢宾从有羊何。","思玄客已还山久，问字人多载酒过。","雪后庭阶喧鸟雀，月中簪弁杂烟萝。","登楼更滞风尘日，徙倚那能不醉歌。"]},{"t":"寄金员外","f":"七言律诗","c":["一从凫舄簉鹓班，汉署仙郎欲见难。","邑长至今思卓茂，州民谁复念丘丹。","御河冰泄归鸿度，禁掖花明立马看。","北望公车犹万里，将随计吏入长安。"]},{"t":"王郡倅应文邀登镇海楼","f":"七言律诗","c":["倦客蓬蒿已十年，中原多难最堪怜。","牂牁流水全通粤，岣嵝归鸿直过燕。","笳鼓渐闻催战舰，关河一望隔烽烟。","江南保障群公在，莫使渔樵病税钱。"]},{"t":"送唐郎中还留都兼寄黄仓曹","f":"七言律诗","c":["严程风雪肃旌旄，君去留京总署劳。","馈饷暂烦萧相国，孝廉谁似范功曹。","红亭握手惟孤剑，白发交情只浊醪。","同舍黄郎应问我，自怜憔悴掩蓬蒿。"]},{"t":"次韵奉和泰泉先生喜惟和授行人","f":"七言律诗","c":["汉庭射策早知名，通籍金门委佩行。","使节远从衔诏去，主恩先慰望乡情。","尧封万里輶轩近，禹甸千山櫑具明。","想见出关家庆日，路旁应认弃繻生。"]},{"t":"泰泉先生元日有作次韵奉和","f":"七言律诗","c":["遥瞻北斗拜枫宸，十载銮坡早乞身。","蓂荚纪元颁历早，椒盘宜寿颂年新。","嵩呼最忆鹓班地，镐宴曾随鹤禁人。","独向天涯吹玉律，罗浮山下万花春。"]},{"t":"夏黄门摄县以纂志见邀局中答梁彦国邓毓元二子","f":"七言律诗","c":["偶来讲肆暂盘桓，祖谢同游自鹖冠。","窗外竹声凭槛听，雨中山色隔城看。","娇莺乍啭衣将换，新火初分食尚寒。","自笑校书非寓直，花期犹阻故人欢。"]},{"t":"秋雨怀仲登贤甫","f":"七言律诗","c":["秋来渐觉故人稀，况复关河雁已飞。","窗雨静闻钟磬响，江风寒入薜萝衣。","还山路远书难寄，滞酒情多客未归。","天际孤舟何处望，题诗空愧谢玄晖。"]},{"t":"十五夜清泉山中待月得云字","f":"七言律诗","c":["空林乌鹊暝依群，九十秋光此夕分。","把酒山中还问月，卷帘天末乍披云。","霜清木叶当窗堕，风急江猿隔岭闻。","玉宇高寒心转切，骖鸾吾欲一从君。"]},{"t":"家慈初度承黎惟敬梁思伯过村居为寿","f":"七言律诗","c":["白发惟堪供菽水，佳晨还得下鹓鸾。","登堂拜母劳公瑾，避地全家愧幼安。","竹径疏烟侵客屦，橘林飞鸟怪儒冠。","荒村浊酒君堪醉，莫惜淹留看药栏。"]},{"t":"同惟敬思伯夜泊浦口","f":"七言律诗","c":["浦口青枫夕照迟，天涯飘泊更何之。","船迎张翰因同载，笛遇王猷更一吹。","渔父每从醒客问，海翁今谢白鸥疑。","十年已共江潭远，岂傍啼猿怨竹枝。"]},{"t":"西樵山谒白沙先生祠","f":"七言律诗","c":["杖舄名山恨不同，今看俎豆白云中。","两楹岂梦当时奠，一亩犹存后代宫。","鹿印砌苔多暮霭，鸟栖坛树已秋风。","江门经笥曾传业，岂但通家似孔融。"]},{"t":"经李山人子长墓","f":"七言律诗","c":["宰木萧萧不可闻，青山宿草最怜君。","乡人已祭先生社，弟子曾营处士坟。","终古黔娄空有谥，百年封禅竟遗文。","束书身后嗟零落，惟见哀猿向白云。"]},{"t":"雨中过喷玉岩","f":"七言律诗","c":["溟濛山色敛残曛，瀑布双垂远渐闻。","珠箔不收千日雨，银河犹泻半空云。","归鸦向树疑将去，坠石冲流响乍分。","谁共香炉峰下坐，濯缨于此息尘氛。"]},{"t":"铁泉庵","f":"七言律诗","c":["岩前旧是子云家，门掩悲泉一道斜。","石室竟藏高士传，山园犹种故侯瓜。","虎看丹灶多年火，树挂诗瓢几度花。","小草尚惭曾出洞，至今猿鸟怨烟霞。"]},{"t":"宝鸭池","f":"七言律诗","c":["瑶水千年王母居，台成青鸭上空虚。","双凫忽去犹馀舄，三鸟将还更寄书。","波转金风惊夕冷，影摇珠树觉秋疏。","丹丘岂是人间世，何似东来过石闾。"]},{"t":"天湖","f":"七言律诗","c":["涧上幽人赋考槃，石泉今得放纶竿。","裘披半似桐江隐，璜在疑从渭水看。","向晚高台含照远，经秋飞瀑入池寒。","烟波岂必投荒饵，六犗连鳌亦不难。"]},{"t":"重阳后一日同梁思伯潘少承岑允穆集苏都谏幼清宅","f":"七言律诗","c":["黄花佳节愁中过，青琐华筵胜处开。","秋色平临天外树，山光半落槛前杯。","郑庄置驿推贤久，疏傅挥金爱客来。","西转玉衡歌欲阕，曙鸦惊起未能回。"]},{"t":"陈推府九十过余山馆始获瞻承赋此上寿","f":"七言律诗","c":["剑津解组赋思玄，八桂成林近海边。","洛邑客逢开社日，济南人拜受经年。","关前紫气占曾过，阁上青藜照不眠。","太史为君将纪异，寿星高照五云天。"]},{"t":"故大司寇刘公之孙尧士来求黄太史碑文却还大庾仆曾拜公于家食因附致哀挽之私","f":"七言律诗","c":["欲悬宝剑何由至，不过山阳亦自悲。","马首北平曾拜日，楸行东武竟封时。","九言黄父今犹记，十字延陵幸有碑。","爱尔凤毛还别去，天涯云树最相思。"]},{"t":"山人艾从之为故司寇刘公来徵黄太史碑文事竣还大庾","f":"七言律诗","c":["白头何自别烟霞，衣褐还山老岁华。","卷有素书遗叔夜，碑成玄冢似侯芭。","囊琴岭北能千里，留药江南又几家。","匹马长亭秋欲尽，陇头何日寄梅花。"]},{"t":"双桐馆为梁思伯赋","f":"七言律诗","c":["草玄多暇此徘徊，旧种双桐覆奕台。","德比三槐名相后，词怜丛桂小山才。","夕阳渐送疏阴转，秋色初惊一叶来。","二仲过从应不厌，蒋园蓬径待君开。"]},{"t":"过宝林僧舍因忆亡友潘启纯","f":"七言律诗","c":["曾伴戴颙栖遁处，今成桑扈返真庵。","井沉桐月香台侧，窗掩松风石涧南。","每借佛灯翻贝蕳，几听僧梵绕花龛。","残经应已封蛛网，犹记山房半夜谈。"]},{"t":"同少承诸子粤秀山观音阁秋望","f":"七言律诗","c":["绀阁秋登海色明，浊醪无限此时情。","千帆拾翠洲前过，双角沉珠浦外声。","带郭蓬蒿犹汉苑，隔河烟火是卢城。","千年皋壤嗟摇落，因向空门悟此生。"]},{"t":"镇海楼同惟敬作","f":"七言律诗","c":["一望河山感慨中，苍苍平楚入长空。","石门北去通秦塞，肄水南来绕汉宫。","虚槛松声沉暝壑，极天秋色送征鸿。","朔南尽是尧封地，愁听樵苏说霸功。"]},{"t":"初冬过诃林寺净隐方丈","f":"七言律诗","c":["故园犹得狎长裾，偶为寻僧过净居。","施食斋前禽乍散，经行坛下树偏疏。","菊花向晚犹堪摘，杮叶经秋尽可书。","且莫攒眉便归去，白莲今日问何如。"]},{"t":"陈公载邀游浮丘山心远亭","f":"七言律诗","c":["洗耳松风渐可听，忽看十里出郊坰。","青山开户朱明馆，绿发悬车白傅亭。","调鹤便思游碧落，观鱼真欲钓沧溟。","与君早约归中阁，四百峰头尽勒铭。"]},{"t":"东山别业为梁少傅赋","f":"七言律诗","c":["策蹇寻君出郭偏，逍遥公后见君贤。","著书已满山中笥，爱月闲挥石上弦。","清梵屡闻黄竹寺，寒溪半出白云泉。","谢安恐为苍生起，深锁松筠又几年。"]},{"t":"黄幼章邀游巢云轩","f":"七言律诗","c":["壶榼幽期在竹扉，黄花三径晚依依。","草堂鹤待人归久，蕙帐云深客到稀。","觅句泉边供茗细，清斋林下折菘肥。","出山愧谢陶弘景，争得当年便拂衣。"]},{"t":"同士鹄贤甫三水夜泊","f":"七言律诗","c":["青枫习习三江口，旅泊欣逢二妙才。","客梦偶随浈水去，塞鸿新度蓟门来。","孤城闭月秋砧急，野戍临江晓角催。","跃马听鸡还此日，十年奔走在天涯。"]},{"t":"闻苏黄门饮黎氏山楼佳句见及和答一首","f":"七言律诗","c":["衣冠洛下几追随，一出风尘怅别离。","北海清尊多好客，南楼明月负佳期。","归与不为鲈鱼脍，隐矣谁招桂树词。","献纳近臣劳记忆，腐儒真愧故人知。"]},{"t":"病后","f":"七言律诗","c":["经年疲病愧蹉跎，尚可樵薪醉且歌。","佐锻每于灌园后，挥锄长是带经多。","霜清狮岭劳场圃，雨过龙津理钓蓑。","已笑杜陵忧太早，归朝筋力定如何。"]},{"t":"文太史九十寄上","f":"七言律诗","c":["山中杖屦道弥尊，曾忆当年一扫门。","天许东吴开寿域，人从南海望台垣。","书传掌故儒宗学，酒洽乡人圣主恩。","汉室辟雍还酳爵，苍颜黄发老乾坤。"]},{"t":"答黎惟仁见寄","f":"七言律诗","c":["卧病芙蓉溪上村，心期无地与君论。","社中僧散归庐岳，渡口人来问鹿门。","岁晏鱼鸿愁莫至，径荒松菊喜犹存。","报书欲访安期去，四百名山好避諠。"]},{"t":"寄龙孟采文学","f":"七言律诗","c":["谈经东郡未蹉跎，惆怅其如远别何。","万里塞鸿传信少，三年山雪下帷多。","城临古木陶丘镇，窗送孤帆马颊河。","闻尔春风入京洛，早传消息慰沧波。"]},{"t":"上元后夕顾玄纬官舍宴集","f":"七言律诗","c":["五夜尚馀镫市兴，一尊仍引褐衣閒。","星摇海上常朝斗，阁倚城头每见山。","曙色渐分旌旆外，春声多在鼓鼙间。","顾荣不是江东客，只恐承明计日还。"]},{"t":"春日同顾玄纬游石虹湖","f":"七言律诗","c":["谬敬宁劳一坐倾，石湖犹得伴君行。","风烟半入刘王苑，山海周遭赵尉城。","帆外日斜平楚尽，鸥边冰断早潮生。","彤云北望朝台路，赋客江南万里情。"]},{"t":"送丁戊山人返闽中","f":"七言律诗","c":["白日乍逢勾漏令，青山归觐武夷君。","手扶藜杖经溪雪，囊贮荷衣度海云。","绛节只将鸡犬去，赤霄终远凤皇群。","虹桥宴后还来否，祇恐璈笙不可闻。"]},{"t":"潘道颐夜过滋兰精舍见访","f":"七言律诗","c":["杨生欲卜岷阳宅，谢史将归石井山。","好事特来频载酒，故人相见一开关。","春声宝瑟风前泛，溪影青蓑月下还。","别尔不胜南浦望，鹤岑长在白云间。"]},{"t":"答黎吏部惟和岭下见寄","f":"七言律诗","c":["北去关河信息稀，岭头曾见几鸿飞。","别时驱马遵原隰，到日听莺入省闱。","阊阖云霄双玉舄，江湖烟雨一荷衣。","君今且上山公启，宁得逢人问钓矶。"]},{"t":"寄梁舍人思伯","f":"七言律诗","c":["紫宸肃穆拜恩时，裴瓒风神众所推。","春满龙池三月雨，日高鸡树万年枝。","看花右掖封章少，视草西台刻漏迟。","共识平津能待士，由来东阁几人窥。"]},{"t":"游狮岭龙岩遇雨宿田舍","f":"七言律诗","c":["山北山南近可游，农谈西夕偶淹留。","茅茨喜就田更宿，鸡犬愁闻里正求。","鼓吹雨沉莎泽冷，管箫风袅豆篱秋。","陶公拥耒怀千古，束带宁堪见督邮。"]},{"t":"次韵酬黄幼章见寄","f":"七言律诗","c":["历落生涯只钓矶，城中车马到应稀。","溪园得雨缃梨熟，水国先秋紫蟹肥。","别久林僧频有约，病多酒客每相违。","劳君尺素能题寄，谁向襄阳问布衣。"]},{"t":"送罗明府改教荆州","f":"七言律诗","c":["九十九洲烟水流，到时应及渚宫秋。","马融绛帐今犹在，陶令清尊谁共游。","天畔看山明月峡，风前散帙曲江楼。","城西茅舍君堪赋，莫道荆南未可留。"]},{"t":"飓风涨落招晋安王山人","f":"七言律诗","c":["沧波洗屐出柴关，渔钓何人到此间。","江水未漂何胤室，竹林深掩戴颙山。","三轮公调年来异，四壁家徒日共闲。","泾上樵风今可帆，夕阳长望一蓑还。"]},{"t":"同潘少承入西樵山卜居铁泉精舍二首 其一","f":"七言律诗","c":["鸡犬薪蒸共一车，入山真与世情疏。","家随子季移秦望，粮学通明食禹馀。","瓠叶尚堪供享射，秫田那得废耕锄。","植林开涧吾生事，谁向名山问著书。"]},{"t":"同潘少承入西樵山卜居铁泉精舍二首 其二","f":"七言律诗","c":["山泽神交二十年，素情台尚得君贤。","閒游径就天峰去，晏坐醒寻海石眠。","风起于菟看杏地，露寒阿对灌蔬泉。","闭门白发萧萧在，何事虚名世上传。"]},{"t":"夜过云谷洞","f":"七言律诗","c":["豹林只隔数峰西，涉涧寻君月未低。","简子深秋停露照，鞠侯清夜过云啼。","泉香石铫聊堪煮，松响风琴不用携。","谁见幽人独来往，寒光明灭在前溪。"]},{"t":"晓登玉廪峰","f":"七言律诗","c":["独吹铁笛一临霞，青玉坛边散晓鸦。","洞逼金华羊是石，岭疑缑氏鹤为花。","瀑前木客支茶灶，云里山都问酒家。","莫遣移文羞涧壑，周颙真欲老天涯。"]},{"t":"由烟霞洞登大科峰绝顶","f":"七言律诗","c":["灵气飘飘满石坛，峰头长啸九秋残。","大荒风起千松乱，碧落天高片月寒。","羽客共将金偈答，山僧闲把玉书看。","难向外人言此乐，白云深恋鹿皮冠。"]},{"t":"西樵山中忆惟敬内翰思伯中舍","f":"七言律诗","c":["故人昔共此栖迟，瀑布峰前忆别时。","骑省谁能怜国宝，士林今已得山披。","清猿自和斋中磬，野鹿閒窥石上棋。","回首白云多出岫，独看秋雁一相思。"]},{"t":"送蔄尊师往郴州","f":"七言律诗","c":["仙官南去洞庭南，衡岳诸峰更一探。","黄石早为松子客，青童曾是木公男。","羽衣轻举淩苍雾，毛节遥瞻入翠岚。","甲子从今三百后，东门楼上望苏耽。"]},{"t":"次韵答丁戊山人武夷见寄二首 其一","f":"七言律诗","c":["去年勾漏始归来，太姥虹桥待尔回。","海送羽车占异气，石藏金匮识仙才。","汞铅几处留丹灶，脯炙何时共酒杯。","莫向岩头吹铁笛，幔亭风急万山哀。"]},{"t":"次韵答丁戊山人武夷见寄二首 其二","f":"七言律诗","c":["玉椷何处寄新诗，消息惟应海鹤知。","三洞丹经瞳炯炯，万峰黄帽鬓丝丝。","云浮飙室朝元地，月过天坛礼斗时。","为问青精何日至，山禽将献赤龙芝。"]},{"t":"寄何元朗","f":"七言律诗","c":["曾闻子季移家处，小阁云深手自关。","良常不隔神仙宅，秦望犹传大小山。","金马直来孤梦远，银鱼焚后一身閒。","知君颇有梅花句，岭上何时寄驿还。"]},{"t":"潮州萧君达偕郑国彦方邦哲张子晦过访以诗见诒用韵兼酬四子","f":"七言律诗","c":["客邸逢君醉几回，岂缘乡国共衔杯。","西京正待张衡赋，南海谁如赵德才。","楯鼻自将飞檄去，刀头何必问书来。","清秋最是披襟日，更约双骖上汉台。"]},{"t":"元夕出城访董山人","f":"七言律诗","c":["城里歌钟几万家，独寻阒寂到烟霞。","路逢草屩知居士，山隐铜鞮问伯华。","碧鉴海环赪石起，黄冈峰引白云斜。","骖驔归骑犹携客，醉向祇园火树花。"]},{"t":"同何太仆泛舟作","f":"七言律诗","c":["桂楫飘飘珠浦前，上书宁待鉴湖田。","归同宾客居閒口，恩在君王赐告年。","月下锦袍江祖石，烟中翠被鄂君船。","乘风直到金银阙，谁道淩虚不是仙。"]},{"t":"送王总戎东征","f":"七言律诗","c":["汉将征蛮旧策勋，提兵东下阵如云。","珠旗明月天边出，玉笛秋风檄外闻。","幕府功多横海战，楼船令待伏波军。","即看捕虏驰还奏，只以升平答圣君。"]},{"t":"壬戌七月十五夜同诸亲友泛舟佛教海","f":"七言律诗","c":["赋成忆在楚江干，今夕何夕斯游难。","自操兰桡波里白，不禁枫叶霜前丹。","水落石出鲈鱼上，月明星稀乌鹊寒。","醉倚柁楼望天末，西风萧萧羌笛残。"]},{"t":"九日登观海楼送陈士鹄北上","f":"七言律诗","c":["西风平楚莽萧萧，天畔登楼正泬寥。","万户砧声催夕照，千帆涛色送秋潮。","青山谢傅相将去，白首冯公尚未招。","此地明年重忆汝，佩萸应在紫宸朝。"]},{"t":"同陈潜甫叶伯埙吴叔颐罗见参吴伯纶罗曜文梁仲登夜集吴氏池亭时余将北上得秋字","f":"七言律诗","c":["浊醪犹有鹔鹴裘，下马张镫且暂留。","客路风尘双短鬓，宦情天地一孤舟。","袂分此夜清溪月，书寄何时白雁秋。","别后荆南君莫赋，肯令王粲滞江楼。"]},{"t":"登快阁遂谒山谷祠和石刻十韵","f":"七言古诗","c":["千峰匡岳亭亭立，万里澄江滚滚来。","文水远流诸港入，禅官高阁半云开。","川原日照新楼橹，城郭烟侵废草莱。","旧邑飞凫留玉舄，几时孤鹤下山台。","浮沉谩忆神仙令，留滞空怜太史才。","尊酒囊琴皆寂寞，斜阳归雁独悲哀。","年深短句馀残墨，迹古遗碑翳绿苔。","肃肃祠堂犹俎豆，翛翛图像已尘埃。","高风一代人何在，长路孤舟客自回。","双井白杨应咫尺，不堪西望独徘徊。"]},{"t":"出云谷关泛樵湖","f":"七言古诗","c":["三关迢递指津途，舍策庄前问钓舻。","泽豹未能终隐矣，山猿其奈怅归乎。","蓼江南下龙江近，一曲西沿九曲殊。","闸里泉流肥晚稻，渚边霜色冷秋菰。","陆洲租税惟莲实，百滘园林半木奴。","风物蕳村遥可见，雁群急水乱相呼。","帆飞似有冯夷导，川静无烦海若驱。","落落沙坪低草树，茫茫江浦散鸥凫。","萦纡涧壑疑蓝水，回合风烟似鉴湖。","康乐未忘彭蠡望，右丞犹恋辋川图。","曾经驻舄情何限，更着浮槎兴不孤。","咫尺仙山何处是，夜来魂梦绕清都。"]},{"t":"八月碧桃花十韵","f":"七言古诗","c":["塌羽南飞秋欲暮，西风归路正萧萧。","城边落雁惊枫叶，江上清霜折柳条。","岂意蓬门留晚照，故教桃萼媚春娇。","恍疑玉岭峰头见，乍似霜林树下飘。","水碧着枝偏淡淡，华秾拂槛更夭夭。","武陵路远寻源入，度索山深涉海遥。","游客成蹊应已少，幽人无限不须销。","名亭尚爱无双句，载酒还过第五桥。","露井不堪摇落后，缃园犹及艳阳朝。","螃螗见说多灵实，便理扶桑万里桡。"]},{"t":"送吴而待守归州","f":"七言古诗","c":["汉室分符属俊良，喜君得郡古丹阳。","去时佩印辞京邸，到日题诗出射堂。","大别东连荒梦泽，潜江南下乱潇湘。","三休竟望荆台远，九辨空思汨水长。","熊绎旧邦留荜辂，灵均遗庙洁椒浆。","竹枝渐习巴渝曲，月峡遥归蜀客航。","几处种山还采蜡，何人驻马问耕桑。","拔河应笑祈农异，竞渡堪怜习俗狂。","百里芜城夔子国，千家菰米楚人乡。","讼庭山鸟时时下，燕寝江蓠冉冉香。","露冕褰帷真此地，浮云征雁自殊方。","吴公治行推高第，禁掖行瞻日月光。"]},{"t":"雪中过大庾岭","f":"五言绝句","c":["横浦关门下，秦时塞上沙。","高楼吹玉笛，片片是梅花。"]},{"t":"玉枕山","f":"五言绝句","c":["山幄盘紫逻，石床白云过。","鸡犬天上稀，惟有仙人卧。"]},{"t":"何天宿鸥溪别墅四首 其一","f":"五言绝句","c":["岭北荆榛路，城西浦溆深。","白鸥时自下，知尔海翁心。"]},{"t":"何天宿鸥溪别墅四首 其二","f":"五言绝句","c":["袯襫未能舍，桔槔曾不持。","汉阴机已息，谷口隐何疑。"]},{"t":"何天宿鸥溪别墅四首 其三","f":"五言绝句","c":["颇适濠梁兴，谁云不似鱼。","山中缃帙少，惟有漆园书。"]},{"t":"何天宿鸥溪别墅四首 其四","f":"五言绝句","c":["导水章江入，看云庾岭开。","柴门君莫闭，日许问奇来。"]},{"t":"同王武昌詹侍御游西华山","f":"五言绝句","c":["南峤飘幡地，西华载酒年。","使君携客去，何似谢临川。"]},{"t":"嘉祐寺与禋公别","f":"五言绝句","c":["开社白莲秋，出山余暂游。","君忆柴桑客，江边一倚楼。"]},{"t":"赠苏四赴安西","f":"五言绝句","c":["苏卿西度漠，征马别踌躇。","汉使长安远，无忘雁足书。"]},{"t":"访蔡世新","f":"五言绝句","c":["墨池呼鸟食，书架傍花开。","奇字虽能问，惭非载酒来。"]},{"t":"吉州别萧曙","f":"五言绝句","c":["高浪黄牛石，长亭白鹭洲。","岭头千里水，何事入江流。"]},{"t":"滕王阁送邓巴州二首 其一","f":"五言绝句","c":["南浦不可望，潇湘何处秋。","好将明主意，露冕入巴州。"]},{"t":"滕王阁送邓巴州二首 其二","f":"五言绝句","c":["君去西川路，知余滞楚乡。","巴江书莫寄，九派是浔阳。"]},{"t":"南浦驿送少室山人之襄阳二首 其一","f":"五言绝句","c":["嵩少何年出，遥寻庞德公。","宁知高士宅，只在鹿门中。"]},{"t":"南浦驿送少室山人之襄阳二首 其二","f":"五言绝句","c":["远别伤春日，襄阳路更西。","习家池尚在，堪听白铜鞮。"]},{"t":"水次逢碧桃","f":"五言绝句","c":["桃叶复桃花，秦淮是汝家。","渡头风雨夜，惆怅忆天涯。"]},{"t":"湖口忆子文","f":"五言绝句","c":["日落劳延伫，江长动远思。","汀洲采兰杜，惆怅欲遗谁。"]},{"t":"南京三首 其一","f":"五言绝句","c":["金门迎王气，丹阙俯神州。","苑柳摇春殿，宫鸦拂曙楼。"]},{"t":"南京三首 其二","f":"五言绝句","c":["江左开基日，山河入地图。","千秋龙虎国，万里帝王都。"]},{"t":"南京三首 其三","f":"五言绝句","c":["青云鳷鹊观，赤日凤皇台。","司马文园病，谁言献赋才。"]},{"t":"秦淮","f":"五言绝句","c":["玉树歌已残，秦淮不堪泊。","女墙明月高，江枫夜深落。"]},{"t":"登报恩寺塔","f":"五言绝句","c":["塔倚长干寺，经传白下僧。","六朝城市尽，江涌佛前灯。"]},{"t":"宋博士邀饮凭虚阁玩月","f":"五言绝句","c":["高阁月初朗，他乡酒易酣。","今宵同作客，不记是江南。"]},{"t":"灵应观玉皇阁临乌龙潭","f":"五言绝句","c":["台城遣恨多，山阁今独倚。","玉笙何处来，月照乌龙水。"]},{"t":"海天僧同余过朝天宫周道士馆不值道士","f":"五言绝句","c":["谁言匡阜远，亦似石城西。","观主今何去，殷勤过虎溪。"]},{"t":"扬子江上寄伦膳部","f":"五言绝句","c":["夷犹望京邑，江月听秋潮。","谁念扁舟客，新林向版桥。"]},{"t":"溧阳孙生邀游三山饮听江楼二首 其一","f":"五言绝句","c":["风引孤舟行，登楼听呜咽。","春江万里流，半是巴山雪。"]},{"t":"溧阳孙生邀游三山饮听江楼二首 其二","f":"五言绝句","c":["解裘换斗酒，江上同兹夕。","试问李青莲，何如落星石。"]},{"t":"题王子新所藏赵承旨山水小景二首 其一","f":"五言绝句","c":["虎溪流曲泉，鹿门隐高树。","山人不入城，日暮自来去。"]},{"t":"题王子新所藏赵承旨山水小景二首 其二","f":"五言绝句","c":["落日芙蓉渚，轻风杨柳矶。","船头独吹笛，时见白沤飞。"]},{"t":"闻笛","f":"五言绝句","c":["参差江上笛，长似怨湘君。","况复离群夜，高斋月下闻。"]},{"t":"题画赠蔡比部子木","f":"五言绝句","c":["远目凝椒浦，扁舟下桂潭。","青天鸿雁起，秋色满江南。"]},{"t":"游金陵还家作","f":"五言绝句","c":["远游不称意，裘马半摧残。","惟有罗浮色，归人日日看。"]},{"t":"从化山水十首 其一 鹧鸪山","f":"五言绝句","c":["山倚鹧鸪岭，城临白马场。","东风无限事，芳草自斜阳。"]},{"t":"从化山水十首 其二 狮子岭","f":"五言绝句","c":["何年天目峰，飞在此山侧。","空林夜吼声，百兽潜踪迹。"]},{"t":"从化山水十首 其三 云台山","f":"五言绝句","c":["马援屯兵处，南征汉将雄。","椒房难掩绩，铭勒万山中。"]},{"t":"从化山水十首 其四 杨溪洞","f":"五言绝句","c":["明都唐宅在，扬越舜巡馀。","洞里千寻石，应藏太史书。"]},{"t":"从化山水十首 其五 韶洞","f":"五言绝句","c":["重华不可作，雅乐尚堪闻。","风动箫韶起，馀音袅白云。"]},{"t":"从化山水十首 其六 北山瀑布泉","f":"五言绝句","c":["云顶白泉飞，珠箔千重挂。","仙衣惊尽湿，彷佛香炉下。"]},{"t":"从化山水十首 其七 黄纛嶂","f":"五言绝句","c":["尉陀无旧宅，陆贾有新祠。","羁迹今消歇，秋山草露垂。"]},{"t":"从化山水十首 其八 武台","f":"五言绝句","c":["南武千年国，将军百尺台。","何人通越路，西引夜郎来。"]},{"t":"从化山水十首 其九 流溪","f":"五言绝句","c":["秋山枫叶赤，春水鳜鱼肥。","独傍渔船去，沙头雁不飞。"]},{"t":"从化山水十首 其十 龙潭水","f":"五言绝句","c":["肤寸云初出，须臾满太空。","只知天下雨，谁识是龙功。"]},{"t":"西樵登通天台","f":"五言绝句","c":["何年开一窍，神斧凿玲珑。","登天从此路，人在绿云中。"]},{"t":"翠岩","f":"五言绝句","c":["风飘鸣玉音，爽气生衣袂。","上攀百尺藤，朝夕挹山翠。"]},{"t":"七松台","f":"五言绝句","c":["句曲万松山，西樵七松岭。","山人听风涛，何似陶弘景。"]},{"t":"夜起观池上荷花","f":"五言绝句","c":["炎歊不可居，起濯风露里。","解佩欲遗谁，盈盈涉秋水。"]},{"t":"伏波桥下别士鹄","f":"五言绝句","c":["携手河梁日，梅花欲满枝。","他时逢驿使，寄尔一相思。"]},{"t":"三月晦日别黄贤甫","f":"五言绝句","c":["山馆欲分襟，况是春归节。","不惜落花飞，惟愁与君别。"]},{"t":"枕上","f":"五言绝句","c":["枕上书难寄，羁愁久病中。","闭门三日雨，归梦五更风。"]},{"t":"病中贤甫未至","f":"五言绝句","c":["玉笥久不读，瑶觞宁复持。","钟残山馆雨，正是忆君时。"]},{"t":"江馆雨中待陈梦庚二首 其一","f":"五言绝句","c":["松围村舍暝，花落涧泉香。","独听萧萧雨，孤莺啼夕阳。"]},{"t":"江馆雨中待陈梦庚二首 其二","f":"五言绝句","c":["昨日过花朝，红芳暗烟雨。","蘼芜绿渐多，美人隔春渚。"]},{"t":"西樵山人寄茶","f":"五言绝句","c":["山侣念别久，云芽寄荜门。","竹下一烹啜，幽人时与言。"]},{"t":"林中闻莺","f":"五言绝句","c":["绮楼花万树，睍睆足春声。","复此林间听，深山无世情。"]},{"t":"寄孔元锡","f":"五言绝句","c":["踯躅开无数，辛夷尚未稀。","子规何处去，早唤故人归。"]},{"t":"朝汉台怀古二首 其一","f":"五言绝句","c":["瓯骆犹归粤，河山尚隔秦。","谁令南海尉，终作汉藩臣。"]},{"t":"朝汉台怀古二首 其二","f":"五言绝句","c":["童子请缨日，老夫黄屋来。","楼船何自下，麋鹿至今哀。"]},{"t":"晓起出溪上","f":"五言绝句","c":["住山深几许，晓送林僧语。","溪涌石楠花，因知昨宵雨。"]},{"t":"春日期少承过洲上","f":"五言绝句","c":["寒食君有期，江烟过三月。","荼蘼渐欲开，容易花成雪。"]},{"t":"长信秋词二首 其一","f":"五言绝句","c":["重门葳蕤锁，苔深履綦绝。","起看玉阶霜，不似昭阳月。"]},{"t":"长信秋词二首 其二","f":"五言绝句","c":["新凉罗袂卷，愁更理秋衣。","不忍持金剪，梁间半似飞。"]},{"t":"征妇怨二首 其一","f":"五言绝句","c":["远信过张掖，征衣寄陇西。","夜乌惊妾梦，底事傍窗啼。"]},{"t":"征妇怨二首 其二","f":"五言绝句","c":["近撤黄花戍，新屯豹海兵。","可怜眉子月，西照受降城。"]},{"t":"闻筝","f":"五言绝句","c":["秦声何处奏，花落玉尊前。","无限佳人思，春风十二弦。"]},{"t":"题朱子朗画二首 其一","f":"古风","c":["槛外碧波万里，窗间紫逻千回。","日暮无人载酒，门前问字谁来。"]},{"t":"题朱子朗画二首 其二","f":"古风","c":["秋色山山木落，夕阳浦浦帆归。","有客共登高阁，西风鲈鳜初肥。"]},{"t":"入烟霞后洞","f":"古风","c":["千峰欲淩倒景，万里可御泠风。","试问烟霞洞口，何如鸡犬云中。"]},{"t":"寄远词二首 其一","f":"古风","c":["珠尽啼痕犹凝，玉消愁色方新。","明月关山万里，回文欲寄情人。"]},{"t":"寄远词二首 其二","f":"古风","c":["荡子经年未还，几看破镜云间。","只道雁衔书至，雁门何处关山。"]},{"t":"洲上四首 其一","f":"古风","c":["灌畦稍能种药，临水亦可弹琴。","汉阴何有机事，坛下只送挐音。"]},{"t":"洲上四首 其二","f":"古风","c":["稚子闲来弄影，丈人于此逃名。","高枕独看春雨，沧涨几濯尘缨。"]},{"t":"洲上四首 其三","f":"古风","c":["生事庭前流水，世情竹外青山。","抱膝长吟梁父，为园不闭柴关。"]},{"t":"洲上四首 其四","f":"古风","c":["长江万里扁舟，春水孤烟白鸥。","何处高人持钓，百年吾道沧洲。"]},{"t":"马上望黄鼎诸村","f":"古风","c":["风雨声中落木，茅茨深处鸣鸡。","过尽平湖十里，人家犹隔瀼西。"]},{"t":"同罗思诚登玉镜台","f":"古风","c":["前不可见既往，后不可见将来。","眼中之人未老，百年斗酒登台。"]},{"t":"经郁水","f":"古风","c":["漓水几时进帆，黔江一道惊波。","驰义发兵何处，夜郎西下牂牁。"]},{"t":"题太玄观道士壁","f":"七言绝句","c":["羽客持经白日长，石门阴洞楚云凉。","空闻丹伏降龙虎，何处箫声下凤凰。"]},{"t":"发横浦驿大司寇刘公邀詹侍御王武昌移舟饯送留别三首 其一","f":"七言绝句","c":["挂席沙头津鼓催，群公出祖尽千杯。","介休自愧龙门客，何似仙舟洛下来。"]},{"t":"发横浦驿大司寇刘公邀詹侍御王武昌移舟饯送留别三首 其二","f":"七言绝句","c":["楚水吴山积雪残，烟花东下秣陵看。","清歌送酒不能醉，回首江枫一路寒。"]},{"t":"发横浦驿大司寇刘公邀詹侍御王武昌移舟饯送留别三首 其三","f":"七言绝句","c":["两岸猿声傍客啼，思君烟草易凄凄。","扁舟幸有江湖在，那得春潮尽向西。"]},{"t":"早春寓南康官舍寄嘉祐寺禋上人","f":"七言绝句","c":["逢师岭下问三乘，几度吟诗绕佛灯。","别后听莺官舍晚，每从闭处忆高僧。"]},{"t":"同王户曹发南康别郭蔡二子","f":"七言绝句","c":["杨柳青青水驿楼，谁期今上鄂君舟。","从来南浦销魂处，醉下烟波万里愁。"]},{"t":"巴陵刘宗道自吉安与余同载至九江口相别","f":"七言绝句","c":["雨中同上吉州船，分手浔阳思惘然。","明日思君是何处，万行烟树入湘川。"]},{"t":"答刘宗道别后见寄","f":"七言绝句","c":["浔阳别后叹离居，雁尽谁期更有书。","西去潇湘八千里，前途何处望双鱼。"]},{"t":"豫章留诸公二首 其一","f":"七言绝句","c":["贵家公子玉鞭长，下马相逢大道傍。","日暮衔杯怅离别，不堪烟雨折垂杨。"]},{"t":"豫章留诸公二首 其二","f":"七言绝句","c":["南浦楼前风色新，主人送别玳筵春。","他时若上滕王阁，为念江湖万里人。"]},{"t":"春日豫章游览十首 其一","f":"七言绝句","c":["襟江带湖古豫章，西望西山磐石梁。","松门石镜不可到，天际孤帆烟浪长。"]},{"t":"春日豫章游览十首 其二","f":"七言绝句","c":["南控蛮荆作重都，滕王高阁天下无。","洪州自昔蛟龙穴，章水今为鱼鳖湖。"]},{"t":"春日豫章游览十首 其三","f":"七言绝句","c":["章江门外江水西，南浦亭前春日低。","桂楫兰桡恣容与，晚风摇过斗门堤。"]},{"t":"春日豫章游览十首 其四","f":"七言绝句","c":["市汊渔父豢鸬鹚，芦下挐音来不迟。","却怜榉柳留江畔，自在蜻蜓立钓丝。"]},{"t":"春日豫章游览十首 其五","f":"七言绝句","c":["江头三月雨不止，新水昨添一尺强。","鸂鶒鹳鹅夜相唤，鄱湖东下乱潇湘。"]},{"t":"春日豫章游览十首 其六","f":"七言绝句","c":["商帆估楫太留连，晓来打鼓齐开船。","直下浔阳三百里，莫愁家在石城边。"]},{"t":"春日豫章游览十首 其七","f":"七言绝句","c":["城边酒楼帘昼垂，吴姬楚女斗腰支。","金鞭折柳不肯下，愁杀江南游侠儿。"]},{"t":"春日豫章游览十首 其八","f":"七言绝句","c":["千枝杏花高照门，脩竹夹池如兔园。","自昔西江尊帝子，只今南国奉王孙。"]},{"t":"春日豫章游览十首 其九","f":"七言绝句","c":["春晴彩绣簇湖边，百花洲前更可怜。","白马青丝三月路，棠梨杨柳万家烟。"]},{"t":"春日豫章游览十首 其十","f":"七言绝句","c":["千花万花日暮飞，石头渡西江舸稀。","无钱取醉禁愁得，芳草如烟人未归。"]},{"t":"鄱湖歌九首 其一","f":"七言绝句","c":["苍茫水府大江关，万里西来楚蜀间。","彭蠡若为云梦泽，匡庐应作剑门山。"]},{"t":"鄱湖歌九首 其二","f":"七言绝句","c":["南北波涛相对愁，水犀军士向南州。","英雄割据今何在，惟见江湖日夜流。"]},{"t":"鄱湖歌九首 其三","f":"七言绝句","c":["西出岷山入海东，章江今汇一湖中。","玉简曾逢苍水使，石铭犹见紫霄宫。"]},{"t":"鄱湖歌九首 其四","f":"七言绝句","c":["江左楼船伐汉时，鄱阳南下遽班师。","百战将军曾庙食，至今遗老想旌旗。"]},{"t":"鄱湖歌九首 其五","f":"七言绝句","c":["康郎山下羽旄开，六军齐唱凯歌回。","高皇神武雄千古，苏竣卢循伪汉才。"]},{"t":"鄱湖歌九首 其六","f":"七言绝句","c":["庐岳风烟从古开，御碑传诏九重来。","天池锦绣丹青合，五色云缠白鹿台。"]},{"t":"鄱湖歌九首 其七","f":"七言绝句","c":["浔阳九派合溟濛，浪击雷翻天地中。","贾客渔翁恣来往，帆樯倾仄势连空。"]},{"t":"鄱湖歌九首 其八","f":"七言绝句","c":["楚女绣襦鸣赵瑟，越人箫鼓唱吴歌。","珍珠象齿由来贵，估贩宁论万里波。"]},{"t":"鄱湖歌九首 其九","f":"七言绝句","c":["湓浦城边桑落洲，匡山斜对庾家楼。","扬澜左蠡连天远，鸂鶒鸬鹚无数游。"]},{"t":"金陵览古","f":"七言绝句","c":["石头踞虎已千年，铁锁沉江事可怜。","惟有南朝旧歌舞，至今犹在绮罗边。"]},{"t":"大中桥晚眺","f":"七言绝句","c":["佳气葱芊望不遥，汉家宫殿切丛霄。","五陵车马今何在，依旧斜阳白下桥。"]},{"t":"报恩寺塔灯","f":"七言绝句","c":["九级琉璃净土旁，帝城今现玉毫光。","因看塔火知生灭，未必高僧舍利藏。"]},{"t":"钟山二首 其一","f":"七言绝句","c":["钟山东望碧岧峣，玉殿金门隔绛霄。","忆自鼎湖弓坠后，万年长受岳灵朝。"]},{"t":"钟山二首 其二","f":"七言绝句","c":["松柏萧萧御道长，金衣绣袷羽林郎。","上陵一曲铙歌动，千骑曾闻从武皇。"]},{"t":"幕府山怀古","f":"七言绝句","c":["渡江五马一为龙，开府勋名勒景钟。","西望洛阳宫殿远，河山无处不边烽。"]},{"t":"鸡鸣寺塔眺玄武湖","f":"七言绝句","c":["乐游苑外夕阳沉，玄武堤边秋草深。","何处飘零江左客，不禁烟桨五湖心。"]},{"t":"忆宋霖望刘用时游西湖未返","f":"七言绝句","c":["姑苏城下别风烟，闻尔从师上浙船。","遥想女儿湖上醉，浴凫飞鹭锦帆边。"]},{"t":"过姑苏访郭郡博","f":"七言绝句","c":["高士传家更有诗，偶从岭外荷君知。","平原文学推匡鼎，此去吴门一解颐。"]},{"t":"同郭郡博徐茂才登郡楼望太湖","f":"七言绝句","c":["青山海涌石巑岏，楼上清秋笠泽寒。","欲挟灵威丈人去，金庭玉霤醉中看。"]},{"t":"逢沅陵客因讯胡用颐","f":"七言绝句","c":["龙江阙下惜离群，岭外逢人一问君。","回首旧游千万里，澧兰沅芷不相闻。"]},{"t":"得徐叔子归长沙消息","f":"七言绝句","c":["三年楚客独还家，北望京华路转赊。","从此梦中难觅汝，不知何处是长沙。"]},{"t":"春别曲四首 其一","f":"七言绝句","c":["寂寂青楼大道边，反反朱萼绮疏前。","可怜万里关山月，无那房栊照独眠。"]},{"t":"春别曲四首 其二","f":"七言绝句","c":["门前江水去来潮，独下西洲路转遥。","夜月葡萄萦锦树，春风杨柳拂河桥。"]},{"t":"春别曲四首 其三","f":"七言绝句","c":["自怜机上回文锦，偏恨堂前并蒂花。","年华不及逢君色，春信何由到妾家。"]},{"t":"春别曲四首 其四","f":"七言绝句","c":["蛱蝶双双度晚风，鸳鸯两两小池东。","愿随萧史升台上，恨逐嫦娥戏月中。"]},{"t":"九月十五夜将赴苍梧舟中望月","f":"七言绝句","c":["客里中秋赏已违，天涯凉月倍光辉。","却怜少妇长相忆，何事征人独未归。"]},{"t":"送陈大赴清远兼寄杨维舟","f":"七言绝句","c":["寺里题名杨柳新，君游中宿更逢春。","遥知杨子谈经处，共向山阿忆美人。"]},{"t":"泛舟江上戏作采莲曲三首 其一","f":"七言绝句","c":["兰舟忆昔下横塘，莲花初开莲叶长。","谁道今朝鶗鴂至，回桡愁见两鸳鸯。"]},{"t":"泛舟江上戏作采莲曲三首 其二","f":"七言绝句","c":["浦口齐歌出荡边，叶残花败未回船。","风吹罗袖沾微雨，道是无情亦可怜。"]},{"t":"泛舟江上戏作采莲曲三首 其三","f":"七言绝句","c":["雨过蘼芜绿满洲，一双鸂鶒对沉浮。","王孙画舫归何晚，日暮湘江无那愁。"]},{"t":"题画美人","f":"七言绝句","c":["吹罢鸾箫斗柄高，旧人惟有薜阳陶。","翻思十载扬州月，曾照船头白锦袍。"]},{"t":"和黎惟敬寄意二首 其一","f":"七言绝句","c":["肠断西风荷芰衣，搴舟日暮浦烟微。","鄂君翠被今何在，青草湖边一棹飞。"]},{"t":"和黎惟敬寄意二首 其二","f":"七言绝句","c":["十二巫山日欲曛，相思谁更梦为云。","烟波渺渺孤舟远，独折疏麻一寄君。"]},{"t":"题思伯画","f":"七言绝句","c":["摵摵秋风隐高树，黄叶苍苔满庭户。","青山自有下帷人，知是广川读书处。"]},{"t":"题惟敬画","f":"七言绝句","c":["雾阁芸窗白石霏，夜寒轻飏五铢衣。","仙人合在芙蓉馆，并驾青鸾上翠微。"]},{"t":"山池见月","f":"七言绝句","c":["月色波光静倚阑，夜深萧飒独惊寒。","临池对影长忧别，何况天涯别后看。"]},{"t":"题文太史山水小幅二首 其一","f":"七言绝句","c":["绿树溪边一草堂，风流应是辋川庄。","题诗好在芙蓉沜，独下兰桡思渺茫。"]},{"t":"题文太史山水小幅二首 其二","f":"七言绝句","c":["精舍新开剡水滨，闭门风雪四无邻。","前溪夜静闻篙桨，知有扁舟乘兴人。"]},{"t":"送玉雨","f":"七言绝句","c":["曾向君家醉玉觥，岭南今日送飞旌。","相看只有双垂泪，马首无从拜北平。"]},{"t":"闺情","f":"七言绝句","c":["双燕风斜款款低，春深楼上早归栖。","郎骑白马向何处，妾在临邛西更西。"]},{"t":"登粤王台","f":"七言绝句","c":["呼鸾道上粤王台，粤王如今安在哉。","惟有太行秋雁字，一年一度一飞来。"]},{"t":"池上","f":"七言绝句","c":["群鱼圉圉足池水，雨过忽添一尺强。","移向长江看变化，云涛千顷更禁当。"]},{"t":"寄郑克一","f":"七言绝句","c":["故人高卧久藏名，有约来同旧酒鎗。","闻道公车求茂异，名儒将召郑康成。"]},{"t":"题西洲精舍图","f":"七言绝句","c":["精庐新卜蓼花洲，隐几萧然已觉秋。","坞西有客期未至，日暮临流看白鸥。"]},{"t":"七月八夜山馆纳凉","f":"七言绝句","c":["淅淅金风吹玉扉，夜深清露坠罗衣。","谁言欢逐昨宵去，银渚含情似未归。"]},{"t":"班姬怨","f":"七言绝句","c":["侍奉长门雨露新，不知团扇委埃尘。","秋风燕入深宫里，惟有砧声不负人。"]},{"t":"送彭栋","f":"七言绝句","c":["故人相访到天涯，十载秦关梦尔家。","归去岭头逢驿使，相思早为寄梅花。"]},{"t":"同家兄公毅泊舟青萝山下忆故从兄元龙四首 其一","f":"七言绝句","c":["蓑笠冲寒晚系舟，知君泉下亦离忧。","不须浪泊他年路，已忆平生马少游。"]},{"t":"同家兄公毅泊舟青萝山下忆故从兄元龙四首 其二","f":"七言绝句","c":["冒寒曾上抱旗山，逸步飘然不可攀。","明日招魂向山上，江南摇落早知还。"]},{"t":"同家兄公毅泊舟青萝山下忆故从兄元龙四首 其三","f":"七言绝句","c":["忆君同泊海西津，夜半围炉酒百巡。","今夜扁舟惟有泪，满江风雪觅何人。"]},{"t":"同家兄公毅泊舟青萝山下忆故从兄元龙四首 其四","f":"七言绝句","c":["死别千年无见期，平生幽恨独君知。","萧萧松柏悲风起，犹记萝山恸哭时。"]},{"t":"秋夜","f":"七言绝句","c":["四壁萧然客计贫，药炉诗卷伴闲身。","秋来夜夜西园月，不似同游邺下人。"]},{"t":"瘗小侄幼初于先陇下归路感伤不已","f":"七言绝句","c":["一夜清霜凋玉兰，坟封三尺委茅菅。","鸣蛩断续精魂泣，回首荒山落月寒。"]},{"t":"宫怨和叶文学四首 其一","f":"七言绝句","c":["一别增城岁月移，房栊萧瑟朔风吹。","铜墀玉砌依然在，曾见君王旧履綦。"]},{"t":"宫怨和叶文学四首 其二","f":"七言绝句","c":["遥闻歌吹火辉煌，独抚流尘暗洞房。","宫禁重重魂梦远，枕边容易到昭阳。"]},{"t":"宫怨和叶文学四首 其三","f":"七言绝句","c":["金屋沉沉积雪光，卧听宫漏近南廊。","月华若向方诸照，应为长门滴数行。"]},{"t":"宫怨和叶文学四首 其四","f":"七言绝句","c":["独夜调琴荐玉杯，轻霜犹恐近瑶台。","楚妃魏女无劳妒，洛水巫山入梦来。"]},{"t":"天湖亭早梅","f":"七言绝句","c":["九月天湖湖水涯，霜侵铁干影横斜。","岭头想是春先到，已见西樵第一花。"]},{"t":"经铁泉精舍","f":"七言绝句","c":["精庐时有白云封，鹤怨猿啼思万重。","伯鸾一冢长邻近，山木萧萧传暝钟。"]},{"t":"白鹤花","f":"七言绝句","c":["瑶池前夜宴初开，风驭云軿自往回。","为问紫姑何处去，鹤群长绕此山来。"]},{"t":"观卢文卓所藏郭岩山人画菊","f":"七言绝句","c":["黄华寒倚石嶙峋，画幅萧閒见写真。","风雪独逢卢处士，江湖犹忆郭山人。"]},{"t":"月夜过关伯玉","f":"七言绝句","c":["月照江梅雪满枝，绕堤閒咏左思诗。","夜深乘兴那辞远，为是溪堂有戴逵。"]},{"t":"岁暮怀古","f":"七言绝句","c":["闾史无书乐府残，感时怀古泪汍澜。","出门一笑浮云散，惟有青山不厌看。"]},{"t":"春夜山房听雨怀潜父彦国士鹄仲登四子二首 其一","f":"七言绝句","c":["滴尽寒更睡不成，乍疑双瀑月中鸣。","可堪独剪西窗烛，闲却山房夜雨声。"]},{"t":"春夜山房听雨怀潜父彦国士鹄仲登四子二首 其二","f":"七言绝句","c":["听雨西堂夜寂寥，绿波芳草恨迢迢。","东风解送离人梦，曾过溪南第几桥。"]},{"t":"月下碧桃花盛开","f":"七言绝句","c":["玉貌承恩春最浓，楼头不怨五更风。","三千珠翠无颜色，谁似嫦娥戏月中。"]},{"t":"莫君谦夜过","f":"七言绝句","c":["三年梦远怅如何，江海逢君秋色多。","谁见幽人独醒去，依依残月照藤萝。"]},{"t":"夜访蔡子铎","f":"七言绝句","c":["访君灯下砌蛩啼，月满千山霜满溪。","从此相寻知不远，梦来应过浣花西。"]},{"t":"题关元诚所藏赵观四景画 其一","f":"七言绝句","c":["千峰茅屋夐无邻，津口花开始识春。","自是太平多隐逸，山人不是避秦人。"]},{"t":"题关元诚所藏赵观四景画 其二","f":"七言绝句","c":["绿树青山日未斜，镜湖一曲有荷花。","云霞隐映开元敕，行客遥知贺监家。"]},{"t":"题关元诚所藏赵观四景画 其三","f":"七言绝句","c":["秋江无客共衔杯，酤酒前村艇未回。","自信机心忘已久，开门无数白鸥来。"]},{"t":"题关元诚所藏赵观四景画 其四","f":"七言绝句","c":["蹇驴倦仆朔风寒，路远翻愁雪未乾。","此去寻梅因觅句，灞陵桥上几回看。"]},{"t":"同冯用唯陈士鹄夜集郑克一宅","f":"七言绝句","c":["郑庄留客有醇醪，沉醉尊前谢二豪。","后夜还山弄明月，白云相忆在鸣皋。"]},{"t":"题洞庭渔家图","f":"七言绝句","c":["岳州西望洞庭山，万里烟波羡汝闲。","湖上卖鱼仍买酒，钓船犹载夕阳还。"]},{"t":"黎惟仁山房别陈宗益还新溪","f":"七言绝句","c":["高楼送客夜悠悠，独立风烟咏四愁。","归去故园谁是伴，雪晴江上一孤舟。"]},{"t":"海珠江上留别孔元锡","f":"七言绝句","c":["扁舟江上待寒潮，归去孤村正寂寥。","却忆山钟谁共听，诃林寺里赤阑桥。"]},{"t":"题吴而谦野客堂","f":"七言绝句","c":["白首昂藏海鹤姿，翛然林下一茅茨。","北窗似是羲皇世，惟许柴桑旧令知。"]},{"t":"冬雨病滞城中送猷弟还家","f":"七言绝句","c":["脊令风急正分飞，极目西津浦树微。","旅病欲归归未得，孤城零雨自沾衣。"]},{"t":"画酴醾","f":"七言绝句","c":["涂黄妆翠出帘栊，玉脸娇来带酒红。","可是瑶池有嘉宴，夜深低舞月明中。"]},{"t":"木芙蓉花便面","f":"七言绝句","c":["解佩何来路渺茫，明河天上望空长。","江妃似怨秋风早，露下分明滴数行。"]},{"t":"七夕词","f":"七言绝句","c":["白榆丹桂影悠悠，银汉无波月正秋。","牛女桥边自来去，岂知人世有离愁。"]},{"t":"宫人望幸词四首 其一","f":"七言绝句","c":["玉貌临风几欲仙，掌中歌舞为谁怜。","自知不洒门前叶，只待羊车日似年。"]},{"t":"宫人望幸词四首 其二","f":"七言绝句","c":["暗数佳期欲渡河，罗衣休问夜如何。","汉宫恩泽如秋露，万岁枝头得最多。"]},{"t":"宫人望幸词四首 其三","f":"七言绝句","c":["同时豹尾数相随，自许当熊亦不辞。","红粉三千各秋色，独悬明月照蛾眉。"]},{"t":"宫人望幸词四首 其四","f":"七言绝句","c":["碧落空歌去莫攀，彩云不散候龙颜。","寄书为问西王母，更宴瑶池几日还。"]},{"t":"暮春过就芝亭玩秋海棠","f":"七言绝句","c":["沉香亭上酒醒迟，正是君王赐浴时。","知尔先秋畏摇落，十分春色在蛾眉。"]},{"t":"凝秀阁前对虞美人草","f":"七言绝句","c":["起舞尊前掩泪痕，芳魂何意傍兰荪。","楚歌月下无人听，露泣烟啼恋主恩。"]},{"t":"碧鉴江上与少承别后却寄","f":"七言绝句","c":["一片秋波万叠山，丹枫白草夕阳间。","征鸿只解将愁去，不见孤帆送客还。"]},{"t":"送邓山人游南岳","f":"七言绝句","c":["邓郁飘飖上岳庭，万松孤鹤五峰青。","欲餐云母轻身去，归受夫人大洞经。"]},{"t":"塞下曲七首 其一","f":"七言绝句","c":["雪满辽阳万里山，孤城木叶白云间。","至今鸭绿江头月，独照高骊使者还。"]},{"t":"塞下曲七首 其二","f":"七言绝句","c":["甲马居庸日日还，黄花一望白羊间。","何年绣斧曾三疏，百拜回銮独闭关。"]},{"t":"塞下曲七首 其三","f":"七言绝句","c":["军市云中日暮开，渔阳上谷几烽台。","娘娘滩上沙如月，一曲胡笳马上来。"]},{"t":"塞下曲七首 其四","f":"七言绝句","c":["二镇屯兵百万馀，花当消息近何如。","征鸿日暮江南去，多少闺人望寄书。"]},{"t":"塞下曲七首 其五","f":"七言绝句","c":["黄河套里尽膏田，胡虏深耕六十年。","莫上骆驼城上望，黄沙白草正连天。"]},{"t":"塞下曲七首 其六","f":"七言绝句","c":["燉煌更在酒泉西，哈密全封土鲁提。","汉将留屯三万里，玉门休用一丸泥。"]},{"t":"塞下曲七首 其七","f":"七言绝句","c":["花马池边大将营，边军只保朔方城。","吉囊莫向硝河渡，曾见泾阳六月兵。"]},{"t":"送龙彦襄往临淄","f":"七言绝句","c":["君骑匹马穆陵关，万里青齐积雪间。","到日登临陪玉舄，岱宗看尽万盘山。"]},{"t":"秋闺怨二首 其一","f":"七言绝句","c":["庭梧昨夜试新霜，坠叶成丹蝶已黄。","更堪羌笛城头起，一片关山在夕阳。"]},{"t":"秋闺怨二首 其二","f":"七言绝句","c":["书成月下捣砧催，河汉东西过雁哀。","寂寂洞房天似水，秋声何事入窗来。"]},{"t":"从军行六首 其一","f":"七言绝句","c":["驱车西出雁门关，关下征人不记还。","汉马时思呕夷水，胡儿愁见白登山。"]},{"t":"从军行六首 其二","f":"七言绝句","c":["朔方高阙接秦京，敕遣防秋列五营。","夜解马鞍屯马邑，朝持龙节出龙城。"]},{"t":"从军行六首 其三","f":"七言绝句","c":["云中烽火照甘泉，羽林十万驰燕代。","防胡但得飞将军，不用河南筑秦塞。"]},{"t":"从军行六首 其四","f":"七言绝句","c":["飞狐道上行人绝，倒马关前建旌节。","塞荒榆叶不作钱，山冻杨花尽成雪。"]},{"t":"从军行六首 其五","f":"七言绝句","c":["黄云黑水古边州，北风吹笳汉将愁。","夜深饮马长城窟，明日枭胡紫塞头。"]},{"t":"从军行六首 其六","f":"七言绝句","c":["雨雪关头射虎回，鹊血弓弰弯不开。","日暮闻箛齐上马，燕然西望李陵台。"]},{"t":"罗京兆携酒以歌者过吴氏池亭三首 其一","f":"七言绝句","c":["秋色如花掌上看，歌传秦□□□□。","曲终只恐还飞去，更筑高台驻紫鸾。"]},{"t":"罗京兆携酒以歌者过吴氏池亭三首 其二","f":"七言绝句","c":["三月清歌醉不还，使君犹自爱红颜。","风流颇似张公子，画得蛾眉似远山。"]},{"t":"罗京兆携酒以歌者过吴氏池亭三首 其三","f":"七言绝句","c":["新学歌喉试舞衣，馀音袅袅画梁飞。","池边好待陈王赋，且莫淩波洛水归。"]},{"t":"罗氏园作有序 其一","f":"七言绝句","c":["吏部文章自世家，独留何点在烟霞。","交深难向尊前别，沉醉山园十月花。"]},{"t":"罗氏园作有序 其二","f":"七言绝句","c":["君采翩翩子业前，尔兄华省并称贤。","持杯此地双钩色，回首浮云二十年。"]},{"t":"罗氏园作有序 其三","f":"七言绝句","c":["竹林嵇阮是吾徒，空有山阳旧日庐。","已分沉冥今更出，西风征马一踟蹰。"]},{"t":"罗氏园作有序 其四","f":"七言绝句","c":["兄弟通家里闬欢，故人犹作布衣看。","扁舟且载烟波兴，不为微名负钓竿。"]},{"t":"潘少承楼上读张妆集","f":"七言绝句","c":["弱冠诗名海内闻，潘郎连璧愿同君。","草书颇恨相逢晚，不见西窗白练裙。"]},{"t":"章中丞谪居南海枉书相问余值北上不获面承寄答二首 其一","f":"七言绝句","c":["椷书劳尔寄衡门，知在城西诃子园。","我自天涯频借问，几人迁客似虞翻。"]},{"t":"章中丞谪居南海枉书相问余值北上不获面承寄答二首 其二","f":"七言绝句","c":["薄谪何年出汉关，主恩宁不念行间。","长安献赋能相待，应见中丞斧钺还。"]},{"t":"海上","f":"七言绝句","c":["乱后风烟异昔年，孤帆一片海东悬。","鲁连不是扁舟客，何处长安落日边。"]},{"t":"初去故园","f":"五言古诗","c":["出身本田夫，家贫无负郭。","蚤从铅椠劳，尚乏霸王略。","躬耕岁频荒，转贩力犹薄。","饥来每驱人，谋禄心转怍。","谬为乡里推，遣诣太常学。","脂车已在门，逝将别林壑。","踌躇不能行，执辔前屡却。","上怀高堂欢，下顾同生乐。","虽歉三釜养，幸可事佣作。","愧谢栖遁贤，黾勉游京洛。","井臼付妻儿，且当厌藜霍。","夙昔邴生情，宁终恋人爵。"]},{"t":"望雪浪阁寄罗太史","f":"五言古诗","c":["进帆文江曲，江水清且涟。","水宿倦独往，岩栖久无缘。","倏经雪浪石，问讯飞霞前。","临清敞高阁，偃息群玉仙。","标以栖霞馆，带以种秫田。","簪笏谢金马，衿佩随青毡。","兹邦古安成，诗书闻诵弦。","人伦有师表，风教伊谁传。","余夙企明哲，未由觌高贤。","徒望县车里，曾览削竹编。","坚卧足镇俗，捷径难自全。","寄谢山中人，岁暮怀灵荃。"]},{"t":"送李伯承四首 其一","f":"五言古诗","c":["朝阳耀高树，光风泛崇兰。","三春岂不荣，雷雨将摧残。","之子好奇服，兰荃被缨冠。","芳馨讵自藏，剪伐良独难。","寸心葵藿前，中逵杂茅菅。","浮云为之阴，白日为之寒。","葳蕤上林苑，移植丘与樊。","岁华感我心，摇落增长叹。"]},{"t":"送李伯承四首 其二","f":"五言古诗","c":["结束事行役，京洛辞豪游。","朝发卢龙下，夕见黄河流。","飞泉洒濠梁，高澨望马丘。","淮阳岂云远，卧治亦已优。","宁厌承明庐，补郡非所求。","君恩旷浩荡，毋俾赤子忧。","禁闼虽可恋，疲瘵待尔瘳。","赐召行复来，肃穆瞻宸旒。"]},{"t":"送李伯承四首 其三","f":"五言古诗","c":["良会不可常，杂英满瑶席。","四座蔼冠簪，夫君独迁谪。","伊余承末交，绸缪暂昕夕。","未罄欢豫悰，遽惨关山色。","关山去何之，繁忧未能醳。","挥袂自此分，居人转悽恻。"]},{"t":"送李伯承四首 其四","f":"五言古诗","c":["临岐重踟蹰，四顾惊飙来。","偃蹇寄薄游，郁结何由开。","河梁一分手，鸣驺已相催。","落日照古堤，行子心悠哉。","北瞻金马门，东倚秋风台。","骖騑怀往路，太息仍徘徊。","绛灌本不怒，谁遣贾谊哀。","五陵纨绮间，焉知杨马才。","君其慎自爱，千秋重玫瑰。"]},{"t":"十四夜元白惟敬见过","f":"五言古诗","c":["暧暧天字豁，凉夜皎如练。","镜彩未盈规，清辉远弥见。","先临太液池，却丽昭阳殿。","须臾出渐高，历历指燕甸。","零露浥金茎，严更促银箭。","登楼枉嘉宾，鸣佩总时彦。","列坐引浊醪，行厨愧丰膳。","游豫靡沉酣，谈笑事笔砚。","盍簪既非偶，明德夙所眷。","共舒南渚情，宁羡西园宴。","抚景豫持满，称诗戒侧弁。","鄙劣谢久要，期尔回光眄。"]},{"t":"十五夜迟元白惟敬玩月","f":"五言古诗","c":["昨游有馀兴，今赏不可忘。","况当圆景丽，秋中气清凉。","池沼浩澄澄，城阙郁苍苍。","披衣坐前楹，瑶空已飞光。","凝华映连观，流辉明洞房。","周除觉冰净，达道弥天长。","步檐几延伫，呼童扫中堂。","石几拂琴瑟，邻家谋酒浆。","夫君幸伊迩，策马非异乡。","怀贤切饥渴，皎皎恒相望。","愿从聆徽音，示我于周行。"]},{"t":"十六夜述怀示元白惟敬","f":"五言古诗","c":["登高頫层城，远盻穷燕粤。","东窥沧渤流，西抚太行碣。","轮光出海隅，浮云敛天末。","徙倚眺京师，控带尽冀阙。","迅飙度陇阪，万里霜氛灭。","坞笛应鸿鸣，关柝随砧发。","幽燕多慷慨，赵魏负勇决。","李牧出雁门，汲黯入禁闼。","昔人构运会，题拂多引拔。","谬予困泥涂，栖迟独皤发。","且忻免负薪，敢复望结袜。","芳华宁久妍，精诚谁能察。","弦望信有常，亏盈不堪诘。","迢遥思美人，明珰似秋月。","劳悁咏四愁，并寄双鱼札。"]},{"t":"送姚元白","f":"五言古诗","c":["煌煌汉业盛，双阙何颉颃。","侯门半金貂，七贵黼绣裳。","北里富歌钟，南邻奏丝簧。","驱驰走马埒，游戏斗鸡坊。","君来入鼎门，弹冠厕朝行。","肃事禁庭间，抒藻翰墨场。","三年厌羁绁，请告还陪京。","陪京礼乐地，佩玉鸣锵锵。","衣簪荣旧秩，亲昵洽故乡。","朝趋典客署，夕卧中林堂。","执戟岂云疲，颂酒殊未央。","夙昔耻繁华，于今适徜徉。","扬雄虽寂寞，乐志在文章。","达士有高轨，去矣遥相望。"]},{"t":"送大司空蔡公考绩还留都","f":"五言古诗","c":["帝世穆清夷，皇泽播膏液。","二佐资牧鸿，九官让夔稷。","司空翼圣朝，献纳黼扆侧。","精义密言诠，掞文粲邦式。","深衷秉靖寅，补衮自恭职。","二京颇均劳，入奏虞庭绩。","勤事旋旧都，秉钧待崇陟。","予本澹荡人，谬厕章缝迹。","堂上察然明，车下怜齐戚。","洵美缁衣情，自愧乏明德。","方承倒屣欢，已奉脂车役。","商飙捲秋蓬，须臾易离隔。","何因奋南图，愿托扶摇翼。"]},{"t":"召试皇极门作","f":"五言古诗","c":["双阙中天起，宸居控华夷。","卿云薄前殿，下建五丈旗。","赐召入铜龙，延引牧豕儿。","冠簪左右列，侍从纷皋夔。","衢室下清问，爰采刍荛辞。","自顾雕虫技，岂有青云姿。","结发愿事主，委身及明时。","上书幸晚达，颖脱亦在兹。","负薪暂已释，交戟容逶迤。","衮职自无阙，绍绕将奚为。","且因四门辟，思以答周咨。","千载有良谟，毋遣曲学讥。"]},{"t":"秋夜二首 其一","f":"五言古诗","c":["秋风西北至，河汉横中天。","他乡况久居，游子私自怜。","蟪蛄鸣且凄，鸿雁何翩翩。","叹息夜中起，揽衣白云前。","故人一尺书，关山邈以绵。","宁当如参商，别离多盛年。","携手思行游，何时早归旋。"]},{"t":"秋夜二首 其二","f":"五言古诗","c":["飒飒丘中桂，凄凄阰上兰。","芳馨讵能久，北风天已寒。","萧艾非所宝，岂置珩璜间。","结佩远莫遗，徘徊望云端。","忆与君别时，明月缺又圆。","君心妾自知，妾期君不还。","严霜迫中闺，自理素与纨。","何因逐黄鹄，一至雁门关。","踟蹰盻双星，盈盈增长叹。"]},{"t":"冬日圣驾幸万岁山恭赋","f":"五言古诗","c":["会稽昔受计，涂山曾合符。","皇览遵时豫，宸游协前谟。","肆瞻万岁山，奠彼玄武区。","上冠青霞峤，下澄碧波湖。","绛氛久磅礴，苑中得方壶。","卜馆筑祈年，议礼齐鲁儒。","季冬朔云吉，乐岁欢以愉。","驾出即伊迩，警跸先传呼。","勾陈伏严卫，招摇备前驱。","旬始建曲旃，天狼奋威弧。","驭风六苍虬，望坛俨龙趋。","天童奉苍璧，玉女持金炉。","英韶合九奏，歌筑延以歈。","封泥瘗玉简，白云起须臾。","回盻秦汉辙，驰骋万里途。","何如格群神，行不役千夫。","霈泽答玄穹，望幸劳东都。","升中举盛典，永垂皇家图。"]},{"t":"答成仁卿","f":"五言古诗","c":["风林远冥鸿，冻泽沉修鲤。","洛阳三日雪，袁生未能起。","谁能除径来，忽觌楚成子。","褐衣翩翩行，声名在人耳。","江汉夙蕴灵，荆南富楩梓。","骚辞启屈平，丘索闻左史。","子也纂前绪，纫兰袭芳芷。","秋风吹洞庭，北征戒行李。","怜予濩落踪，顾笑长安市。","意气契远游，扶摇大鹏徙。","投赠英琼瑶，置之石上几。","嘉藻溢华光，深衷析玄旨。","得俊欢盍簪，并驱肃遐轨。","愿谢嚣壒缘，鸾骖自兹始。"]},{"t":"赠通政邹公","f":"五言古诗","c":["二华表秦京，殽函控天府。","黄河从西来，汨沸皋兰浒。","祥秀钟国宝，炳灵笃皇辅。","邹公冠惠文，枚卜授斋斧。","按章伏青蒲，请剑谁与伍。","日月方丽天，尧舜今圣主。","崇奖骨鲠臣，谠论播朝宁。","四岳咨纳言，帝曰予命女。","济济夔皋列，肃肃鹓鹭羽。","天球并雕戈，金镛协南吕。","忻逢阳道升，众羽各翔舞。","有渰出寸云，淰淰九州雨。","高木以鸣嘤，周原沃而膴。","吹万满太虚，春令待公举。","平格寿在天，侑歌酌吾醑。","深冯高庙灵，台阶即延伫。"]},{"t":"送吴明卿四首 其一","f":"五言古诗","c":["浮云耸双阙，阿阁扶中天。","洛京朝诸侯，冠盖纷其间。","之子赤麟符，握手惟古欢。","日暮出长乐，城南恣游盘。","命侣前进酒，朱瑟迎风弹。","千秋一绸缪，思驾双飞翰。"]},{"t":"送吴明卿四首 其二","f":"五言律诗","c":["嘉会不可常，绸缪为君结。","赐金岂不荣，而恋河梁别。","乐哉新相知，倏忽已燕粤。","万里风与波，罗帷有明月。"]},{"t":"送吴明卿四首 其三","f":"五言古诗","c":["明月更弦望，鸿雁知凉暄。","翩翩多北飞，胡为独南辕。","君自卧治之，宁薄武夷山。","翩其汉公卿，谁遣君弹冠。","辟门咨四岳，乘时当来还。"]},{"t":"送吴明卿四首 其四","f":"五言古诗","c":["行行奉明诏，还来待轩车。","夙昔恋禁闼，言返承明庐。","那知斗酒欢，不得长相于。","騕袅游中原，讵能顾驽驹。","结佩与我期，兰蕙秋何如。","佳人南以北，慰我尺素书。"]},{"t":"送吴约卿四首 其一","f":"五言古诗","c":["松柏附以萝，浮云恋清波。","万里远结交，三岁日已多。","何为双黄鹄，分飞山与河。","岂无盈觞酒，对之不能歌。","中心怆离居，徙倚将如何。"]},{"t":"送吴约卿四首 其二","f":"五言古诗","c":["河畔青青草，征马为君秣。","马亦顾其群，讵能与君别。","关山邈以长，咫尺难可越。","携手立斯须，燕婉已离阔。","风吹吴会云，何由到京阙。","汀洲采兰苕，及此芳未歇。"]},{"t":"送吴约卿四首 其三","f":"五言古诗","c":["美人好众芳，岁久香不息。","持以结交欢，时节倏已易。","幽兰有本性，终风竟何益。","白日照江皋，秋耿君应识。","夙昔奉周旋，谁能置其侧。","赠君遂与环，因之共朝夕。"]},{"t":"送吴约卿四首 其四","f":"五言古诗","c":["别离日已远，江流悲客心。","在近恩易洽，在远思弥深。","高足岂不策，赫奕人所钦。","于昔凛威棱，丰泽沛自今。","所贵崇令德，鼎足力可任。","鹍鹏志万里，焉能计飞沉。","扶摇以为期，矫翼青山岑。"]},{"t":"广武吟","f":"古风","c":["晨登广武山，萧萧古战场。","徘徊京洛间，日落盻荥阳。","秦鹿昔奔走，中原共翱翔。","项王气扛鼎，叱咤重瞳光。","江东提八千，独伯诸侯王。","沛中赤帝子，入关约三章。","烧栈定咸秦，蜀租给军粮。","成皋跳玉门，引兵食敖仓。","相与临广武，鸿沟竟分疆。","追击过固陵，雌雄颇低昂。","垓下楚歌声，骓逝虞亦亡。","汉业定关中，乃公留未央。","千年系马树，此地悲风长。","君不见沛公入关秦婴走，东井煌煌五星守。","蛇分云聚徵灵久，新城遮说兵缟首。","乌江不渡马童来，亚父何劳撞玉斗。"]},{"t":"梁园歌","f":"古风","c":["汝南太守来送别，劝予一访梁园雪。","今朝始渡黄河流，登台忽见梁园月。","魏王雄都大梁野，信陵公子曾停马。","屠肆空闻力士名，夷门不见抱关者。","孝王宫阙在睢阳，连属平台复道长。","兔苑山高成百室，旌旗警跸回三光。","檀栾修竹今非故，胜事空馀枚马赋。","猿岩雁池曾在无，鹤洲凫渚知何处。","莽苍荆棘古城隈，汴水东流去不回。","千年李白与杜甫，此地曾经醉酒杯。","荒烟落日一洒泪，悲歌抚剑空徘徊。","明兴古文谁第一，共推此地李献吉。","信阳何子曾并驱，苏门高生亦其匹。","一时酣咏梁王台，人称甫白与邹枚。","我来更在何李后，持觞三酹沾襟袖。","天球河图可终古，朱弦疏越竟一奏。","当年达宦总丘壤，尔辈大名同宇宙。","此物应难论簪组，斯文未坠怜雕镂。","梁园歌，歌正愁，明月平台似雪浮。","遥寄汝南徐子与，知予独啸梁园秋。"]},{"t":"望苏门山长吟","f":"七言古诗","c":["我行殷墟鄘卫间，访古一望苏门山。","濯缨思向百泉上，悲风落日流潺湲。","苏门先生久韬耀，土窟隐居睨嵩少。","嵇阮叩之嘿不言，下山回首闻鸾啸。","啸台隐隐白云层，本末披烟正可凭。","青史百年书巧宦，徒惭柳下愧孙登。","竹林七子沉酣处，空有山阳怀旧赋。","拂衣便可巢云松，芒鞋桐帽吾将去。","雪蓑道人期我游，弦琴读易苏门秋。","早向浮丘知相鹤，幸从庄叟悟牺牛。"]},{"t":"铜雀台歌","f":"七言古诗","c":["建安西驾轘辕道，二京旧迹忽如扫。","邺都踞虎当涂高，伤心千里青青草。","英雄盖世汉征西，叱咤山河落日低。","左开朱邸词臣宴，右指金戈壮士提。","中天铜雀何年筑，岧峣二台更相属。","讲武城连官渡口，滏阳水绕漳河曲。","雄图短日祇堪怜，断履残香满目前。","穗帷井干含啼处，空向西陵洒墓田。","蛾眉曼睩娱清夜，陆机已吊荒台下。","美人歌吹讵堪闻，赋诗横槊何为者。","登台可望荜圭宫，往事纷纷似梦中。","只见孤鸿向嵩洛，咸阳千树尽秋风。"]},{"t":"赋得蓬莱山送王舍人赴谪","f":"古风","c":["缥缈蓬莱山，乃在渤海东。","黄金以为阙，白玉以为宫。","仙人可望不可至，渤海冥濛天地中。","海风引船却复去，珍禽玉树纷何穷。","秦皇何处鞭石来，欲过东海观蓬莱。","徐市一往不复返，大药长生何有哉。","汉武亦祷万里沙，方士羽客列如麻。","泰山梁父竟封禅，矫首青天惟紫霞。","飞仙窟宅云在此，往来雾盖云旗里。","右挥若木左扶桑，波涛汹涌三万里。","豫章王生真岁星，绿发赭颜双眼青。","曾是玉皇香案吏，朝夕侍从趋彤庭。","九枝灯前王母宴，误持金醴倾银瓶。","玉皇一笑群真怒，竟麾羽翿乘云軿。","王生自昔有异骨，岂合燕雀同飘零。","谪居犹是蓬莱岛，九点齐州连杳冥。","玉皇恩深再稽首，岁许绛节朝宸扃。","笑翻东海挹北斗，拜祝玉皇千万龄。","斯时我或骑騄駬，翱翔云中瞻玉几。","相逢把袂问蓬莱，何当赠我金鹅蕊。"]},{"t":"防通州","f":"古风","c":["护仓粮，高筑墙，兵马急趋潞水傍。","东南刍粟积如山，百万军储指顾间。","庙堂胜算在兵食，一夕通州几报还。","忽忆先朝于尚书，计焚积聚将何如。","不见汉家飞挽速，宁如西据敖仓粟。","粮饷足，社稷福，万年周历今可卜。"]},{"t":"边兵来","f":"古风","c":["边书昨日至，人望江总制。","边书今日闻，人望马将军。","胡尘早暗沙头儿，墙子岭边胡马飞。","爷娘妇女急收保，大男挽驮孩牵衣。","襆被裹装束煤荻，顾引马骡鸡狗狶。","都门列卒呵行者，云拥催兵快骑归。","司马授钺司农饷，辇金县爵军中赏。","兜鍪李郭一时来，都人收泪手加颡。","劳苦边兵胆力粗，雨雪满甲冰满须。","半弯繁弱仍吹芦，誓取贤王扫休屠。","捷音入，天语呼。","大同乎，宣府乎。","火影已卜夷虏逋，日暮千里杀气孤。","帝将授之金仆姑，更为国家西击胡。"]},{"t":"侠客作","f":"古风","c":["君不见燕中高筑黄金台，乐生慷慨从西来。","挥戈谈笑聊凭轼，七十齐城何有哉。","君不见荆卿击筑饮燕市，悲歌变徵声，出祖临易水。","督亢图成樊首函，西入秦庭观玉几。","又不见夷门翁、屠肆儿，抱关鼓刀知是谁。","一朝窃符与公子，邯郸从此驱秦师。","古来侠者此数君，叱咤万里生风云。","借身报仇不足道，持危排难宁论勋。","思如雕鹗霜空肃，气似骅骝霜坂逐。","自堪鸣剑驰伊吾，谁解校书向天禄。","君不见东方先生待诏时，三冬文史无不窥，徒诵四十四万字。","宁似卫将军，救羊之尺箠。","仆也落魄长安市，颇识中原豪杰士。","只今匈奴犯边鄙，四郊多垒谁之耻。","便请横行沙漠里，岂令饮马雍奴水。","朔风夜吹紫驼耳，旄头不见三军喜。","登坛推毂更谁俟，酒酣耳热可以起。","左执干戈右弓矢，为缚天骄报天子。"]},{"t":"送吴约卿西巡因讯张广平助甫","f":"七言古诗","c":["金羁玉勒青骢马，绣衣直指称使者。","蓟云满地朔风高，一杯酌别都亭下。","忆我逢君意气真，燕台杨柳尚残春。","此日将军无揖客，此时丞相未留宾。","碣石旧宫成马厩，华阳高馆摧荆薪。","君能置我门下走，怜是风尘肮脏人。","昨者按节过三辅，每称广平张助甫。","鼎釜谁能廉洁如，文章更见风格古。","虽然惨澹违世情，独有芳馨在词圃。","翩翩雄视百代前，骅骝局促心空苦。","俯仰乾坤又一时，万方王道正清夷。","公卿喜上推贤疏，郡邑多传乐职诗。","君行再出赵魏间，揽辔应登马服山。","澶渊西望黎阳渡，瓠子东障金堤关。","长途魍魉知相避，负弩前驱或一攀。","怜才此去仍推毂，为我问讯憔悴颜。","冯唐归日逢停辇，肯荐云中魏尚还。"]},{"t":"雪夜曾缮部邀饮迟吴侍御黎秘书不至即席赋长句得孤字","f":"七言古诗","c":["狂夫作客游燕都，卜居亦在城南隅。","侯门怀刺不解趋，颇笑阮藉悲穷途。","故人为郎调绝殊，荆玉出璞今方须。","怜才稍惜南海珠，岂有照乘堪前驱。","深更遣迎走宛驹，从以貂帽双胡奴。","明月在裘雪在须，开筵兽炭红满炉。","宜城有酒不用酤，雕盘络绎出中厨。","高情卜夜且欢娱，黄金那问有与无。","城头吹角惊栖乌，酣歌更劝倾百壶。","竹林二客宁得俱，宾主能饮兴不孤。","青骢御史芸阁儒，何如高阳之酒徒。","他宵良会尚可图，开尊莫惜招狂夫。"]},{"t":"黎秘书席上赠李少虚之官赤岩","f":"古风","c":["长安腊月送行客，雪中命酒秘书宅。","客行路出八闽西，赠言岂有绕朝策。","前年岛奴犹未平，郡县纷纷皆甲兵。","岩前吹角边军集，城上鸣铙老将行。","岛奴今已悔祸久，闽中咸奏凯歌声。","客为南海李少虚，谢家之亲黎秘书。","请缨岂是抱关吏，佩印那辞乘传车。","风尘止可树勋伐，今人古人何不如。","吾闻桐乡朱邑本啬夫，阳夏黄霸曾游徼。","客行上马须早驱，慷慨岂道功名小。"]},{"t":"王母歌寿黎母太夫人","f":"楚辞体","c":["峨峨天上三珠宫，琳庭贝阙交玲珑，扶桑若木生西东。","朱光反射银汉侧，青雀翻飞明月中。","椷书咫尺报蓬莱，王母西从瑶水来。","戴胜之冠切云笄，珣玗双佩秋兰裁。","青娥三千不可以约略，后先婀娜纷趋陪。","烟軿电毂一时集，手翳琼枝胡至哉。","斯时琪花散空碧，绿幢卒葆忽生色，枣熟如瓜宴瑶席。","吸沆瀣兮食紫虹，左流霞兮右金液。","双成指顾三千娥，迭歌侑酌觞不息。","须臾又转绛节朝，天津两旗河鼓遥。","湘妃和神起阳瑟，秦女按节来吹箫。","鸾匏鹤笛合九奏，电裳舞袖回风飘。","南岳夫人笑相邀，麻姑赴会不待招，武夷曾孙歌且谣。","罗浮仙峰四百三十二，青玉为坛铁为桥，王母来往常逍遥。","飞云我忆蓬莱阁，儿时迎拜骖黄鹤。","玉箱欲纪王母年，金门且问东方朔。"]},{"t":"苏子川席上观舞歌","f":"古风","c":["燕京九月霜花落，蹇驴夜走城南陌。","请谒难窥许史门，邀欢独造苏卿宅。","苏卿薄禄有清酤，西台御史为上客。","玉觞引满炙肥羊，自称无以娱宾乐。","须臾红妆立帐前，激楚结风舞交错。","扇开衫影乱明霞，帕掩钗光薄金爵。","鬓云百转匝花钿，举袂飘裙忽欲仙。","钏边露腕双双玉，毯上行尘步步莲。","应节低鬟依促拍，逐行挥翟人繁弦。","行云送曲那能住，曼睇横波谁不怜。","金吾将军笑频顾，秘书先生目犹注。","胡髯山人侠者流，耳热酣呼亦豪举。","持觞将炙奈乐何，马跃鸡鸣不知曙。","巴渝迭舞白纻歌，主人寿客金叵罗。","西台痛饮仍大爵，苏卿膝席情更多。","卿也起家曹濮下，严亲尚书号横野。","秉钺云中节制遥，驱胡漠北威名大。","绛侯世业有亚夫，穰苴兵法传司马。","君不见东山饮酒赌墅人，苏卿尔岂沉酣者。"]},{"t":"赠薛子熙兼柬杜青州","f":"古风","c":["君不见陶公不能谒督邮，君不见李白愿识韩荆州。","嗟君结交二千石，古之杜毋今君侯。","君侯佩印牧青社，桑枣万家春满野。","羔币缤纷聘士人，中和宣布劳讴者。","闻君下榻郡斋时，多暇登楼日赋诗。","不署议曹参府事，但随上计朝京师。","燕山嵯峨雪三尺，燕市酒徒共朝夕。","君侯召对将有期，门下窃讥客无益。","君不见王生嗜酒一何能，渤海片言汉帝称。","卿寺今须贤太守，知君不愧水衡丞。"]},{"t":"送黄定父赴云中谒张中丞","f":"七言古诗","c":["汉家西北云中郡，大漠苍苍鸟飞尽。","代马风沙远斥边，秦人榆柳因成镇。","纥干迥隔雁门高，句注斜连稒阳近。","何年三筑受降城，单于射牧今谁问。","烽火曾照甘泉宫，幽并亦在胡尘中。","君王抚髀思颇牧，玺书夜册将军功。","山东才人近开府，帷幄运筹似其祖。","绝驱区脱静芦笳，尽日辕门寝鼙鼓。","黄郎任侠二十馀，手持一尺司马书。","西投开府献奇策，分庭愿作诸侯客。","燕郊去骑嘶春草，狐白之裘紫貂帽。","边风二月吹马倒，一川碎石飞如扫。","杨六寨前人迹稀，阴山何处飞狐道。","匕首腰间照雪光，檄成楯鼻不可当。","班生早勒燕然石，归来典秘兰台郎。"]},{"t":"石湖歌送韩员外请告还山","f":"古风","c":["大江五千里，草堂云气孤。","前揖茅君山，下瞰石臼湖。","湖上之居今几载，韩君少小曾击汰。","乃公谢郡持一竿，来往溪翁钓船在。","桃花吹满旧矶头，白鸥渺渺沧洲外。","君从献赋入明光，六载尚书水部郎。","长卿壁立能文赋，曼倩陆沉称酒狂。","昨者睥睨长安市，结交稍得天下士。","不能訾哫贵客前，独解酣呼众人里。","省署萧然退食时，梦飞半落石湖水。","上书请急觐乃公，锦帆三月过江东。","加餐鲈鳜烟涛上，高枕图书云雾中。","君去莫誇湖上乐，拂衣我亦寻幽约。","刺船便可系篱门，白浪高于瓦棺阁。","还家绿发意何如，只恐鸣驺促使车。","谁谈安石东山事，自有司空城旦书。"]},{"t":"松洲歌","f":"七言古诗","c":["主人家世执金吾，不数汉时马子都。","朝从卤簿甘泉驾，夕奉期门骑卫呼。","洲居岂是列戟处，松尘非供折腰具。","受爵幸免大夫封，论功欲倚将军树。","兴在青丘岩谷间，高堂倏见徂徕山。","扫花食实自堪老，耸壑昂霄谁可攀。","紫雾濛濛团盖滴，翠涛瑟瑟长空激。","龙干旁飘金阙门，虬枝低拂沧池石。","遥思海上凤麟洲，羽驾招摇玉树秋。","何时君挟偓佺去，我识金门万户侯。","问君冠剑奉朝请，何似天风洒吾顶。","好将忠荩答升平，人间亦有陶弘景。"]},{"t":"送稷山王簿兼寄谢山人","f":"七言古诗","c":["武安王生谢公侣，逢人每道四溟子。","经笥曾携隆虑山，褐衣傲睨长安市。","同时淮上有吴生，苕霅为丞色不喜。","王生作簿向稷山，大笑各行其志耳。","稷山远在汾河西，太岳中条与绛齐。","保障茧丝堪一试，凤鸾枳棘且安栖。","王生禄米薄升斗，醉后谢公诗满口。","车行上党近青天，先访谢公一携手。","何门今曳邹阳裾，当垆岂卖临邛酒。","高歌但拥如花人，刀环昨寄漳南否。","欧生海上欲归时，停云为道最相思。","绛帖紫参难远致，秋鸿须寄谢公诗。"]},{"t":"刘子脩归湖上居赠以长句","f":"七言古诗","c":["射阳湖上烟树多，浊水奔流江作波。","邗沟西北入淮去，一夜秋风渡漕河。","竹西歌吹何年路，广陵回首瓜洲渡。","胥泾不见浣沙人，参军只有芜城赋。","真州昔与谭生游，门下每称刘子脩。","曾揖长桑传肘后，还能满壁画沧洲。","前年击筑过燕市，昭王台边遇刘子。","挥毫命酒见平生，荐引无人解知己。","丹青传色出董源，晚于山水师荆关。","犹恨壮观未极意，跨蹇从我游西山。","风吹柳花满京阪，忽忆射陂春已晚。","公卿投辖不可留，买舟直向湖南返。","到家稚子候门庭，湖上芦黄枫树青。","行持西掖裁书笔，归注东皋让酒经。","我畏东华软红热，木门琅仓不堪谒。","长吟左氏招隐诗，寻尔持竿钓湖雪。"]},{"t":"春游曲","f":"七言古诗","c":["长安大道纵春游，燕草萋萋满御沟。","西山半似终南色，太液还如渭水头。","太液流澌已三月，西山绝巘犹残雪。","绿树遥连五凤楼，彤云深护双龙阙。","秦川公子玉骢嘶，半醉章台日未低。","挟弹呼鹰熊馆北，挥鞭飞鞚灞桥西。","芊绵紫陌华茵细，窈窕青楼弦管沸。","赏胜俱邀侠客来，骑回暂向倡家系。","倡家少女艳神仙，红杏齐开花满天。","郁金香袅芙容帐，琥珀杯行玳瑁筵。","千回送酒银瓶满，一曲当楼明月转。","莺笙鹤笛引宵长，绣簿锦屏障春暖。","歌翻子夜更悠悠，舞罢霓裳乐未休。","古调暂更新水令，新腔又过小梁州。","为君酒涴春衫袂，为君笑解罗襦带。","不惜侬家羞展眉，不怨个人太无赖。","春花春月冶游多，相携相引屡经过。","交疏影里频留盻，娇鸟窗前奈尔何。","五陵走马徒能侠，西津交佩谁怜妾。","燕岁莺年容易更，鸦黄蝶粉殷勤贴。","十千买笑意何如，百万缠头日不虚。","何事草玄甘寂寞，独怜杨子一床书。"]},{"t":"伏日同文寿承徐子与顾汝和饮袁鲁望斋中听讴者杨清歌时子与已补长芦矣因题此句","f":"七言古诗","c":["蒲萄绿酒黄金卮，吴趋越歈多妙词。","歌喉复见薛车子，曲谱似传杨叛儿。","绝代佳人不易得，楚妃堂上无颜色。","惯邀文顾两才人，颇骄天目山中客。","客去南皮沧海阴，浮瓜沉李共谁吟。","他时莫忆袁郎咏，妒杀尊前白雪音。"]},{"t":"送佘彦纶宰合肥","f":"楚辞体","c":["燕山驿路蝉声稀，蓟门关前桑叶飞。","故人得意鸣驺去，想见闾门迎锦衣。","庐江小吏来到门，双旌催驾叠鼓喧。","舒城馆里不遑食，亚父山旁将驻轩。","西望镇淮楼橹开，桐柏之水如丝来。","少年白晰宰京县，民得饭稻羹芋魁。","吠无犬兮驯有雉，忆尔行春过淝水。","诏书明日下扶风，蚤入长安见天子。"]},{"t":"华阳行赠王孝廉归晋陵","f":"古风","c":["华阳馆前秋雪飞，幽州道上行人稀。","当年筑馆人何在，今日拂衣君独归。","萧条策马辞京阙，关门一片西山月。","胡姬葡萄酒初泼，垆头把臂与君别。","君为荆川太史之门生，弟子都讲往往皆名卿。","独守师说奉大对，公孙侧目辕固行。","滹沱河水冻偏早，驿楼官树叶如扫。","上有燕台之衰草，下有荆卿之古道。","行行旅食不堪陈，渔钓江湖且煮莼。","子虚傥遇乡人荐，老作金闺侍从臣。"]},{"t":"将上京师答约侄问何日归隐","f":"五言律诗","c":["竹林方欲出，君已问归期。","肝胆灯前剑，勋名镜里丝。","燕台收骏日，汉畤获麟时。","傥奏淩云赋，沧洲去不疑。"]},{"t":"岭上谒张文献公祠","f":"五言律诗","c":["南人谁爰立，公始相开元。","忠岂酬金鉴，恩空下剑门。","衣冠通德里，桑梓曲江园。","父老修秦腊，还来奠桂尊。"]},{"t":"过南康寄蔡山人","f":"五言律诗","c":["蓉子何年国，桐君此日台。","隐无千亩竹，诗在一庭梅。","停楫思携手，题书问举杯。","邮程非兴尽，犹是雪中回。"]},{"t":"除夕寓九江官舍","f":"五言律诗","c":["饯岁浔阳馆，羁愁强笑欢。","烛销深夜酒，菜簇异乡盘。","泪每思亲堕，书频寄弟看。","家人计程远，应已梦长安。"]},{"t":"江州元日","f":"五言律诗","c":["北望国门近，那知隔楚天。","卿云书正月，瑞雪入新年。","愁向庾楼失，心先魏阙悬。","伫思元会盛，春宴禁庭前。"]},{"t":"游四祖道场","f":"五言律诗","c":["慈云自雁塔，香炉分鹫峰。","涧寒浮石钵，雪霁闻山钟。","欲难斋前偈，高寻霞外踪。","何人曾出世，禅境空长松。"]},{"t":"游五祖道场","f":"五言律诗","c":["冯茂道场古，千年大满名。","铭题鹦鹉塔，灯现钵罗城。","万众人天里，虚空仙佛情。","南宗今几代，曾此学无生。"]},{"t":"麻城雪中游龟峰山还过万寿寺圆容上人方丈","f":"五言律诗","c":["徒御偶然屏，闲来聊避喧。","雪深支遁院，松傍朗公门。","苦茗资檀越，疏钟掩给园。","蕲黄禅祖地，经律共谁翻。"]},{"t":"渡淮河次新息","f":"五言律诗","c":["初离弦子国，渐入息侯乡。","淮水分桐柏，鸿陂引玉梁。","人犹歌贾父，客每忆黄郎。","回首关东路，苍苍夕照长。"]},{"t":"晚憩普济寺趋郾城","f":"五言律诗","c":["挥鞭穷落日，上蔡更西平。","客问棠溪渡，僧还郾子城。","泉寒惟马饮，村暝少人行。","期向溵亭醉，长途莫计程。"]},{"t":"新郑北门读子产墓碑","f":"五言律诗","c":["忆昔干戈际，扶颠独有君。","礼能交晋楚，学已辨参汾。","莫以刑书铸，而忘策府勋。","城边溱洧水，呜咽几回闻。"]},{"t":"黎口镇趋宜沟","f":"五言律诗","c":["贪程宁计远，日日逐车尘。","河徙黎阳渡，城临白马津。","买刍供候骑，炊黍待行人。","貂帽惟残雪，空思五岭春。"]},{"t":"始至京师姚元白黎惟敬携酒夜过得春字","f":"五言律诗","c":["斗酒偏能载，新丰问旅人。","烟花三月暮，冠盖五陵春。","慷慨曾看剑，浮沉但饮醇。","他宵青琐直，何处望清尘。"]},{"t":"吴山人子充见过","f":"五言律诗","c":["十年思识面，把袂忽燕台。","蓟子何由至，辕生只漫来。","藏真君有道，奏赋我非才。","且贳胡姬酒，相将一醉回。"]},{"t":"同沈懋学王仪甫过吴子充留酌","f":"五言律诗","c":["日暮长安道，纷纷车马多。","高阳频觅酒，燕市且酣歌。","玄白宁劳问，风尘奈尔何。","穷交吴季子，犹得共烟萝。"]},{"t":"李符卿伯承左迁亳州夜同黎秘书惟敬吴侍御约卿往饯得长字","f":"五言律诗","c":["殷勤一尊酒，相送意何长。","薄宦投濠上，归心向濮阳。","使星珠斗外，卿月玉河傍。","持慰山东客，衔恩异夜郎。"]},{"t":"同许太仆元复文文学寿承吴山人子充黎秘书惟敬姚鸿胪元白杜舍人从殷集吴侍御约卿宅得禅字","f":"五言律诗","c":["朝回焚谏草，爱客且谈玄。","高士林疑竹，清斋室似禅。","襟期三径外，献纳五云边。","觅酒能无厌，应挥月俸钱。"]},{"t":"晓经西苑闻斋禁","f":"五言律诗","c":["肃穆展灵祈，千官御事时。","采诗供夜诵，持节侍春祠。","泰乙风云接，廿泉日月迟。","君王无秘祝，翔洽被恩私。"]},{"t":"送董文学之清河","f":"五言律诗","c":["泗水流不息，楚州行莫迟。","青毡聊讲德，彩笔更题诗。","草长淮阴市，江清漂母祠。","知君三策在，谁荐上彤墀。"]},{"t":"刘刑曹邀同李尚宝项录事黎秘书饮得观李何边徐顾孟诸公真迹","f":"五言律诗","c":["河东称甲族，京洛始逢君。","剑佩分青琐，琴尊向白云。","碑看先友记，箧出玉堂文。","世业翩翩起，王郎更不群。"]},{"t":"佛日独诣善果寺","f":"五言律诗","c":["清晓田衣去，花宫问梵僧。","鹤窥松下帙，瓢挂涧边藤。","请谒堪谁懒，沉冥愧我能。","鍊心曾十载，犹礼塔前灯。"]},{"t":"端阳日施缮部曾虞部邀游西山马上次韵","f":"五言律诗","c":["联镳从画省，命赏陟烟岑。","稍适林峦兴，因谐鱼鸟心。","开尊临水次，采药遍峰阴。","员峤前期路，翩翩何处寻。"]},{"t":"登望湖亭","f":"五言律诗","c":["宴坐一斋闲，西湖几席间。","岂期金马客，能到玉泉山。","解带同围竹，看云且放鹇。","烟波心更远，谁共棹歌还。"]},{"t":"碧云寺庭前芍药","f":"五言律诗","c":["红药花宫种，谁移供佛堂。","云深松院色，池净竹林香。","山鸟频窥影，天风忽送凉。","五台应不远，烦热此中忘。"]},{"t":"答黎秘书迁居见示","f":"五言律诗","c":["知汝避喧久，缁尘几卜居。","宫云飘曲磴，海月到前除。","僧问笼鹅帖，僮抄种树书。","未须辞禁直，即此足逃虚。"]},{"t":"伏日同许殿卿姚元白黎惟敬游郑氏园四首 其一","f":"五言律诗","c":["并马南溪路，何如杜曲边。","园因看竹入，裳每采荷搴。","池鹭频窥酒，潭鱼不避船。","酣歌还洗耳，箕颖兴悠然。"]},{"t":"伏日同许殿卿姚元白黎惟敬游郑氏园四首 其二","f":"五言律诗","c":["冥濛朝霭散，晴色满燕关。","策杖城南寺，看松雨后山。","蝉声流水外，人语白云间。","眷此幽栖地，犹能一醉还。"]},{"t":"伏日同许殿卿姚元白黎惟敬游郑氏园四首 其三","f":"五言律诗","c":["鸣珂寻郑谷，十里到池亭。","鱼鸟惊长啸，乾坤厌独醒。","烟消雍畤碧，云傍泰坛青。","欲作郊居赋，频来倒玉瓶。"]},{"t":"伏日同许殿卿姚元白黎惟敬游郑氏园四首 其四","f":"五言律诗","c":["尔辈俱词客，伊予本钓徒。","相将河朔饮，不问步兵厨。","宦岂黄金拙，歌应白雪孤。","君看三伏里，谁省在江湖。"]},{"t":"闻岭外苦旱岛夷再转潮州和惟敬","f":"五言律诗","c":["岭外今多难，偏伤旅客情。","疲兵当贼境，久旱罢农耕。","即恐军书至，深凭庙算成。","家人应掩泪，何事滞秦京。"]},{"t":"周太守叔愚寓善果寺夏日过讯","f":"五言律诗","c":["亦知除热恼，禅榻与僧分。","静院山禽下，疏钟夕梵闻。","黑貂今季子，皂盖旧冯君。","避世金门者，悲歌共尔群。"]},{"t":"读姚鸿胪禁中供事诸作辄赋一首","f":"五言律诗","c":["鸣佩侍臣随，炉烟傍玉熙。","预承瑶水宴，曾奉柏梁诗。","礼乐尊周朔，衣冠肃汉仪。","河东虽欲赋，徒有鬓成丝。"]},{"t":"吴约卿自邯郸回同惟敬过讯留酌因览张助甫诸诗","f":"五言律诗","c":["使者輶轩至，云从赵地回。","青天岳色断，白鸟秋风来。","行李唯诗卷，浮瓜共酒杯。","四愁何处寄，犹忆汉庭才。"]},{"t":"姚元白将还金陵同黎惟敬顾汝和汝所过访得秋字","f":"五言律诗","c":["恋别还今日，乡心不可留。","浦帆千里月，江雨六朝秋。","邀笛怀宵咏，鸣珂得昼游。","无言分手易，尊酒更绸缪。"]},{"t":"夏夜同吴侍御黎秘书集许舍人稚干馆得芳字","f":"五言律诗","c":["西京视草郎，结佩有琼芳。","下直开文苑，高阳得酒狂。","庭槐风转细，林竹露添凉。","爱此萧闲夜，那知玉漏长。"]},{"t":"同李给事避暑柏林寺遇雨饮白阁山僧房","f":"五言律诗","c":["清凉闻此地，结驷亦随缘。","偶共金门客，来参白阁禅。","萝云栖古殿，花雨接诸天。","阑暑深杯外，茅斋更洒然。"]},{"t":"答张员外鸿与楼居见怀","f":"五言律诗","c":["为郎恩不薄，久客梦江濆。","长铗愁中把，疏钟雨后闻。","经传秦博士，酒忆晋徵君。","自惜繁霜鬓，栖栖牧豕群。"]},{"t":"七夕约卿携酒惟敬同过得凉字","f":"五言律诗","c":["良宵不可度，佳客共清觞。","河倒星光动，楼空海气凉。","疏砧低汉月，哀角落胡霜。","谁听机丝苦，年年在七襄。"]},{"t":"秋日同惟敬道襄过天宁寺访真乘上人不遇","f":"五言律诗","c":["近臣方赐沐，暇日爱攀登。","共向前朝寺，因寻长梵僧。","一庵唯挂钵，何处独支藤。","客有许询辈，山门问几灯。"]},{"t":"璿上人园内菊","f":"五言律诗","c":["燕郊寒色净，秋在给孤园。","旃林三径冷，栗里数花存。","霜滑松枝几，池清竹叶尊。","远公浑爱客，山暝出柴门。"]},{"t":"秋日过戴伯常西园玩菊","f":"五言律诗","c":["闻君方把菊，步履远相寻。","谁道戴侯贵，萧然陶令心。","夕阴生曲径，秋色满平林。","从此篮舆惯，闲门五柳深。"]},{"t":"雨中同元白过惟敬借树轩","f":"五言律诗","c":["意惬过逢数，更阑笑语长。","乱蛩灯下静，深竹雨中凉。","客坐开山笥，乡心寄酒觞。","子云方寂寞，谁道校书郎。"]},{"t":"元白惟敬约卿见过同咏秋雨得尘字","f":"五言律诗","c":["爽气回千嶂，浮空晚更匀。","萧条青塞色，沾洒玉京尘。","井干飘黄叶，江潭涨白蘋。","洗兵还藉汝，应慰远游人。"]},{"t":"刘北部仲恭邀游商园二首 其一","f":"五言律诗","c":["蓟北窥形胜，登台尽日留。","关河三辅壮，冠盖五陵游。","清啸馀萧爽，沉酣任拍浮。","青门瓜地在，莫问邵平侯。"]},{"t":"刘北部仲恭邀游商园二首 其二","f":"五言律诗","c":["休沐频邀赏，羁栖足散愁。","平台冰井溢，曲水羽觞浮。","细酌仍调鹤，忘机偶狎鸥。","名园京洛外，回首汉陵秋。"]},{"t":"送马将军出塞","f":"五言律诗","c":["羽书飞万里，不分听胡笳。","独有黄须将，先驰白鼻騧。","鹿塞连烽堠，龙庭乱雪花。","封侯归日早，破镜莫思家。"]},{"t":"沈封君隐居巽洲其子祠部君索题","f":"五言律诗","c":["玉湖湖上水，种竹忽成洲。","君是沈麟士，功曹宁足留。","持竿风渚晚，吹笛卞山秋。","玄散何年赋，云虹应独游。"]},{"t":"谒文信国祠即柴市故迹","f":"五言律诗","c":["忆昔南冠日，厓山恨未忘。","魂沉柴市月，泪尽蓟门霜。","白雁衔江草，黄龙逐海航。","中原冠剑在，歌舞待巫阳。"]},{"t":"十月初度都下值防虏甚急感怀寄诸弟五首 其一","f":"五言律诗","c":["贱生常不乐，此日更萧骚。","汉苑惊烽燧，胡尘老鬓毛。","蒺藜兼雪下，刁斗入云高。","羁绁何为者，承欢愧尔曹。"]},{"t":"十月初度都下值防虏甚急感怀寄诸弟五首 其二","f":"五言律诗","c":["军书飞羽入，日落战云黄。","梦寐金戈外，关山铁骑傍。","千村荒汉月，六阵散胡霜。","候火回中近，南飞雁几行。"]},{"t":"十月初度都下值防虏甚急感怀寄诸弟五首 其三","f":"五言律诗","c":["生计由来薄，兵戈日转愁。","乡书经岁绝，客泪几时收。","星暗藏宫剑，霜凋季子裘。","老亲衣线在，辛苦事防秋。"]},{"t":"十月初度都下值防虏甚急感怀寄诸弟五首 其四","f":"五言律诗","c":["家舍何人守，松楸有梦攀。","思归金鼓里，恨别木樵间。","老至惟衰鬓，秋高益苦颜。","新阡猿断处，月冷道园山。"]},{"t":"十月初度都下值防虏甚急感怀寄诸弟五首 其五","f":"五言律诗","c":["驿断书难至，笳清露更寒。","田园兵后计，儿女梦中看。","帷幄筹方急，边庭虏欲残。","愁中持浊酒，听捷到长安。"]},{"t":"陈侍御道襄宅离夜遇雪得心字","f":"五言律诗","c":["去住还同醉，燕歌泪不禁。","怀乡游子赋，恋阙近臣心。","雪暗惊啼雁，天遥急乱砧。","凭君持使节，传语到家林。"]},{"t":"寒夜同惟敬怀杜舍人","f":"五言律诗","c":["传经今子夏，霄汉隔知音。","柏叶琼蕤散，梅花玉照深。","投壶谁一笑，绕槛共微吟。","讵道离居近，还驰径寸心。"]},{"t":"雪中同惟敬约卿集休承寓舍得君字","f":"五言律诗","c":["乘兴元非远，淩寒一访君。","万山驱白凤，千里暗黄云。","客计毡同冷，羁愁酒易醺。","蓟梅还共赋，抗手即离群。"]},{"t":"西苑十二首 其一 万岁山","f":"五言律诗","c":["五岳来朝日，三山路不迷。","长杨秦苑北，卢橘汉园西。","珠斗淩空近，瑶峰入望齐。","万年同圣寿，何用访丹梯。"]},{"t":"西苑十二首 其二 太液池","f":"五言律诗","c":["壶梁移此地，宫禁有沧洲。","浴鹤看成沼，疏龙汇作流。","波清珠树晚，风急石鲸秋。","不羡横汾赏，芙蓉隐御舟。"]},{"t":"西苑十二首 其三 紫光阁","f":"五言律诗","c":["仙仗那劳远，凭高禁籞间。","丹丘非弱水，紫气自函关。","芝纳诸山献，歌从八伯还。","卿云飞不散，长以奉龙颜。"]},{"t":"西苑十二首 其四 璚华岛","f":"五言律诗","c":["宸游几度过，容与棹郎歌。","沧海浮员峤，瑶池长碧荷。","月从云汉上，秋入露寒多。","青鸟西飞急，其如宴乐何。"]},{"t":"西苑十二首 其五 龙舟浦","f":"五言律诗","c":["箫鼓中流发，秋风散浦烟。","淋池新乐府，汾水旧楼船。","赏胜观涛日，游非习战年。","甘泉思扈从，回首濯龙川。"]},{"t":"西苑十二首 其六 承光殿","f":"五言律诗","c":["前朝唯此树，旧史不知名。","翠葆临圆殿，苍虬拂古城。","石封千岁字，风起半空声。","颇似逃秦客，悠悠见太平。"]},{"t":"西苑十二首 其七 丹冲台","f":"五言律诗","c":["窈窕丛霄上，回看佳气浮。","苑疑长乐接，台似集灵游。","云鹤迎清跸，山烟绕御楼。","王褒随所幸，新赋玉园秋。"]},{"t":"西苑十二首 其八 芭蕉园","f":"五言律诗","c":["谁道神山远，依然玄圃通。","琼瑶无隙地，苜蓿满离宫。","吹绿晴湖曲，飞霞小殿东。","史臣焚草后，蓂历万年同。"]},{"t":"西苑十二首 其九 南台","f":"五言律诗","c":["西内风烟异，南台见水田。","艰难曾稼穑，淳朴一山川。","农舍朝炊里，江乡夕照前。","谷蚕劳睿藻，豳雅定同传。"]},{"t":"西苑十二首 其十 兔园","f":"五言律诗","c":["西转兔园开，曾徵赋颂才。","赤麟随驭至，黄鹄下池来。","弦玉临风谢，留金罢露台。","明良真此日，拜手咏康哉。"]},{"t":"西苑十二首 其十一 乐成殿","f":"五言律诗","c":["弄田开汉苑，藉亩表周廛。","耒耜豳风后，膏腴灞水前。","千箱收夕照，几碓响秋泉。","父老康衢颂，惟知祝帝年。"]},{"t":"西苑十二首 其十二 平台","f":"五言律诗","c":["路直苑墙东，台因选将雄。","云屯丹组甲，月抱绿沉弓。","定虏凭骁骑，誇胡笑射熊。","君王非好武，频奏幕南功。"]},{"t":"同黎秘书刘山人游西山经玉泉山池亭望西湖","f":"五言律诗","c":["并马今朝路，西行访石经。","山泉浮钵绿，湖草映袍青。","积玉迷春涧，飞花入暮亭。","十年江上客，烟雨忆扬舲。"]},{"t":"功德寺","f":"五言律诗","c":["宣皇游豫日，此地翠华来。","忍草生驰道，慈云护讲台。","玉波仙鹭浴，绯雪御桃开。","望幸还今日，何人托乘陪。"]},{"t":"登香山寺来青轩","f":"五言律诗","c":["青冥香界外，寺远少人踪。","客至双停辔，僧来一叩钟。","梵声千涧水，雪色万山松。","何处期支许，闲扶石上筇。"]},{"t":"金山寺","f":"五言律诗","c":["泠泠钟磬音，金口惬幽寻。","溪绕芙蓉殿，山开薝卜林。","绳床逢鸟下，锡杖过苔深。","一听维摩偈，弥清尘外心。"]},{"t":"宿寿公禅房","f":"五言律诗","c":["王泉初解辔，松院揖方袍。","地远祇林静，天空禅月高。","楼真知道在，息影觉心劳。","且伴山僧宿，西湖听夜涛。"]},{"t":"寻华严洞","f":"五言律诗","c":["谁期宗炳至，石室访山僧。","桐帽飘云气，棕鞋受石棱。","莓苔前代字，瓶钵几传灯。","更看波罗长，追攀最上层。"]},{"t":"送曾子澄之塞上","f":"五言律诗","c":["曾是征南将，今随定远侯。","白云沉汉垒，春色过边州。","柳拂渔阳骑，笳清紫塞楼。","酬恩知有日，谈笑看吴钩。"]},{"t":"韩子成晚过","f":"五言律诗","c":["江左君成赋，中原念我来。","浮云驱碣石，华月散燕台。","调笑金门下，深知水部才。","新丰无斗酒，谁遣独醒回。"]},{"t":"送吴鸿胪幼贞省觐还毗陵","f":"五言律诗","c":["典客初通籍，宁亲遂尔私。","箧经韦相业，池草谢郎诗。","牛酒秋酺日，鲈羹晚钓时。","河东须早献，名已汉皇知。"]},{"t":"送华鸿胪存叔还无锡","f":"五言律诗","c":["蓟北承恩早，江南到日欢。","稻香三堰熟，茗细二泉寒。","临帖开山笥，移舟弄钓竿。","知君西笑后，还复向长安。"]},{"t":"署中王户部汝绪招饮","f":"五言律诗","c":["省署君多暇，华筵集友生。","清冰沉玉椀，赤日望金茎。","河朔千杯少，巴渝几曲成。","最怜消渴者，滞酒在秦京。"]},{"t":"燕京卧病书怀五首 其一","f":"五言律诗","c":["梦里潘舆远，三年侍奉违。","灵台深寄宿，上国久思归。","儿懒忧渔钓，家贫念蕨薇。","何因常负米，朝夕傍慈闱。"]},{"t":"燕京卧病书怀五首 其二","f":"五言律诗","c":["都养吾能给，长安旅食馀。","人怜贫仲叔，客笑病相如。","三谢雕胡饭，频窥贝叶书。","白头思牧豕，只合在田庐。"]},{"t":"燕京卧病书怀五首 其三","f":"五言律诗","c":["问讯沧江上，疮痍日可怜。","射潮喧弩士，下濑请戈船。","刍粟深忧里，冠缨醉影边。","飨军曾不乏，今借水衡钱。"]},{"t":"燕京卧病书怀五首 其四","f":"五言律诗","c":["辛苦防倭戍，千夫愤未消。","国威虽不损，师律恐成骄。","星垒连江雾，云旗蔽海潮。","东南堪一尉，深仗圣明朝。"]},{"t":"燕京卧病书怀五首 其五","f":"五言律诗","c":["伏枕惊还喜，天颜一笑开。","露桃方朔献，白鹿叔卿来。","灵圉多留馆，通天更筑台。","岂堪沧水使，容易奏蓬莱。"]},{"t":"伏日同惟敬鹫峰寺避暑","f":"五言律诗","c":["逢君校雠暇，同向寺中来。","丹鹫何年至，青莲此地开。","经声闻竹屿，棋局净池台。","茗粥深逃暑，萧萧散步回。"]},{"t":"晚同惟敬步至水塘庵","f":"五言律诗","c":["地远接人天，相寻解夏前。","松门初过雨，竹坞细疏泉。","簟冷山池气，茶香石铫烟。","莫嗔朝谒懒，犹得对僧禅。"]},{"t":"沈山人懋学邀同丁光禄吴孝廉避暑饮园中","f":"五言律诗","c":["好客如君少，招携更一尊。","桂同淮士赋，林即隐侯园。","图里疑山响，琴边听涧喧。","千秋河朔饮，谁解此清言。"]},{"t":"送张助甫之湖南四首 其一","f":"五言律诗","c":["开府荆湖上，清秋建节行。","胡林仍对月，羽扇亦谈兵。","水落黄陵庙，天遥白帝城。","召归应旦夕，登是厌承明。"]},{"t":"送张助甫之湖南四首 其二","f":"五言律诗","c":["喜得巴陵去，犹堪和郢歌。","秋兰被澧浦，木叶下沧波。","霄汉君恩远，江潭客梦多。","向来曾磬折，前席意如何。"]},{"t":"送张助甫之湖南四首 其三","f":"五言律诗","c":["几度传书至，难期把袂游。","中原驱上驷，南斗望孤舟。","缟带轻相赠，绨袍老自羞。","天涯见明月，空忆洞庭秋。"]},{"t":"送张助甫之湖南四首 其四","f":"五言律诗","c":["谈笑开尊处，词人共握兰。","江声云梦转，秋色岳阳寒。","侠气唯龙剑，时名岂荐冠。","治书铃阁日，须早寄长安。"]},{"t":"陆山人元德见过同黎秘书惟敬梁舍人思伯小酌得山字","f":"五言律诗","c":["桐帽烟霞客，相逢朝市间。","谁言碣石馆，不似洞庭山。","调岂浮沉异，心能去住閒。","因君招隐曲，桂树几回攀。"]},{"t":"李实夫太守将还泉南集别黎惟敬宅沈管二山人同赋得豪字","f":"五言律诗","c":["海内论词伯，宁能少尔曹。","竹留三径赋，酒值五陵豪。","绿发抽身早，青山阅世高。","乾坤交态在，回首愧绨袍。"]},{"t":"送顾汝脩归上海兼寄朱邦宪","f":"五言律诗","c":["易水悲歌地，如何与尔违。","天寒孤雁度，江远一船归。","餐菊逢醪美，羹莼问蟹肥。","朱云犹未出，遥忆薜萝衣。"]},{"t":"钟天章张伯邻二户曹载酒夜过","f":"五言律诗","c":["酒榼何因至，蓬门偶一开。","谁知居士室，犹有故人杯。","落魄看交态，分曹见吏才。","鹔鹴吾已典，萝月几回来。"]},{"t":"冯侍御共宿归义寺禅房","f":"五言律诗","c":["谁期趋府客，同有住山心。","涧鹿窥禅诵，林猿听苦吟。","清斋黄菊冷，孤磬白云深。","安石膺朝寄，幽盟未敢寻。"]},{"t":"答曾缮部省中见招","f":"五言律诗","c":["省署散群吏，知君绕径行。","听松心独远，把菊句还成。","簪组时人态，浮沉大隐情。","谁当虚左待，宾客老侯生。"]},{"t":"与黎秘书夜集曾缮部省中得花字","f":"五言律诗","c":["官舍绕霜花，邀欢兴未涯。","雁鸿秋万里，砧杵夜千家。","明月松杉直，高天河汉斜。","潘郎宁拙宦，词赋满京华。"]},{"t":"送潘时服省觐还吴兴","f":"五言律诗","c":["同待公车诏，秋风一骑还。","以吾思问寝，羡尔去承颜。","钓鲤太湖水，采芝天目山。","故人期握手，春色到燕关。"]},{"t":"送张山人碵夫游东岳","f":"五言律诗","c":["支瓢不惮远，东谒泰山君。","河带泠泠水，松栖片片云。","玉书窗下诵，金策月中闻。","归上诸儒议，千秋汉禅文。"]},{"t":"黎惟敬初度曾缮部有作即席索和","f":"五言律诗","c":["市隐扬云宅，风流贺监年。","清歌停座上，紫气落尊前。","词赋谁争长，婵娟却自怜。","金门沉陆久，那识是神仙。"]},{"t":"送何别驾见可之晋陵","f":"五言律诗","c":["佐郡推经术，名儒出汉庭。","严霜醒蓟酒，落月引吴舲。","稻熟荆溪馆，鲈肥笠泽亭。","延州歌颂在，谁共使君听。"]},{"t":"范员外见访偶出不得款待柬谢一首","f":"五言律诗","c":["子猷非兴尽，犹是雪中回。","终愧凿坏遁，难逢结驷来。","芸窗黄叶积，蒿径白云开。","更枉夷门顾，清尊得共陪。"]},{"t":"送陆元德还山二首 其一","f":"五言律诗","c":["洛下辞伧父，咸阳厌布衣。","遂成歌凤隐，不为忆鲈归。","名岂菰蒲掩，身才糠籺肥。","赁舂今且去，吾道未全非。"]},{"t":"送陆元德还山二首 其二","f":"五言律诗","c":["谁念客游者，归装无一金。","检书黄叶积，荷锸白云深。","亲膳供莼菜，官租指橘林。","因君寻角里，先寄五湖心。"]},{"t":"姚元白黎惟敬张羽王见过小酌得孤字","f":"五言律诗","c":["燕市浮沉日，将谁向酒垆。","自难期贵客，君肯问潜夫。","白眼千人废，黄金一醉无。","却看星斗上，剑气不曾孤。"]},{"t":"雪中访洪山人从周不遇","f":"五言律诗","c":["一径无车马，相寻且杖藜。","戴因招隐忆，袁岂避人栖。","仗虎炉空在，笼鹅帖懒题。","蹇驴何处去，应过灞桥西。"]},{"t":"岁晏旅中寄故园诸子十二首 其一 邝子乾","f":"五言律诗","c":["鹤氅高斋日，貂裘久客间。","饥寒驱我出，鱼菽羡君閒。","落羽栖燕渚，归心度汉关。","故乡兵甲后，那得帛书还。"]},{"t":"岁晏旅中寄故园诸子十二首 其二 郑克一","f":"五言律诗","c":["严遵常闭肆，匡鼎亦传经。","短褐谁曾问，哀歌只自听。","观棋多妙理，嗜酒且沉冥。","楚客宁知此，江潭赋独醒。"]},{"t":"岁晏旅中寄故园诸子十二首 其三 陈潜父","f":"五言律诗","c":["柴荆君独掩，怀抱向谁开。","日惨朱旗闪，云愁白雁来。","蒯缑多侠气，草屦老生涯。","二仲应相过，江乡望我回。"]},{"t":"岁晏旅中寄故园诸子十二首 其四 陈梦庚","f":"五言律诗","c":["故人无一字，目极为伤神。","虎观求方急，牛衣卧独贫。","罪言忧战伐，饥色杂风尘。","岂不怜同舍，飘零万里身。"]},{"t":"岁晏旅中寄故园诸子十二首 其五 梁公瑞","f":"五言律诗","c":["论交兄弟少，每忆长公诗。","书札能相慰，干戈未可期。","铜鞮君隐早，玉笈我归迟。","知有青箱在，行藏任鬓丝。"]},{"t":"岁晏旅中寄故园诸子十二首 其六 林维乔","f":"五言律诗","c":["与君期出世，那复待玄纁。","聊试漆园吏，将寻沧海君。","玉颜如可驻，金液早须分。","南北艰虞日，椷书报白云。"]},{"t":"岁晏旅中寄故园诸子十二首 其七 黎惟仁","f":"五言律诗","c":["寒霄频梦远，多在故人家。","箫咽云成綵，杯深月散华。","孤亭吟列岫，三径醉餐花。","忽复烟波外，书归汉使槎。"]},{"t":"岁晏旅中寄故园诸子十二首 其八 潘干周","f":"五言律诗","c":["扁舟相访处，浑似武陵溪。","岁月期看竹，风烟忆杖藜。","橘林双渡口，草阁万峰西。","斥堠年年远，重来路恐迷。"]},{"t":"岁晏旅中寄故园诸子十二首 其九 潘少承","f":"五言律诗","c":["昔年台尚好，共隐大科南。","犬护山厨火，猿听海客谈。","烟中捐蕙佩，云里锁松庵。","君自谙吾性，移文亦不惭。"]},{"t":"岁晏旅中寄故园诸子十二首 其十 梁少学","f":"五言律诗","c":["阮氏仲客贤，名家业已传。","峤南霜橘帖，海上牡丹篇。","远信劳鱼素，穷交念酒钱。","崇兰君莫寄，抽思向江天。"]},{"t":"岁晏旅中寄故园诸子十二首 其十一 罗曜文","f":"五言律诗","c":["故园多难日，消息尚纷纭。","朋旧空相忆，安危久未闻。","兵骄寻陕战，戍苦伏波军。","问讯沧洲上，渔樵亦可群。"]},{"t":"岁晏旅中寄故园诸子十二首 其十二 梁仲登","f":"五言律诗","c":["苦忆江楼别，北来音信疏。","曾投章甫去，几卜杜陵居。","岭峤仍烽火，朝廷问捷书。","不知溪上客，入幕策何如。"]},{"t":"雪中送别姚元白还金陵","f":"五言律诗","c":["寒城一以别，晓骑发卢沟。","燕代千山过，关河大传游。","鸡声惊叠鼓，雪片乱征裘。","去听江南笛，应思倦客愁。"]},{"t":"吴明卿自闽至寒夜同集吴约卿谒舍得明字","f":"五言律诗","c":["何期燕市酒，并得楚狂生。","词赋空时辈，歌呼岂世情。","幔亭云片落，碣石雪花明。","莫问垆头夜，沉酣有步兵。"]},{"t":"同吴员外过韩员外子成宅饮时子成以病在告","f":"五言律诗","c":["病爱枚乘笔，闲资季重谈。","颇从京洛下，一望石湖南。","月俸还官藉，山经与客参。","何因歌九辨，憔悴忆江潭。"]},{"t":"吴侍御席上赠门人张玉归武定省觐","f":"五言律诗","c":["两月传经去，宁亲借使骢。","席常虚待左，道岂敢云东。","射策张家子，能诗任氏童。","苍苍岱云里，何处听春鸿。"]},{"t":"岁尽独卧长安客舍怀文休承","f":"五言律诗","c":["公车同此夕，别去又经年。","格五无宣召，朱儒自俸钱。","孤灯残雪后，乱帙小窗前。","谁共文江客，屠苏一醉眠。"]},{"t":"同明卿惟敬过约卿宅得朝字时除前一夕","f":"五言律诗","c":["坐期官烛尽，且以永今宵。","纵酒惟吾辈，狂歌有圣朝。","胜传金缕蝶，颂倚玉盘椒。","城角风前断，空闻枥马骄。"]},{"t":"人日同张山人孙鸿胪徐文学集诚意伯刘公宅得盘字","f":"五言律诗","c":["西堂冠剑合，春酒一筵欢。","七叶蓂初长，千条柳尚寒。","河山连甲第，歌管荐辛盘。","华胜风前影，持觞几度看。"]},{"t":"同黎惟敬询韩子成病 其一","f":"五言律诗","c":["同是沉冥客，言寻消渴人。","避諠三署夕，归计五湖春。","玄晏成书早，维摩示病真。","相将江乘浦，烟艇共垂纶。"]},{"t":"同黎惟敬询韩子成病 其二","f":"五言律诗","c":["同谢鹓鸿侣，而私丘壑身。","赐衣沽酒尽，积俸买山贫。","梦蝶閒园吏，怀荃托楚臣。","因君上书早，偏忆岭南春。"]},{"t":"春日同社诸公集道院咏雪得庭字","f":"五言律诗","c":["岁献云含白，春回树失青。","鸾骖停玉笥，鹤氅肃金庭。","梅萼丛丛湿，松枝片片零。","何当笙磬发，同听蕊珠经。"]},{"t":"春夜大雪骑过明卿邸中","f":"五言律诗","c":["山阴吾兴剧，一骑偶冲寒。","栖凤银成阙，游龙玉作鞍。","云中妆树出，空里散花残。","为爱阳春曲，来同郢客看。"]},{"t":"十三夜同苏子川黎惟敬方德新吴明卿苏子冲成仁卿黄定甫集吴约卿观灯得开字","f":"五言律诗","c":["银缸生暖色，谁省在霜台。","月傍琼枝出，花攒火树开。","杯盘欢五夜，赋颂见群才。","隐隐闻歌笑，鸾舆太乙回。"]},{"t":"陆华父金元宾邀饮灵济宫赵道士馆","f":"五言律诗","c":["同作华阳客，过从惬素情。","市朝多大隐，喧寂共浮生。","坛石流云湿，山钟过雪清。","问君携手约，金液几时成。"]},{"t":"范方伯职方兄弟邀同吴太守庄黄二文学汪吴二山人夜集分得兵字","f":"五言律诗","c":["华筵逢二陆，春色凤皇城。","一雨沉花气，千门过雁声。","狂歌何处客，浊酒此时情。","竹径风流在，谁如阮步兵。"]},{"t":"酬厉都谏滦河见寄","f":"五言律诗","c":["憔悴投荒去，何年祀碧鸡。","谁怜青琐客，自老白云栖。","碣石春涛外，卢龙暮角西。","安危还寄托，健饭且扶藜。"]},{"t":"期陈明府子野晚过","f":"五言律诗","c":["君岂陈惊座，邀欢满汉都。","懒朝仍傲吏，纵饮亦吾徒。","夕苑千花暗，春沟片月孤。","糟床堪一斗，乘兴肯来无。"]},{"t":"题冯汝行海浮山居图","f":"五言律诗","c":["远识金银气，舟行望转微。","楼台疑蜃起，风雨挟鹏飞。","孤岛分齐鲁，千山入海沂。","图南吾欲去，渺渺泛潮归。"]},{"t":"曾缮部省中夜赏牡丹得狂字","f":"五言律诗","c":["官阁题诗夜，重陪水部郎。","花摇池槛影，酒洽竹林狂。","国色含烟紫，宫妆写额黄。","月中看不足，汉署更闻香。"]},{"t":"送冯明府谪教润州","f":"五言律诗","c":["讲肆延陶令，今非马队扃。","葛巾原漉酒，绛帐且传经。","高浪西津白，生烟北固青。","江南书札近，好寄鹤丘铭。"]},{"t":"送陈子野调令宁乡","f":"五言律诗","c":["古来才子地，天遣到长沙。","谁道三湘水，今看一县花。","橘洲收井税，竹浪见人家。","君自谈云梦，无令楚客誇。"]},{"t":"送丁子文赴浙省","f":"五言律诗","c":["名士曾书记，之官亦散曹。","登楼中夜月，作赋曲江涛。","荷叶迎仙棹，薇花洒客袍。","知君还北望，离思满烟皋。"]},{"t":"太保刘文安公彰恩卷 其一","f":"五言律诗","c":["功德四朝日，河汾千载馀。","曲台家乘礼，东观世藏书。","诵岂多三箧，名因出九胪。","殿前曾剑履，师傅几人如。"]},{"t":"太保刘文安公彰恩卷 其二","f":"五言律诗","c":["风雨中台坼，笳箫上党寒。","崇班瞻太保，旧学失甘盘。","瓜奠频繁遣，槐阴次第看。","凤毛今五色，得恐谢家难。"]},{"t":"午日集周都督子脩宅得诗字","f":"五言律诗","c":["缓带从容日，天中盛赋诗。","总戎周太尉，好客郑当时。","射柳无劳试，觞蒲且共持。","陆沉金马下，三见汉宫丝。"]},{"t":"病中承曾缮部见召不赴缮部以予将归曾有二诗意最勤厚因并酬答","f":"五言律诗","c":["倦游仍伏枕，归思更何如。","君已怜将别，吾方念介居。","家贫沧海钓，身老茂陵书。","知有盈觞酒，还来伴直庐。"]},{"t":"送刘伯良宰信宜","f":"五言律诗","c":["明卿春出牧，慷慨又刘生。","邸吏惊怀印，都人羡请缨。","云随铜柱尽，山过窦州平。","我欲移家去，鸣弦听诵声。"]},{"t":"送从弟淳伯南归二首 其一","f":"五言律诗","c":["三载惊相见，都亭把袂时。","游梁吾已倦，入洛尔何迟。","谁诵淩云赋，仍为失路悲。","天涯贫贱别，只少杜陵诗。"]},{"t":"送从弟淳伯南归二首 其二","f":"五言律诗","c":["同有怀萱梦，而先戏彩欢。","朝餐行荐笋，秋佩且纫兰。","山笥归时检，尘冠异日弹。","长安春柳色，还待玉骢看。"]},{"t":"夏日同潘时良出访徐子与因避暑张园 其一","f":"五言律诗","c":["休沐名园里，飞觞细雨前。","瓜期元不偶，萍迹况相怜。","避暑仍袁绍，登楼亦仲宣。","何须仙掌露，心赏已泠然。"]},{"t":"夏日同潘时良出访徐子与因避暑张园 其二","f":"五言律诗","c":["空庭回赤日，万竹驻高轩。","入座凉飙满，披襟玉露繁。","风尘俱傲吏，河朔一清尊。","即此看沉陆，无论金马门。"]},{"t":"同徐子与使君过袁鲁望进士留酌","f":"五言律诗","c":["燕市吾徒在，相携片语真。","饥寒驱薄宦，簪绂偶时人。","醉看青萍短，娇歌白纻新。","君看袁夏甫，落落傍风尘。"]},{"t":"同曾缮部宿省中得园字","f":"五言律诗","c":["邀欢成伴直，退食一清尊。","画省更明月，铜驼非故园。","竹阴凉露滴，楼影夜乌翻。","看尔郎官草，青绫怀主恩。"]},{"t":"方侍御德新宅伏日同诸公宴集得台字","f":"五言律诗","c":["青骢人正避，皂帽客犹来。","酒以金鱼换，谈容玉麈陪。","迎风开岳色，消暑倚霜台。","君已投车辖，那能不醉回。"]},{"t":"病中顾汝所招饮不赴闻是日子与先归鲁望吐酒有污茵之句因以戏之","f":"五言律诗","c":["消渴难乘兴，空斋独闭关。","最思光禄酒，一望太行山。","客劝袁丝饮，人歌山简还。","不知谁戏剧，噀雨到人间。"]},{"t":"伏日同徐子与顾汝和袁鲁望沈道桢顾汝所集文寿承斋中得家字","f":"五言律诗","c":["同心曾海岳，握手偶京华。","酒狎高阳侣，诗称博士家。","盘冰寒苜蓿，井碧泛甘瓜。","独有留欢处，空庭日易斜。"]},{"t":"送杨朝藩掌教安仁","f":"五言律诗","c":["洞庭南去路，文学得君良。","地以琳琅重，洲因橘櫾香。","听猿过楚岫，看雁到衡阳。","莫道王程远，由来近帝乡。"]},{"t":"送张彦旬掌教诸城","f":"五言律诗","c":["赐履千秋地，谭经五岭豪。","汉儒称世业，齐客亦吾曹。","马耳登台见，琅琊出浪高。","傥能游海上，为我访卢敖。"]},{"t":"立秋日同文寿承徐子与顾汝和沈道桢顾汝所朱子愚饮袁鲁望宅得凉字","f":"五言律诗","c":["秋催词客赋，晚醉酒人傍。","纨扇西风早，絺衣白露凉。","落梅惊玉笛，坠叶响银床。","惟有潘郎鬓，飘零感异乡。"]},{"t":"送王茂成归括苍 其一","f":"五言律诗","c":["骏足图难索，蛾眉画莫凭。","盐车曾涕泪，国色未须矜。","秋菊怀三径，燕歌别五陵。","大楼岩下月，谁得伴支藤。"]},{"t":"送王茂成归括苍 其二","f":"五言律诗","c":["今日中原客，秋风送汝还。","五噫辞汉主，一骑出秦关。","醉眼功名际，浮云去住间。","黄精归可斸，且看浙西山。"]},{"t":"七夕遇雨同徐使君袁进士刘沈二山人集潘大理宅时子与已有长芦之役","f":"五言律诗","c":["月卿重促宴，星使欲临河。","急雨下秋叶，平池生夕波。","风前双掌出，云里二灵过。","且莫捐兰佩，其如怅别何。"]},{"t":"曾缮部以三宅饯徐使君子与得情字","f":"五言律诗","c":["故人今夕酒，砧杵凤皇城。","碣石片云落，渔阳孤月明。","佩刀看侠气，击筑共平生。","别后南皮客，应知汉署情。"]},{"t":"观上虞谢进士读书山房图","f":"五言律诗","c":["东山君早出，人忆著书年。","竹牖飘晴叶，松门起夕烟。","经声秋瀑下，笔札白云边。","久系苍生望，深知谢傅贤。"]},{"t":"赠张仲实还山","f":"五言律诗","c":["曾闻飞遁日，石上卧江烟。","芝术君何弃，藤萝我最怜。","几时沧海钓，一问赤松年。","归去看云起，青苔诵古篇。"]},{"t":"初秋夜过曾以三缮部得尊字","f":"五言律诗","c":["凉色爱清尊，银鞍夜到门。","知予思露掌，为客扫风轩。","满目时人态，平生国士恩。","片心秋月下，微尔共谁论。"]},{"t":"暮秋过饮戴氏西园","f":"五言律诗","c":["羸马青门路，君家数往还。","亭留白云曲，城倚太行山。","残菊寒犹摘，霜梨醉可攀。","山阳灌园日，谁共吕安閒。"]},{"t":"送陈郑州敬甫兼寄张判官","f":"五言律诗","c":["词人多出牧，州郡岂徒劳。","汉主分符竹，王郎揖佩刀。","楼前中岳树，雪后大河涛。","知授梁园简，应邀谢法曹。"]},{"t":"送刘山人子脩归真州","f":"五言律诗","c":["三年蓟门客，分手秋风时。","旅食金同尽，生涯剑独知。","柴荆归更掩，猿鹤隐何疑。","我识江头路，寻君定有期。"]},{"t":"怀苏子冲","f":"五言律诗","c":["闻道辟疆园，蓬蒿积短垣。","诗篇传海岳，剑术老乾坤。","判袂燕台侧，题书濮水原。","相思日南北，吾亦别金门。"]},{"t":"寄苏子长","f":"五言律诗","c":["季子貂裘在，何年作隐沦。","金扉曾谢禄，瑶草足娱亲。","林似听莺日，山疑卧虎春。","悠悠濮台水，今见钓鱼人。"]},{"t":"寄苏子新","f":"五言律诗","c":["敬客知公子，通家托长兄。","早传梅石赋，不负竹林情。","开径期羊仲，淩云羡马卿。","思君若河水，何以到鄄城。"]},{"t":"雷比部携酒同古比部夜过得何字","f":"五言律诗","c":["寂寞无奇字，其如载酒何。","秋辞三署直，夜向五陵过。","玉笛吹花早，银床坠叶多。","他宵明月下，荒径忆鸣珂。"]},{"t":"子与将之瑞州予亦南行寄此为别","f":"五言律诗","c":["量移劳圣主，尺组不须论。","山雪思君曲，江枫去国恩。","孤村通栗里，三谷近麻源。","独有天涯客，扁舟夜听猿。"]},{"t":"酬张山人英甫","f":"五言律诗","c":["蓟北逢君日，名山忆永嘉。","綵毫新赋颂，铁研老生涯。","酒伴灵台月，心期雁荡霞。","谁堪关路别，惆怅五陵花。"]},{"t":"题张仲素玄玉斋","f":"五言律诗","c":["高斋弦诵日，鸣佩更珊珊。","江泻瑶池色，窗摇玉树寒。","何来沧水使，将献白云坛。","牛斗千山外，晴虹几度看。"]},{"t":"送董山人述夫归阳羡别业","f":"五言律诗","c":["远游因好道，能诵五千文。","帽湿双林雨，衣披十岳云。","江湖犹作客，猿鹤正思君。","归去张公洞，秋天长啸闻。"]},{"t":"九月十五夜月","f":"五言律诗","c":["瑶草三秋色，金风一夕寒。","书缘多难绝，月在异乡看。","凄断惊霜角，迟回望露盘。","刀头今未定，谁最忆长安。"]},{"t":"张户部伯邻宅同郭仪部方尚宝夜集","f":"五言律诗","c":["菊觞宁厌数，骑马屡过门。","结客多同舍，看花似故园。","月高燕市路，砧近汉宫垣。","不有中郎酒，谁堪秋思繁。"]},{"t":"晚过许维桢王绍传二内翰院署对酒言别","f":"五言律诗","c":["玉署能迎客，高天近九重。","白云随匹马，紫气护双龙。","洒袂西山雪，持觞北禁钟。","周南他日路，思尔扈登封。"]},{"t":"景州谒董子祠","f":"五言律诗","c":["广川晴雪后，驻马董生祠。","帷在知曾下，园荒似不窥。","疏林堕残叶，枯柳宿寒鸱。","老作江都客，传经愧我师。"]},{"t":"阙里观先师所植桧","f":"五言律诗","c":["尚见参天起，今思翠黛长。","岁华周日月，春色鲁宫墙。","柏岂存新甫，桐虚表峄阳。","独馀嘉树在，海岱接扶桑。"]},{"t":"谒颜庙","f":"五言律诗","c":["睎颜曾想像，入室见琴书。","洙泗为邻并，箪瓢恒晏如。","山庭仍陋巷，井里半荒墟。","目送浮云过，因知乐有馀。"]},{"t":"谒孟庙","f":"五言律诗","c":["世岂居邹日，三迁有故宫。","龟蒙曾蔽鲁，凫峄只荒东。","客礼兼金外，家祠五鼎中。","玄圭同禹力，谁颂决河功。"]},{"t":"枫香驿楼夜雪","f":"五言律诗","c":["白马枫香下，青春粉荔前。","雪凝千涧水，风荡万家烟。","卯酒官亭路，辛盘旅食年。","故人传尺素，为枉济江篇。"]},{"t":"立春日匡庐山中","f":"五言律诗","c":["两见青丝菜，五年今复游。","客从庐岳下，僧候虎溪头。","春转双林色，冰开众壑流。","天池飞梦到，宁待拂衣秋。"]},{"t":"经濂溪先生故居","f":"五言律诗","c":["斯人不可作，绝学已千年。","湓浦庭皆草，匡庐岳是莲。","霜凋前代树，月霁一林烟。","犹有图书在，风琴自洒然。"]},{"t":"同介上人寻广福观遇刘道士","f":"五言律诗","c":["高赏云霞侣，欣然巾我车。","法师不嗜酒，道士本能书。","炉耸紫烟际，经残丹笈馀。","虎溪还一笑，忘却在匡庐。"]},{"t":"青居馆读江州故守朱子价碑","f":"五言律诗","c":["谢公文可读，山馆不荒芜。","星堕炉峰顶，珠沉甓社湖。","虎符丹旐远，龟碣白云孤。","千载匡君传，能留姓字无。"]},{"t":"圆通寺","f":"五言律诗","c":["山有古祇林，开堂石耳阴。","岳云当涧落，径树向门深。","雪磴僧支策，风泉客掩琴。","西亭茶灶在，即此长禅心。"]},{"t":"元夕玉峡过吉水与黎比部饮舟中","f":"五言律诗","c":["雪浪开千里，仙槎偶共乘。","江亭深夜酒，水市满船灯。","笛里听金缕，帆前望玉绳。","明年花月夕，还约醉兰陵。"]},{"t":"安远驿下送别叶男兆宰福清","f":"五言律诗","c":["天边叶县令，何日别皇畿。","驿树迎官舫，江云映彩衣。","辱楼沧海近，雁字晋安稀。","期尔陪仙仗，双凫正北飞。"]},{"t":"清远道中答胡佥宪","f":"五言古诗","c":["结束事行役，风霜易白头。","望乡同海雁，浪迹似沙鸥。","岐路频搔首，江山一倚楼。","欲裁王粲赋，幸托李膺舟。","北上初辞粤，西归已梦周。","本非游说客，空愧黑貂裘。"]},{"t":"谒少司寇梅国刘公祠","f":"五言古诗","c":["丁年予度岭，公已蚤归休。","旅馆回光盻，林园表宴游。","每闻诸士论，实许五臣流。","富国卑为晏，精忠更是刘。","深衷劳奏疏，雅量镇沉浮。","献纳趋宸扆，班司近冕旒。","不鸣羞仗马，遂去伴江鸥。","田宅贫萧相，朝廷老沈侯。","蒲轮将下日，梁木已先秋。","伏腊村翁走，碑铭太史留。","何人哀北海，有客哭西州。","寂寞祠前路，空瞻庾岭头。"]},{"t":"过汤阴谒岳忠武庙","f":"五言古诗","c":["遥指汤阴路，西寻鄂国居。","行云犹惨淡，征马尽踌躇。","逆虏兵曾炽，中原愤未除。","旄头南落日，鼓角北征馀。","谋国奸先蠹，和戎策已疏。","黄龙期痛饮，丹诏促归与。","草染苌弘血，霜飞乐毅书。","皇天不可问，烈士竟何如。","力尽朱仙镇，魂随二帝车。","山河留壮气，不敢泣欷歔。"]},{"t":"秋夕约卿元白惟敬同集小斋闻新雁得年字","f":"五言古诗","c":["秋风万里至，一雁过长天。","嘹唳胡笳里，凄凉塞笛前。","庭空飘落叶，家远梦江船。","声急零霜夕，书迟度岭年。","罗浮归未得，沧海到应先。","楚客谁同听，西楼片月悬。"]},{"t":"春夜同惟敬约卿集寿承学舍时休承将之吉水在坐同赋得寒字","f":"五言古诗","c":["庭阶仍系马，献岁聚长安。","甲子新周朔，申公老汉冠。","共推经术最，其奈鬓丝残。","学馆荣三绝，儒林合二难。","兴来题棐几，酒至出辛盘。","墨竹烟光动，鱼灯海色寒。","粤人千里思，楚客几回看。","凤掖怜分袂，螺洲忆采兰。","雪消梅粉路，月满杏花坛。","他日江湖上，方知此夕欢。"]},{"t":"春雪后同杨徐沈舒四子集诸太史宅","f":"五言古诗","c":["西山残雪在，返照万家明。","汉署宾初集，梁园赋欲成。","门摇金马色，树走玉龙声。","暗溜还凝水，疏帘尚积霙。","花轻含冷萼，草细折冰茎。","寒枥仍留骑，深更不算觥。","璚楼惊曙雁，银阙听新莺。","纪瑞词臣颂，祈灵圣主情。","白云停绝唱，黄竹念苍生。","紬史书年异，看君继二京。"]},{"t":"送吕参军幼开出守寻甸","f":"五言古诗","c":["儒林推父子，世德重箕裘。","家出关西学，才参幕下筹。","符分铜虎去，使得碧鸡游。","行矣驰滇国，先应梦益州。","僰僮迎汉吏，泸帅识姜侯。","万里题诗日，千山羽猎秋。","青蛉通北望，黑水入西流。","赐召君来速，归期看拥驺。"]},{"t":"送秦侍御赴浙江佥宪","f":"五言古诗","c":["早岁成辞赋，君王诵子虚。","自簪前殿笔，岂是茂陵居。","使以观风出，名因抗疏馀。","外台仍衣豸，南国便羹鱼。","道路秦人策，江湖越绝书。","行歌听榜枻，问士过桐庐。","海色长鲸截，霜威落雁疏。","衔恩归有日，把袂意何如。"]},{"t":"孙鸿胪席上咏樱桃得绡字","f":"五言古诗","c":["珍果来何处，炎风万里遥。","莺含分露颗，雀啄落星条。","映席霞飞槛，开笼绛满绡。","瑛盘行寝庙，玉食及臣僚。","近侍初休沐，新题偶见邀。","青冥沾赐日，同荷圣明朝、"]},{"t":"秋日同周象贤沈道桢游白云观","f":"五言古诗","c":["燕九人能往，斯游我自偏。","长廊频落叶，匹马独闻蝉。","鸡犬驱何日，烟霞似昔年。","泉凝丹井月，门锁白云天。","法磬鸣霜后，经函散石边。","宁劳东海上，即此候神仙。"]},{"t":"送王太史元驭奉使册封赵藩","f":"五言古诗","c":["东观词臣出，西藩旧邸开。","占星随玉节，赋雪上铜台。","庭揖诸侯客，园游七子才。","虎盐门下献，牛酒里中来。","赵璧无劳赠，吴涛更有裁。","圣明思侍从，莫遣隔年回。"]},{"t":"出京师留别张郎中鸿与梁助教彦国十二韵","f":"五言古诗","c":["朔风吹万里，曾共忆江乡。","雁引归心早，砧惊客梦长。","忽随公府牒，频举故人觞。","夙昔诸生后，周旋二子傍。","四门推助教，三署表中郎。","韦杜衣冠并，邹枚侍从良。","出关怜马首，执戟羡鹓行。","雪后宫云白，天边苑树苍。","眇予怀魏阙，看尔在岩廊。","晨佩趋长乐，宵钟听未央。","梅花庾岭色，柏叶禁庭香。","莫以相如赋，从容奏汉皇。"]},{"t":"发华节亭过灵洲至三水与钧谟猷三弟别","f":"七言律诗","c":["片帆已过郁洲台，风急惊沙落雁哀。","万里独怜难判袂，三江犹得共衔杯。","西陵涛起思康乐，南国书归念大雷。","弟妹分岐贫更苦，客轺今去几时回。"]},{"t":"过韶州宿芙蓉驿","f":"七言律诗","c":["峡过浈阳尽始兴，旧游名胜记吾曾。","霜天雁字孤城月，水驿滩声一夜灯。","泷口刺船愁问吏，曹溪飞锡欲寻僧。","夷犹更进芙蓉棹，韶石峰头望舜陵。"]},{"t":"同胡佥宪登云封寺观音阁玩梅花","f":"七言律诗","c":["岭开孤阁倚巑岏，携手高临百八盘。","山畔幽香移般若，天边残雪落旃檀。","春催远客兼程早，驿报长安一骑寒。","十载江南谁把玩，北枝今日正宜看。"]},{"t":"淦口望胡佥宪舟不至先赴金川驿相待","f":"七言律诗","c":["江树寒深独鸟依，邮亭回首叹蓬飞。","湓峰雁去冲残雪，渝水帆来带落晖。","日短山城收市早，风高溪寺听钟微。","瑶琴玉涧今何处，水远天长客未归。"]},{"t":"雪后渡淦水至萧水寄潘少承","f":"七言律诗","c":["风前淦口叹飘零，雪后潇滩更杳冥。","问驿尚知黄蘖馆，渡江还向渌波亭。","异乡只见山云白，故国应多海树青。","此际想君开阁望，计程时一展图经。"]},{"t":"雨中趋陆过瑞州","f":"七言律诗","c":["朔风驱马听晨鸡，路入筠州晚色迷。","小洞雪封梅树外，飞霞寒挂竹林西。","自怜残腊犹奔走，长忆他乡尚鼓鼙。","问讯谢公歌舞处，万峰零雨一猿啼。"]},{"t":"大雪宿建昌早行过德安","f":"七言律诗","c":["白云千里上巑岏，石耳香炉雪未乾。","身到昆丘群玉府，梦游天女散花坛。","闭关岂合长高卧，跨马偏宜半醉看。","渐过楚乡仍北望，瑶台琼阙是长安。"]},{"t":"雪夜同胡伯贤宿东林寺","f":"七言律诗","c":["山僧留客解征鞍，虎笑溪桥鹤绕坛。","两寺疏钟云壑暝，万峰积雪石门寒。","夜深窗竹惊频折，腊尽溪梅落未残。","却望屏风飞瀑下，何时还共醉中看。"]},{"t":"晓过西林寺","f":"七言律诗","c":["峰头雪霁日初升，扶策西林问上乘。","高阁残经千劫火，空山孤塔几传灯。","青莲旧迹谁为主，白鹿曾游不记僧。","笑忆柴桑犹强出，十年心寄白云层。"]},{"t":"初春三日浔阳渡江过黄梅","f":"七言律诗","c":["匹马来看云锦屏，东风湓浦又扬舲。","九江涛涌帆前白，五老峰横雪后青。","鸿雁春归书未至，鱼龙天阔酒初醒。","苍茫已向匡君别，瀑布香炉绕驿亭。"]},{"t":"人日由蕲水过黄州长堤四十里马上晴望","f":"七言律诗","c":["蕲春城在楚云间，策马冲寒问五关。","积雪消时浠水树，乱峰明处汝州山。","石头古渡孤舟急，樊口疏钟一鸟还。","记取天涯过人日，莫愁双鬓易成班。"]},{"t":"寻东坡雪堂遂过赤壁矶下","f":"七言律诗","c":["钱唐为守最风流，谁遣临皋咏四愁。","两赋云霞留赤壁，五年烟月醉黄州。","沙湖已决求田计，樊口曾来把钓游。","莫向雪堂歌九辩，江山萧瑟白云秋。"]},{"t":"黄州遇袁履善比部时量移郡丞","f":"七言律诗","c":["天涯把袂问何之，海内才名识汝迟。","此地更留苏氏赋，何人不诵谢公诗。","豫章一榻将悬日，洛下扁舟欲去时。","圣主似闻前席待，蓟门烟柳忆归期。"]},{"t":"白杲镇冒雪趋麻城寄袁履善","f":"七言律诗","c":["万树官梅照酒杯，为谁千里雪中来。","貂裘零乱飞花坠，马足淩兢踣铁开。","草埠河将成玉渚，木陵山已作瑶台。","却忆郡斋袁夏甫，青绫深拥散衙回。"]},{"t":"过官渡河入光山","f":"七言律诗","c":["候晓津亭驿骑多，中原道路此经过。","镇淮楼影临官渡，浮弋山光带寨河。","白氎尚存京洛俗，青翰空忆越人歌。","北风吹雪千馀里，零乱貂裘奈尔何。"]},{"t":"过汝南访徐子与使君","f":"七言律诗","c":["望气寻君汝邓来，乘春冰雪马前开。","周璆谬忝斋中客，徐干今推邺下才。","坐啸试临桐柏水，倚歌还上景夷台。","长安西去谁知己，乞取金龟醉几回。"]},{"t":"徐子与春日表台宴集得春字","f":"七言律诗","c":["客来十日饮河滨，淮蔡城边气色新。","把袂未消千里雪，开尊先散万家春。","嵩山杳霭连王屋，洛水萦回带孟津。","百尺高台君试望，中原鞭弭更何人。"]},{"t":"谒大复先生祠堂","f":"七言律诗","c":["贤隐山前宿草烟，祠堂今筑表台边。","伏生不待传经岁，贾谊空伤作赋年。","客望函关仍紫气，书藏嵩岳并青天。","从游载酒嗟予晚，门下何人受太玄。"]},{"t":"登汝南城楼","f":"七言律诗","c":["将军白马旧临关，楼橹中原战守闲。","汝曲自成悬瓠水，淮南遥见朗陵山。","雁鸿早向春风过，鹅鸭偏惊夜雪还。","陈蔡北来今重镇，戍笳声在乱云间。"]},{"t":"郑州客舍怀故园诸子","f":"七言律诗","c":["候馆萧条一骑过，黑貂风雪意如何。","长堤日落行人少，远树天寒宿鸟多。","仆射陂前京北路，武疆城畔楚西歌。","春来纵有停云句，双鲤那因到汴河。"]},{"t":"郑州登楼望中岳","f":"七言律诗","c":["名岳岧峣接上台，毓祥今有中兴才。","云扶二室天边出，日映三花雪后开。","周典尚馀巡狩迹，汉家新筑集灵台。","太平不复论封禅，时听嵩呼万岁来。"]},{"t":"渡黄河","f":"七言律诗","c":["津头小吏候旌干，河激高歌举棹欢。","天转浮云酸枣决，涛翻斜日具茨寒。","万行归雁风前过，一片征帆树里看。","沉璧宣房非汉代，君王无事诏千官。"]},{"t":"河上送七郡太守入洛","f":"七言律诗","c":["关东犹切九重忧，已报诸侯会洛州。","梁狱竟劳田叔按，楚筵宁见穆生留。","嵩邙远近生寒色，瀍涧东西急暝流。","何日山河还带砺，词臣空忆兔园游。"]},{"t":"寻空同先生河上草堂","f":"七言律诗","c":["西来孤骑过中原，却忆词人旧有园。","岳色至今干紫极，河声犹似下龙门。","雪驱梁苑千年赋，云惨浔阳万古冤。","荒径只今书带满，独留玄草在乾坤。"]},{"t":"汴梁怀古","f":"七言律诗","c":["缥缈宫城十二楼，玉津无复昔年游。","烟深废苑常疑雨，柳折残堤半似秋。","遗老尚能谈楚汉，平台谁更召枚邹。","輶轩一望中原路，长送黄河过汴州。"]},{"t":"过邺下访谢山人茂秦","f":"七言律诗","c":["中原七子似君稀，独向西河老布衣。","四海风云鸿鹄远，五陵烟月薜萝归。","竹林青荫乌皮几，铜雀高临白板扉。","自笑缁尘京洛去，新诗偏忆谢玄晖。"]},{"t":"丛台","f":"七言律诗","c":["磁州北走邯郸道，一上高台万里思。","马服山从低树见，葛鹅城为浊河移。","啼乌岂是娇歌日，衰草全非袨服时。","六国不知蚕食易，西来游客最堪疑。"]},{"t":"登龙兴寺天宁阁同胡佥宪伯贤阅观音像","f":"七言律诗","c":["佛阁淩空百尺浮，六鳌曾此负神丘。","金身天竺来何日，石塔波罗到几秋。","恒岳烟消通大漠，滹沱风急涌寒流。","凭高岂但超尘劫，咫尺彤云是帝州。"]},{"t":"初至燕京宿报国寺英上人房","f":"七言律诗","c":["长途日暮叩僧扉，疑入名山坐翠微。","高阁佛灯留客枕，中天禅月照征衣。","不堪夜梦仍南去，已听春鸿尽北飞。","回首缁尘心独远，欲从初地得皈依。"]},{"t":"登毗卢阁","f":"七言律诗","c":["东方初日照觚棱，振舄冯高眼倍明。","四塞河山环大内，诸天楼观俯沧瀛。","花台似涌云中出，仙袂疑从岳顶行。","綵槛雕阑闲倚遍，九霄长送凤凰声。"]},{"t":"寓黎秘书馆王全人见过","f":"七言律诗","c":["献赋长安春暮来，故人今典汉兰台。","紫貂贳酒君能过，玉笥藏书客自开。","金马沉冥犹薄禄，青云冠盖几怜才。","竹林正是邀欢地，车骑良宵得共陪。"]},{"t":"吴侍御约卿宅同黎秘书惟敬杜舍人从殷得臣字","f":"七言律诗","c":["日下衣冠散紫宸，郑庄虚席正邀宾。","鹔鹴燕市频沽酒，鸿雁胡天半过春。","自笑负薪随计吏，偶从视草识词臣。","尊前意气惟须醉，世路风尘白发新。"]},{"t":"和顾汝和玉河堤上见白燕","f":"七言律诗","c":["海上遥思玳瑁梁，御沟东畔几回翔。","瑶台乍过疑无影，珠树曾栖半带霜。","风里差池飞玉舄，月中妆束舞霓裳。","谁云京洛缁尘化，犹自衔恩绕建章。"]},{"t":"送陈侍御道襄巡畿甸及齐鲁诸郡","f":"七言律诗","c":["虎节翩翩獬豸冠，前驱负弩渡桑乾。","花飘燕甸春风早，雨过齐州岱色寒。","东海煮盐纾国计，北庭飞粟募材官。","芝泥玉检登封地，羡尔云边策马看。"]},{"t":"送陈进士彦吾使密云兼还南海省觐","f":"七言律诗","c":["前驱负弩驿亭间，建节东行暂出关。","霄汉乍辞丹凤阙，风烟先卷白檀山。","主恩远许封轺去，家庆深欢綵服还。","莫恋故园春草色，汉庭郎吏待鹓班。"]},{"t":"梁彦国滦州书至","f":"七言律诗","c":["疲马饥衔苜蓿嘶，怜予千里望辽西。","风驱朔雪卢龙近，云暗春城碣石低。","帐下谭经留客坐，斋中把酒听莺啼。","雄文最似相如赋，侍从河东待尔题。"]},{"t":"送岑允穆司理池州","f":"七言律诗","c":["春深杨柳暗燕关，南去襜帷不可攀。","雪浪城头江祖石，芙蓉天外李家山。","讼堂吏散莺堪听，药院僧来鹤共闲。","秋浦看花能忆否，封书须及早鸿还。"]},{"t":"首夏沈鸿胪宅同吴侍书黎秘书顾舍人赏牡丹","f":"七言律诗","c":["玉鞭遥向五陵家，沁水园中日未斜。","万片綵云飘翠幕，一阑红锦照晴霞。","席茵最忆江南草，尊酒频看蓟北花。","欢赏幸陪供奉客，绝胜歌管七香车。"]},{"t":"送王武库定甫使金陵因还南昌展省","f":"七言律诗","c":["供帐都门赠柳条，仙郎衔命下丹霄。","浮云万里辞燕甸，明月孤亭拥汉轺。","碧草渐迷扬子渡，青溪还问谢公桥。","过家莫羡南昌尉，鸣玉含香满圣朝。"]},{"t":"同钱水部吴职方施缮部曾虞部登西山绝顶","f":"七言律诗","c":["绝嶂西来翠柏残，片霞时堕汉臣冠。","青天大岳云边出，落日中原马上看。","玉气重关开碣石，飞泉千折下桑乾。","欲将凫舄翩翩去，花落天坛露正寒。"]},{"t":"晓出玉泉山经西湖","f":"七言律诗","c":["玉泉散作镜湖波，闻道宸游向此过。","宫阙三山浮弱水，楼船千里度星河。","白麟朱雁无消息，瑶草金芝近若何。","词客昔年誇扈从，琳池花似汉时多。"]},{"t":"省中芍药和惟敬","f":"七言律诗","c":["苑中红药艳阳催，禁直仙郎宴赏回。","官锦乍披青玉案，露华深注紫霞杯。","清芬结佩佳人赠，迟日当阶上客裁。","词赋王褒今待诏，銮舆临幸几时来。"]},{"t":"雨夜郑驾部携酒同过黎司封宅时司封已擢广西参藩","f":"七言律诗","c":["佩刀解赠意踌躇，把袂燕歌泪满裾。","客路风烟频汉诏，主恩天地有潘舆。","蓟门夜色千家雨，桂海秋涛九月书。","乡里衣冠吾独后，淩云空自老相如。"]},{"t":"雨中过周园访沈山人与姜膳部对酒作","f":"七言律诗","c":["虎林词客宿称豪，下马何人问浊醪。","醉里山连秦苑树，赋成风起曲江涛。","雨深绿草胡尘断，云散金茎汉阙高。","岂有雄文今待诏，桓谭犹道在春曹。"]},{"t":"送司封黎郎中惟和出参广西政","f":"七言律诗","c":["凤城芳草散鸣珂，横笛谁堪马上歌。","荆楚晓烟飞越巂，湘漓秋色入牂牁。","省郎剑佩云霄远，词客江潭岳牧多。","玉节明年应趣召，咸阳西上莫蹉跎。"]},{"t":"酬王舍人仪甫潞河见寄","f":"七言律诗","c":["骊驹几日出燕关，咫尺青云不可攀。","便访安期沧海上，谁容方朔汉庭间。","故人书札愁中寄，逐客风烟梦里还。","秋色王程应渐远，知君西望太行山。"]},{"t":"约卿宅同元白惟敬咏盆荷得前字","f":"七言律诗","c":["华顶曾窥玉井前，燕阳还赋九花莲。","秋风细洒池边石，暑气全消雨后天。","鱼戏绿波经十里，龟游清露已千年。","因思溪上芙蓉馆，谁更菱歌上钓船。"]},{"t":"夜饮诸太史端甫宅","f":"七言律诗","c":["周南初返直庐年，朝退能开野客筵。","宫锦夜披明月下，禁钟秋到凤楼前。","玉绳低映长安树，仙掌高擎白露天。","方朔自惭还索米，汉庭空有故人怜。"]},{"t":"同元白惟敬过约卿所出鲥鱼侑酌感赋","f":"七言律诗","c":["赐鲜今见出青冥，旅食京华鬓已星。","珠履尚弹孤客铗，金盘宁羡五侯鲭。","天遥渔艇三江水，秋入鲈乡万里亭。","何处沧洲无钓侣，清时犹自恋宸扃。"]},{"t":"新秋同文寿承沈懋学文休承许殿卿姚元白黎惟敬集吴约卿高斋得飞字","f":"七言律诗","c":["初闻征雁送斜晖，凉夜高斋此会稀。","沧海月从危堞过，太行云入小窗飞。","狂来每忆莲池咏，醉后还寻竹径归。","万里秋风长作客，尊前空愧薜萝衣。"]},{"t":"送许右史殿卿之河南","f":"七言律诗","c":["曳裾闻尔相东平，诏许亲藩借老成。","梁苑词臣齐客在，济南经术汉家名。","驱车落日河流远，策杖秋风岳顶行。","莫叹壮游今已倦，主恩还遣入西京。"]},{"t":"万寿节早朝皇极门","f":"七言律诗","c":["清秋阊阖曙光分，逢掖追趋谒圣君。","南极一星珠斗近，嵩呼三祝绛霄闻。","九傧赞后班群瑞，八伯歌成下五云。","白雉赤麟誇盛事，兰台还奏汉都文。"]},{"t":"朝退出右掖望西苑","f":"七言律诗","c":["紫宸分仗散千官，谁奉西清曲宴欢。","瑶水风云随玉辇，蓬莱宫殿接金銮。","九霄幡影玄坛閟，五夜钟声碧落寒。","却忆甘泉秋色里，侍臣多在月中看。"]},{"t":"卢方伯少明入京中秋见邀玩月","f":"七言律诗","c":["使车南去少能留，此地还期月下游。","万里星环燕阙夕，九关榆落蓟门秋。","已闻卿相频推毂，自笑风尘老敝裘。","宾从他宵还对酒，不知谁共庾公楼。"]},{"t":"十六夜小斋待月元白约卿同赋","f":"七言律诗","c":["东来车骑访幽栖，共待清光手重携。","九市烟尘人境外，万家砧杵帝城西。","黄山远见宫槐直，紫阁平临海树低。","何事天涯问圆缺，故园应待尺书题。"]},{"t":"十七夜同何太仆卢方伯袁节推集黎秘书宅","f":"七言律诗","c":["赐金几日出西京，秘省留欢此夕情。","渐望使星天畔去，尚悬卿月禁边明。","腾骧独识秦关骑，战伐曾谈涨海兵。","只尺君恩如召问，上书何以答升平。"]},{"t":"九日同黎秘书李黄门吴冯二侍御登宣武门楼","f":"七言律诗","c":["百二山河控上游，郁葱佳气满皇州。","风驱大漠浮云色，天转滹沱落日流。","双阙金茎连紫极，万家红树动高秋。","佩萸氿菊俱恩泽，不是荆南独倚楼。"]},{"t":"送何太仆入贺还平凉","f":"七言律诗","c":["长安何处望萧关，醉里燕歌一解颜。","辑瑞北来趋魏阙，封轺西去过秦山。","城连上郡羌胡远，马饱中原战伐闲。","乘障莫嗟边吏苦，玺书行召护军还。"]},{"t":"癸亥明堂大祀礼成纪事","f":"七言律诗","c":["甘泉高擢汉明庭，更筑崇台礼万灵。","宗祀偶同书癸亥，中兴谁复数殷丁。","芝生九叶铜池碧，日抱重光玉树青。","前殿公卿频上寿，万年何用禅云亭。"]},{"t":"送姚匡叔之魏郡兼寄谢茂秦","f":"七言律诗","c":["萧萧一骑渡洺河，知有心期在薜萝。","漳滏波声黄叶下，邢襄秋色白云过。","股肱三辅分庭少，笔札诸生任侠多。","后夜西园应见月，谢家新赋更如何。"]},{"t":"过沙河行","f":"七言律诗","c":["离宫千里苑城开，扈从当年尽汉才。","凤扆尚留清禁肃，龙游曾奉属车来。","日高复道晨驱出，星散周庐夜徼回。","宣曲长杨俱望幸，彩云深护建章台。"]},{"t":"谒长陵","f":"七言律诗","c":["居庸叠嶂俯桑乾，终古长陵王气盘。","凉雨石城千堞雪，秋风金阙万松寒。","鼎湖弓剑胡天远，原庙衣冠汉月残。","三驾犁庭思帝力，北门封守在长安。"]},{"t":"阳翠岭","f":"七言律诗","c":["丛霄积翠筑金墉，仙仗曾过第一峰。","海日夜摇三殿玉，园霜秋落七陵钟。","石当御路皆成鹿，松起中天半是龙。","圣主合符临万国，侍臣谁更颂东封。"]},{"t":"送李尚宝册封肃府","f":"七言律诗","c":["曾使琉球海上行，又驰关陇别承明。","兰山星散千秋垒，榆谷天连万里城。","负弩绛驺迎玉节，直庐青琐忆金茎。","汉家茅土雄边镇，从此河湟不用兵。"]},{"t":"送沈给事册封周府","f":"七言律诗","c":["礼重亲藩命汉官，手持金册出长安。","睢阳旧苑鸣驺入，洛涘名园载酒欢。","积雪歌声犹缥缈，夹池竹色尚檀栾。","相如亦有游梁兴，何日平台醉后看。"]},{"t":"送陈侍御道襄出按闽中","f":"七言律诗","c":["天书朝捧禁城西，骢马翩翩向晚嘶。","三策锁闱周礼乐，六条行部越山溪。","频年戈甲穿篁竹，此日渔樵罢鼓鼙。","绝徼早宣明主意，勋名麟阁待君题。"]},{"t":"答施虞部曾缮部同直省中见怀","f":"七言律诗","c":["对直寒宵向省闱，仙郎词赋有光辉。","高悬霜月联曹近，闲锁冰厅见吏稀。","梦隔关城砧杵急，心随江汉雁鸿飞。","草玄寂寞无人问，自笑长安一布衣。"]},{"t":"送黄参军赴闽幕","f":"七言律诗","c":["君行气激五都豪，闽越频年尚属櫜。","簪袅军劳秦爵贵，奉常家学汉庭高。","图中按垒窥鱼腹，幕下持觞论豹韬。","别去从军诗早寄，故人还赠吕虔刀。"]},{"t":"病中曾缮部携酒同黎秘书夜过得长字","f":"七言律诗","c":["并马移尊问草堂，茂陵秋色正苍苍。","城头笛起关山月，槛外砧飞汉苑霜。","多病更堪羁思苦，清欢其奈鬓丝长。","芸台水部能来往，倦客浑忘在异乡。"]},{"t":"次夕黎秘书携酒曾缮部同过得霄字","f":"七言律诗","c":["故人尊酒慰萧条，并控骅骝意气骄。","郢里高歌回白雪，燕台寒色满青霄。","城边明月鸿声起，灯下清霜木叶飘。","此夕谢庄惭作赋，词臣多在圣明朝。"]},{"t":"病起曾缮部夜过","f":"七言律诗","c":["倦疾柴门夜不扃，三年萧寺只沉冥。","瀑窗药试疑瞳碧，山笥书成愧汗青。","明月颇思玄度咏，浊醪能问子云亭。","他宵松落空坛静，谁共幽人石上听。"]},{"t":"施虞部敦甫寄诗问予卧病次韵奉答","f":"七言律诗","c":["萧斋偃卧即山林，门掩藜床岁月深。","市里玉壶聊混俗，省中词客限同心。","拥衾洛下书生咏，击节幽州马客吟。","赖有故人相慰藉，不须重问橐中金。"]},{"t":"十月虏警书事三首 其一","f":"七言律诗","c":["朔气初飞万树霜，惊传胡马过渔阳。","从军岂乏三河少，度漠曾招六郡良。","鸣镝月寒窥雁塞，射雕云暗散龙荒。","皇威赤羽劳诸将，不似周王拥白狼。"]},{"t":"十月虏警书事三首 其二","f":"七言律诗","c":["甘泉烽火到长安，阙下衣冠立马看。","北转储胥刍粟富，西来骠骑雪霜寒。","观兵帐外期超距，拜将庭中议筑坛。","细柳已屯江总制，月明羌笛满桑乾。"]},{"t":"十月虏警书事三首 其三","f":"七言律诗","c":["关塞秋阴暗白登，飞狐道上羽书仍。","云屯汉卒徵三辅，风急胡笳过七陵。","暂向太原称薄伐，已知吉甫佐中兴。","书生亦有燕然颂，待勒恒山第几层。"]},{"t":"答张民部饷军左安门寒夜见寄","f":"七言律诗","c":["飞刍忽上白云边，知尔登楼啸远天。","半夜军声胡垒月，万家寒色蓟门烟。","檄成楯鼻提兵日，箭落旄头破虏年。","投笔欲随骠骑去，汉庭勋业在祁连。"]},{"t":"次韵酬曾缮部以三斋居省中见怀","f":"七言律诗","c":["燕台风起暮萧骚，念我偏题尺牍劳。","阔略幸无三府辟，激昂终愧五陵豪。","公车岁月囊钱尽，郎署云霄剑佩高。","停辇若逢明主问，莫言宾客有绨袍。"]},{"t":"和梁彦国虏退后行经三河诸村落慨然见寄","f":"七言律诗","c":["战后秋阴蓟柳疏，怜君驻马为踌躇。","烽沉万垒荒烟外，鬼哭千村野烧馀。","霜草有狐啼废井，夕阳无鸟入残墟。","防胡李牧须频遣，莫更边庭走檄书。"]},{"t":"兵后梁彦国自滦州见过","f":"七言律诗","c":["辽海君如管幼安，萧条一骑客行难。","堠边星落秦皇戍，战后云愁汉将坛。","驿路飞沙千里暗，海风吹雪万山寒。","灯前独照昆吾剑，长得蛟龙夜夜看。"]},{"t":"冬夜同梁彦国宿永光寺禅房怀故园诸子得来字","f":"七言律诗","c":["江南词赋有群才，曾共高僧社里来。","人忆歌骊辞粤峤，客疑招骏上燕台。","寒翻贝叶斋前诵，香识梅花雪后开。","惟与许询禅此夕，故园书待雁飞回。"]},{"t":"雪中同梁彦国过文寿承学舍","f":"七言律诗","c":["袖中怀刺倦尘沙，清晓寻君坐日斜。","客食空斋惟苜蓿，宦情高阁有梅花。","庭阴独下孤山鹤，禁雪遥栖万树鸦。","经学汉儒推博士，何人江左更名家。"]},{"t":"雪夜同惟敬饯别彦国还卢龙得高字","f":"七言律诗","c":["浊酒寒宵共尔曹，明朝东去客途劳。","山窥上谷孤城月，关倚玄菟万里涛。","黄竹当歌燕雪积，白云随骑朔风高。","期君早献甘泉赋，金马词臣待彩毫。"]},{"t":"送许舍人稚干请告还灵宝","f":"七言律诗","c":["金门侍从捧纶音，去采三花结远心。","令伯表陈臣分浅，茂陵书在主恩深。","雪凝嵩少扶藜往，云起殽函驻马吟。","东阁故人应暂别，岂容簪绂卧山林。"]},{"t":"送方宪副定之备兵饶州","f":"七言律诗","c":["使君千骑出长安，干越新开大将坛。","番令古城楼橹壮，康郎春浪舳舻寒。","军容班剑风云起，宾从胡床雪月残。","遥想雅歌闲对酒，芝山应是几回看。"]},{"t":"冬至斋居后惟敬夜过得残字","f":"七言律诗","c":["君从紫阁宿高寒，下直还能访鹖冠。","惇史书馀云未散，太常斋后雪初残。","千官肃穆骖鸾辂，万骑周遭傍泰坛。","闻道星辰环幄殿，侍臣执盖月中看。"]},{"t":"同文休承顾汝和黎惟敬于虎圈观西域所进狮子","f":"七言律诗","c":["禁苑般般绕象舆，伏狮何幸仰宸居。","风驱林邑千山外，云拥条支万里馀。","清庙已歌天马曲，君王犹纳旅獒书。","更闻九译来朝贡，太史编年在石渠。"]},{"t":"甲子元日早朝","f":"七言律诗","c":["千官催入紫宸班，缥缈炉烟夹仗间。","晓日洛中新甲子，春风燕甸旧河山。","凯成骠骑频归阙，诏许呼韩近款关。","共听太平元会曲，彩云飞处候龙颜。"]},{"t":"经南内","f":"七言律诗","c":["沉沉清禁转朱扉，深锁松阴碧石围。","汉月曾窥青鸟去，朔云先拥白狼归。","雅翻宫雪璚楼过，龙喷山泉玉殿飞。","司竹老臣犹望幸，太平无事宴游稀。"]},{"t":"登辽后妆楼","f":"七言律诗","c":["綵槛雕阑半已荒，房栊树色隐苍苍。","年深冻藓迷妆匣，人去秋云锁屧廊。","玉镜尚悬辽海月，璚花不散蓟门霜。","三千部落无劳望，鸭绿江头雁几行。"]},{"t":"上元日望大高玄殿灯火有赋","f":"七言律诗","c":["太一祈年肃盛仪，灯前亲拜竹宫时。","燎烟夕殿皆青玉，法供春筵尽紫芝。","雍畤旧传周室礼，汾阴今侍汉家祠。","云霄赋客多如雨，持橐何人独鬓丝。"]},{"t":"送钟公琪改令博白","f":"七言律诗","c":["移官因得故园游，津吏先迎郁水舟。","监郡久知皮氏长，赐书还问偃师侯。","装轻片石无劳载，山近丹砂且暂留。","万里登台应北望，题诗须寄蓟门秋。"]},{"t":"送徐别驾赴吉安","f":"七言律诗","c":["监郡多闲见吏能，安成山水最堪称。","黄牛石出疑巫峡，白鹭洲横似秣陵。","客至高斋悬榻下，诗成燕寝异香凝。","明年地主应携我，骑马青原更一登。"]},{"t":"送杨参军允恭守曲靖","f":"七言律诗","c":["五陵冠盖祖行杯，万里楼船晓日开。","越巂地形邛笮尽，盘江秋色叶榆来。","客游南部能蛮语，家出西京自楚才。","诸葛盟坛云树里，褰帷应向此登台。"]},{"t":"送林邦阳佥宪赴汴备兵陈州","f":"七言律诗","c":["中原谈笑拥青油，吹角河山万里秋。","猎骑风云生广武，蒐兵旌旆过鸿沟。","尊前书记知能赋，戏下材官待运筹。","不是玉关留客久，明年应得拜宸旒。"]},{"t":"送文休承赴吉水文学","f":"七言律诗","c":["家学吴门比陆机，一官犹着旧儒衣。","执经讲肆诸生满，临帖山斋过客稀。","雪浪每从章浦见，暮霞多入楚城飞。","石渠金马徵贤日，时倚江云忆禁闱。"]},{"t":"赠光禄李少卿请告还缙云省觐","f":"七言律诗","c":["班衣归去意何如，诏许仙都得暂居。","客舍难忘光禄酒，卿家真见缙云书。","听莺早过双溪水，下马先趋万石闾。","须忆柏梁台上宴，天涯春色伴还车。"]},{"t":"送沈祠部以安奉使因归省湖州","f":"七言律诗","c":["冠盖都亭揖玉鞭，故人多在蓟门天。","千山梦寐为郎日，六传风云奉使年。","綵服朝持新箬酒，白蘋春送太湖船。","建章莫作经时别，御柳轻摇万树烟。"]},{"t":"寄徐子与","f":"七言律诗","c":["汝南尊酒送征轮，何事君为去国人。","汉日将军逢醉尉，楚天渔父识孤臣。","瑶华独忆飘零远，金埒空闻贵幸新。","早晚承明应再入，谁容烟艇五湖春。"]},{"t":"寄濮州苏子川子冲兄弟","f":"七言律诗","c":["闻君濮上卧烟萝，兄弟才名二谢多。","玉树春风飞梦远，金茎佳气早鸿过。","钓台艇畔庄周石，草阁帘前瓠子河。","倘忆倦游梁苑客，可无书札慰蹉跎。"]},{"t":"王户部宅红梅花","f":"七言律诗","c":["东阁名花许共攀，独怜疏影近雕阑。","彩霞忽散春城色，绛雪犹飞夕照寒。","梦想海棠巴子树，步随宫柳汉臣冠。","关山莫遣吹横笛，留待江南醉客看。"]},{"t":"春日同惟敬约卿过弘法寺访翠岩和尚","f":"七言律诗","c":["鹿苑西连紫禁天，斋心曾问远师禅。","五台戒向山中受，双树花从雨后悬。","昼永鹤行春竹里，年深松偃石窗前。","许询颇解閒来往，杖锡何妨结静缘。"]},{"t":"同曾选部于野韩虞部子成夜集范职方于公宅","f":"七言律诗","c":["匈奴远遁塞烟销，尊俎曾筹万里遥。","士论总收燕騕袅，将材今数汉嫖姚。","山公有启傅三署，水部能诗冠六朝。","独笑荆高狂击筑，醉来犹自问金貂。"]},{"t":"答王百谷道馆病起对月见怀","f":"七言律诗","c":["牍中新草献长杨，渴似相如鬓已苍。","客去独吟松几月，僧来同掩竹斋凉。","扁舟远兴因吴语，斗酒高歌学楚狂。","东阁早闻奇士满，秋风吾有芰荷裳。"]},{"t":"送吕比部声甫守庐州","f":"七言律诗","c":["虎竹初分霄汉间，庐江小吏候濡关。","褰帷春雨劳农出，悬榻高斋送客闲。","云起每从三祖石，鹤来曾过八公山。","登楼不用怀京邑，早晚承明入计还。"]},{"t":"送冯屯部信伯补抚州","f":"七言律诗","c":["襜帷南去问桑麻，江燕飞飞引旆斜。","内史台边翻忍草，夫人坛上散明霞。","铜陵夜月红泉酒，绣幕春风玉茗花。","太小冯君称汉吏，赐金何日到天涯。"]},{"t":"次韵答曾参戎子澄塞上行军见寄","f":"七言律诗","c":["都亭别后忆驱驰，大漠听笳汉将悲。","南去长缨曾自请，北来骠骑一相随。","官刍召募飞应急，军市酣歌散未迟。","宾客兰台虽已老，燕然铭笔为君期。"]},{"t":"惟敬席上喜思伯使还","f":"七言律诗","c":["步兵厨里一尊深，闻尔还镳喜不禁。","使者玉鱼亲走送，故人金马独浮沉。","弹冠意气谁相许，拄杖烟霞尚可寻。","醉后莫论烽火事，并州空折白云心。"]},{"t":"约卿东巡以灵岩诸诗寄示闻已登岱岳","f":"七言律诗","c":["灵岩寺里赋新诗，千骑东方星斗随。","汉月颇窥三观石，秦云多挂五松枝。","燕齐有客谈仙诀，禽尚何年住岳期。","揽辔西风应奏草，玉皇宫阙待亲祠。"]},{"t":"送林维成宰邵阳","f":"七言律诗","c":["双旌南去路偏长，秋雁飞时白苧凉。","城浸烟波皆洞野，花开山郭似河阳。","竹枝自渡湘妃水，菰米先称楚客乡。","归赋上林还给札，莫誇云梦献君王。"]},{"t":"十六夜同黎秘书吴侍御梁舍人集梦芝馆听管山人作吴歌","f":"七言律诗","c":["千家明月照帘栊，高咏凉天散步同。","木叶自能飞洛下，秋声先已满云中。","银河影落词臣酒，玉兔光摇御史骢。","醉后忽闻歌子夜，禁城钟鼓思何穷。"]},{"t":"送李太守实夫罢归闽中","f":"七言律诗","c":["驱车落日满河梁，欲别犹堪典鹔鹴。","把袂几人燕市酒，裁书八月蓟城霜。","空令白雁随归客，只为青山忆故乡。","君到南中荣橘柚，应知三径未全荒。"]},{"t":"送姜宪副宗孝之关中","f":"七言律诗","c":["清朝侍从有光辉，十载祠官直禁闱。","绣斧日边新赐诏，油幢关外远宣威。","三秦豪杰分庭揖，二华烟云绕座飞。","早向长杨陪羽猎，汉家词赋似君稀。"]},{"t":"答潘少承经赤花海上见怀","f":"七言律诗","c":["三载离居忆酒垆，秋深犹自滞燕都。","谁堪侠气弹孤剑，独有归心寄五湖。","笛里关山新白发，楼前星斗乱黄榆。","君看甲子泥涂客，长啸烟中且钓鲈。"]},{"t":"送黄佥宪士弘入贺礼成取道南归为太夫人寿","f":"七言律诗","c":["紫宸车马出长安，仙掌秋深露已漙。","金鉴拜陈明主寿，玉觞归献使臣欢。","家藏桂籍分鸾掖，筵近梅花照豸冠。","闻道曾孙迎太姥，画图何异幔亭看。"]},{"t":"九日惟敬置酒与张刘管张四山人同赋","f":"七言律诗","c":["白云箫瑟一尊开，共佩萸囊上蓟台。","橘熟题书曾问讯，菊荒为客未归来。","秋高大漠胡尘净，日落长杨汉骑回。","惟羡故人今侍从，飘零谁道子虚才。"]},{"t":"重阳后一日同古比部黎秘书集张民部宅","f":"七言律诗","c":["班生宁望酒泉封，旅食重阳已再逢。","紫闼梦悬金涧月，白云心寄石闾松。","故人薄禄多官酿，狂客酣歌待禁钟。","手把茱萸还强饮，明年何地忆追从。"]},{"t":"同黎秘书曾缮部吴侍御万金吾出善果寺访冯侍御","f":"七言律诗","c":["封事朝驰玉节孤，青云冠盖满城隅。","客携擂具迎公子，人向高阳问酒徒。","白简霜飞千里草，紫驼秋落九关榆。","燕歌未歇传杯夕，犹识风流在汉都。"]},{"t":"题玉洞桃花图赠大司空蔡公","f":"七言律诗","c":["赤墀委佩更珊珊，五十曾登汉将坛。","胡骑早闻安石墅，洛师犹忆惠文冠。","关门紫气何人候，湖水扁舟异日看。","万树桃花天目上，山炉应熟九还丹。"]},{"t":"送李子新还扬州因讯黄定父","f":"七言律诗","c":["霜欺季子黑貂裘，金尽长安不可留。","黯黯离情平谷月，萧萧归骑广陵秋。","十年生事餐菰米，万里勋名视蒯缑。","欲寄黄郎无尺素，但凭飞梦过瓜洲。"]},{"t":"秋风 其一","f":"七言律诗","c":["萧瑟秋风天雨霜，年来书剑半摧藏。","画眉京兆颇相笑，舞袖长沙空自伤。","客计未应羞马牧，宦情谁肯薄淮阳。","心知不待题麟阁，犹得诙嘲陛楯郎。"]},{"t":"秋风 其二","f":"七言律诗","c":["清切遥看西掖垣，几人荐引登金门。","龙渊池出斗牛气，凤诏天垂云雨恩。","醉白渐多嵩洛梦，草玄已老蓬蒿园。","飘零短褐秋风客，睥睨心期惟酒尊。"]},{"t":"大理潘公雪夜邀同吴侍御黎秘书万金吾集","f":"七言律诗","c":["夜深寒色照帘栊，廷尉留宾似孟公。","且共持觞燕市里，岂论结袜汉庭中。","秋风城阙闻清角，积雪关山断暮鸿。","赋客此时惭授简，独能沉醉倚青骢。"]},{"t":"雪夜同陆山人过张司理时张已补外陆将还山","f":"七言律诗","c":["寒色千门日易低，为君一过玉河堤。","月移赵瑟佳人起，雪照吴钩侠客携。","官阁梅花孤梦后，钓船春草五湖西。","天涯尺素题何处，好忆燕台疋马嘶。"]},{"t":"同吴约卿携酒访姚元白于慈仁寺因登毗卢阁得山字","f":"七言律诗","c":["秦京久客待君还，鹿苑相携霄汉间。","地涌飞楼云绕舄，天连孤鸟日衔山。","高寒并见金茎影，禁近初归玉笋班。","萧瑟秋风怜庾信，江南何处望乡关。"]},{"t":"曾比部子玉宅同冯侍御黎秘书胡礼曹夜集","f":"七言律诗","c":["华发金门隐岁星，知君执戟爱沉冥。","凤毛家学闻江左，马尾官书在汉廷。","醉后自能歌白雪，灯前谁共舞青萍。","郊园赐沐承恩日，曾恋松萝月满亭。"]},{"t":"送刘评事少脩调望江令","f":"七言律诗","c":["雪花燕甸马鞯寒，又送鸣珂出禁銮。","三礼甲科郎选重，大雷渔长主恩宽。","且因粳稻移家去，岂谓风尘作吏难。","闻是尚方曾赐舄，飞凫还望到长安。"]},{"t":"至日同姚元白苏子川黄定父吴约卿张羽王饮黎惟敬宅时元白将还白下羽王将之雷州","f":"七言律诗","c":["阊阖阳生积雪光，高城夕送雁千行。","江南不见梅花使，蓟北空持柏叶觞。","银烛莫教歌管歇，玉颜应笑鬓丝长。","风流渐觉词人散，不待他年忆建章。"]},{"t":"雪中戴伯常见过","f":"七言律诗","c":["晓雪如花片片飘，鸣珂犹复问僧寮。","人寻洛下无行径，客倦咸阳有敝貂。","苑树风吹珠错落，禁城山拥玉岧峣。","冲泥欲跨银鞍去，先访将军第五桥。"]},{"t":"赠张司理羽王之雷州","f":"七言律诗","c":["酒尽征车不可留，劳君万里拥缇油。","荔枝熟处江云湿，杉叶飞时海郡秋。","赋后鹏抟多作浪，尊前蜃起自成楼。","竹书岁报无冤狱，前席从容待借筹。"]},{"t":"寄王仲房","f":"七言律诗","c":["闻君久托远游心，浮世行藏自陆沉。","掌记军中曾入幕，飞书海上亦辞金。","扁舟夜钓黄湖冷，精舍秋移白岳深。","谡谡松风何处听，杖藜吾欲一相寻。"]},{"t":"次韵答顾玄纬见寄","f":"七言律诗","c":["早买山田四十双，扁舟归去老江乡。","谈禅有客期兰若，看竹何人问草堂。","世许谷云工笔札，自羞辕固少文章。","一轺欲访延陵子，天末题书报雁行。"]},{"t":"洞泉有仙人卢至柔遗迹顾光禄隐居在焉为赋是诗","f":"七言律诗","c":["璨山深访羽人居，洞酌亭前寄敝庐。","流水玉琴挥轸外，秋风金涧听松馀。","曾攀丘垄乌啼树，尚忆云窗鸟篆书。","江左周颙归未得，十年猿鹤意何如。"]},{"t":"诚意伯刘公宅同群公宴集得孤字","f":"七言律诗","c":["东阁梅花照玉壶，上公开宴集城隅。","汉京授简新词客，燕市衔杯旧酒徒。","盟府勋名班剑在，中天邸第白云扶。","长裾不少清狂兴，醉散朱门月色孤。"]},{"t":"吴明卿上计至都下","f":"七言律诗","c":["使者归来谒建章，郁葱佳气满咸阳。","禁中乐府歌朱鹭，阙下书生对白狼。","鸣玉班行收客泪，赐金颜色借恩光。","子虚颇有相如赋，侍从无劳上汉皇。"]},{"t":"岁暮次韵答施虞部","f":"七言律诗","c":["避喧金马即山堂，燎玉空瞻紫禁光。","把酒病犹逢汉腊，披裘寒自拂胡霜。","家人椒颂劳相忆，驿使梅花远莫将。","惟有吟诗何水部，共凭高阁望江乡。"]},{"t":"送徐子明赴苍梧参军","f":"七言律诗","c":["跃马都门意气生，飞书骆越旧知名。","炎洲道路三千里，沧海戈船十万兵。","岂为故人誇负弩，祇缘多难请长缨。","伏波门下南征曲，更听袁郎玉笛声。"]},{"t":"冬日同文博士寿承黎秘书惟敬集顾舍人汝和宅","f":"七言律诗","c":["逢君休沐下东华，邀赏高斋到日斜。","已道书钞麟趾殿，真看画在虎头家。","香炉云起匡山石，金灶烟分顾渚茶。","闻道五陵公子醉，只誇银甲拨琵琶。"]},{"t":"同项思尧黎惟敬诸君饮顾光禄汝所齐中乃兄汝由直阁汝和舍人皆在会","f":"七言律诗","c":["绛蜡金尊夜不寒，岂知今夕在长安。","步兵厨里酒新熟，拥衲龛前雪未残。","家有赐书班嗣富，名齐伯仲季方难。","醉来索笑梅花下，何似扬州水阁看。"]},{"t":"同惟敬夜过明卿得台字","f":"七言律诗","c":["送腊尊醪日日开，明星驱马凤城隈。","天知汲黯淮阳至，人笑王生渤海来。","裘剑摧藏惟解饮，风尘荏苒几怜才。","俸钱莫问今多少，且共酣歌上蓟台。"]},{"t":"除夕卧病酬施虞部见召不赴因订早春之约兼呈曾郎中吴韩二员外","f":"七言律诗","c":["东省屠苏念故人，席门虚枉使车频。","愁深白发三年客，梦破青山一病身。","玉醴想添新岁色，金钱将醉曲江春。","申公已侧当时目，犹得交欢侍从臣。"]},{"t":"送庞侍御少南出按两浙二首 其一","f":"七言律诗","c":["明堂令布履端馀，宪府霜飞按越初。","沧海潮回收万弩，潢池氛净出单车。","探碑禹穴多奇字，访士桐江有旧庐。","八使风流谁得似，西京人望皂囊书。"]},{"t":"送庞侍御少南出按两浙二首 其二","f":"七言律诗","c":["同时学赋羡君成，流落怜子十载情。","周室主书专柱史，汉家掌故待诸生。","交游敢望弹冠出，父老应随负弩迎。","浙水东西怀绣斧，江花那得计王程。"]},{"t":"瑞室诗为四明薛子熙赋","f":"七言律诗","c":["明经旧署郑公乡，南渡衣冠岁月长。","野火不惊焦处士，山云常护鲁灵光。","藤交瀑下窗犹暗，菊散霜前径未荒。","奇字祇今邻禹穴，高楼还儗并梅梁。"]},{"t":"诚意伯刘国桢使楚饯别于孙鸿胪宅得枝字","f":"七言律诗","c":["燕台征骑早春时，九陌青青折柳枝。","玉节星随周使者，朱陵云识汉官仪。","澧兰尽入词人赋，湘竹宁忘帝子思。","鸿雁从来飞不到，天涯何处问归期。"]},{"t":"陆使君道函入计还宝庆","f":"七言律诗","c":["使者朝宗出帝阍，赐金南去奉明恩。","飞花扑面驱邮传，落日离心寄酒尊。","风曳珠旗云梦泽，马嘶春草邵陵原。","上林奏赋嗟留滞，待尔鸿书到蓟门。"]},{"t":"清明前一日同方行人岳文学江张二山人集孙鸿胪宅得孙字","f":"七言律诗","c":["三年持橐傍金门，汉署还来问酒尊。","千叠浮云迷客舍，五陵春草送王孙。","莺声半入华阳馆，马首频窥灞水园。","他日看花携手客，禁烟时节望中原。"]},{"t":"送魏顺甫使君上计还济南","f":"七言律诗","c":["河梁垂柳拂雕鞍，竹马争迎稚子欢。","燕筑深杯怀历下，楚歌明月满长安。","黄金恩重君王赐，白雪词高和者难。","别后椷书何处寄，春鸿飞尽岱云寒。"]},{"t":"赠黎君华岑贞叔南还","f":"七言律诗","c":["风起春城日易阴，留君斗酒故情深。","弃繻暂出西游路，献玉终酬北望心。","驿路新莺难驻马，天涯久客易沾襟。","垆头诸少应相忆，为报秋期在竹林。"]},{"t":"送冯侍御出按山西","f":"七言律诗","c":["侍从当年草白麻，西行绣斧有光华。","晋阳列署看双柏，汾水鸣骢散五花。","霜落胡沙边燧暗，星随汉使岳云斜。","建章正待筹边疏，不用蒲稍入内家。"]},{"t":"雨后饮苏子川宅望西山得花字","f":"七言律诗","c":["西山爽气满窗纱，丹凤城南日未斜。","翠黛遥分燕柳色，青云平出岳莲花。","閤开双瀑长临涧，鸟度诸峰半带霞。","尊酒却疑人境外，谁知还醉近臣家。"]},{"t":"送刘选部孟真请告还夷陵","f":"七言律诗","c":["何事张衡咏四愁，飞花春散凤皇楼。","暂辞起草诸郎直，谁共鸣驺六传游。","三峡云帆巴子月，一江风笛渚宫秋。","廷中最忆山公启，兰佩荷裳未可留。"]},{"t":"送范职方于公奉使吴中","f":"七言律诗","c":["侍从频年奉柏梁，西风暂得过鲈乡。","出关偶作吴洲客，负弩争迎汉署郎。","山下清溪通夕照，城边白苧散秋凉。","輶轩归上江淮奏，愿遣材官事朔方。"]},{"t":"答戴进士仪周","f":"七言律诗","c":["燕市还来共酒杯，笑予寄宿在灵台。","省中兰佩今堪结，江上荷裳未可裁。","连骑岂知原宪病，淩云空羡马卿才。","玉河烟柳年年色，曾见何人奏赋回。"]},{"t":"送毕兆先掌教安福","f":"七言律诗","c":["与君少小竹斋谈，此日青毡出淦南。","沧海蛟龙双跃剑，蓟门风雨一分骖。","秋凉弦诵新茨野，夜色楼台石鼓潭。","别后江鸿谁共听，相思应有白云椷。"]},{"t":"送陈文学季谦赴信丰","f":"七言律诗","c":["闻道儒林近岭边，章江西上孝廉船。","片帆烟水三千里，双剑风云二十年。","韦氏只今推世业，文翁不敢倚先贤。","故人相送堪相笑，犹得微官足酒钱。"]},{"t":"徐子与入都见访","f":"七言律诗","c":["蓟云千片拥骅骝，把袂中原感旧游。","一别雪飞桐柏水，三年书寄白蘋洲。","铜龙见尔鸣珂入，金马怜予待诏留。","短发萧骚惟侠气，紫貂还问酒家楼。"]},{"t":"初秋同张李陈三户部王山人柴文学集天坛曹道士院得窗字","f":"七言律诗","c":["日午鸣钟迎客到，仙童花下立双双。","当秋山色分松院，过雨泉声冷石窗。","白鹤连翩参法席，灵风萧飒满经幢。","词人兴在烟萝外，有约还来倒玉缸。"]},{"t":"弘法寺送徐子与谪长芦","f":"七言律诗","c":["回首金门感慨多，汉家迁客一悲歌。","玉珂秋散祇园树，宝剑寒生易水波。","郡里太行新雁起，尊前渤海白云过。","主恩不遣长沙去，咫尺承明鬓已皤。"]},{"t":"早秋同达水部集施虞部省中园亭得来字是日期曾缮部不至","f":"七言律诗","c":["署中凉色满池台，更有双尊出旧醅。","濯露蔬劳园吏给，冒霜花为省郎开。","边烽幸绝甘泉报，胡雁初从大漠来。","寄问东曹词赋客，何时还共故人杯。"]},{"t":"讯沈祠部病","f":"七言律诗","c":["病来秋叶满亭皋，圣主斋居念礼曹。","露下金茎双阙迥，月明瑶瑟五陵高。","四愁有客思江汉，七发何人望海涛。","那得沈郎腰不瘦，闭门犹是著书劳。"]},{"t":"秋夕卧病对月怀许维桢何启图二内翰","f":"七言律诗","c":["卧游因病久盘桓，曾记名山万里看。","雪后驱车过汝水，月中摇艇入新安。","昔年白雁思传札，此日铜龙阻握兰。","尊酒何因携二妙，清光知在玉堂寒。"]},{"t":"乙丑九日同古茂毨蒙廷俞张鸿与蒙廷纶张伯邻郭笃周饮伦绍周宅","f":"七言律诗","c":["蓟城佳节忆烟皋，尚喜东邻有浊醪。","赤管自怜频索米，黄花犹得共持螯。","酒钱颇羡陶彭泽，诗句深知谢法曹。","岁岁佩萸何处客，归心偏恋五云高。"]},{"t":"送沈祠部谢病归吴兴","f":"七言律诗","c":["独辞省署向烟萝，金马其如病客何。","别骑关城惊雁早，归舟江峤听猿多。","帘前讲肆逢严叟，溪上清缨学楚歌。","知有郎中桑落酒，兰桡将泛太湖波。"]},{"t":"中秋同社诸子集方侍御宅得中字","f":"七言律诗","c":["醉客挥毫倚玉骢，西园今夕正秋风。","关山一赋秦城上，砧杵千声汉苑中。","歌后新凉生觱篥，尊前清露滴梧桐。","庾公此兴应非浅，月下何人赋最工。"]},{"t":"太霞洞天为永昌周象贤赋","f":"七言律诗","c":["兰津渡口望天池，曾见王乔来去时。","山气晓蒸华马国，海云寒接碧鸡祠。","丹砂不用求勾漏，采幔应看胜武夷。","觞客九霞堪一醉，何年瑶水与君期。"]},{"t":"燕京秋夜登楼怀故园","f":"七言律诗","c":["风起飞沙日易阴，高城吹角此登临。","归人书去孤鸿杳，游子心惊落叶深。","千垒浮云驱大旆，万家明月拭清砧。","故园亦在沧江上，烽火年年听捷音。"]},{"t":"南溪泛舟遇雨客有怀江南者共赋中字","f":"七言律诗","c":["城西陂上晚溟濛，越客扁舟望不穷。","渭水云沉波色里，长杨秋在雨声中。","乍飞鹤子翻池白，欲尽荷花坠露红。","多少燕姬愁翠黛，共将离思寄江枫。"]},{"t":"送袁解元南归","f":"七言律诗","c":["异乡携手客愁开，秋色飘零酒一杯。","未论南州曾荐士，只知东阁解怜才。","蓟门落叶千砧送，沧海惊波一棹回。","已笑中涓求骏晚，黄金宁不待君来。"]},{"t":"雨夜同薛文学晁秀才集吴侍御子沐宅","f":"七言律诗","c":["君家绿酒照玻璃，佳句还邀烛下题。","宫漏稀闻官舍里，城云低度禁垣西。","铜街踏雨寒嘶马，白简朝天曙听鸡。","他夕金龟能笑解，二豪犹得醉相携。"]},{"t":"送戚进士世秀请告归泗州毕姻","f":"七言律诗","c":["金门诏许出关遥，淮水乘龙意气骄。","鳷鹊青云随去骑，凤皇新月在鸣箫。","花摇屏烛春开宴，星引天津夜度桥。","想是听鸡还戒旦，含香催入圣明朝。"]},{"t":"子与约会沧州予将从德州南行不得过先寄此作","f":"七言律诗","c":["献策无媒将远游，萧萧一骑出卢沟。","白云不散青枫色，明月独照黄河流。","欲赠生平三楚璞，可怜离合双吴钩。","他时莫忆悲歌客，别后何人燕市秋。"]},{"t":"寄李于鳞 其一","f":"七言律诗","c":["屏居犹在列仙乡，十二楼台蜃雾旁。","客自函关占紫气，世从鲁甸识灵光。","窗前海近弹琴润，岳顶云来散帙凉。","难向此中歌白雪，相将看日到扶桑。"]},{"t":"寄李于鳞 其二","f":"七言律诗","c":["高楼不下绝风尘，傲吏当年早乞身。","金匮山经藏岱岳，石渠门客出咸秦。","酒曾累日逢中圣，赋更何时奏大人。","海内从来誇御李，愿从骑鹿过千春。"]},{"t":"雪夜古比部携酒雷比部同过","f":"七言律诗","c":["蓟门积雪九衢光，犹得相随酒榼狂。","紫禁地分文学掾，白云天远尚书郎。","骊驹不用催官骑，鸾鹤偏能恋帝乡。","此夜王猷好乘兴，他年无忆剡溪长。"]},{"t":"送范太史伯祯奉使册封鲁王","f":"七言律诗","c":["殿前三策献宸旒，人识词林第一流。","玉节西分周太史，金符东授汉诸侯。","古城弦诵兼风雪，复壁图书烛斗牛。","邹鲁千秋还讲业，归来何异马迁游。"]},{"t":"余省觐岭外马进士使辽东饮别霍进士爱大宅得真字","f":"七言律诗","c":["祖筵雪色照城闉，海内交情尔最真。","岭表辽阳明日路，貂裘狐帽异乡身。","尊前星斗关山远，阙下衣冠气象新。","燕赵悲歌还此地，重来击筑更何人。"]},{"t":"诸太史邀饯席上留别","f":"七言律诗","c":["玉署开尊雪满庐，勾陈东望逼天居。","浮沉祇自逢宾戏，浅薄何能赋子虚。","离夜肯留文学宴，聚星今得史官书。","一经南去还持橐，遥忆名儒议石渠。"]},{"t":"大理邹卿夜饯席上留别","f":"七言律诗","c":["乌飞廷尉府中栖，坐拥燕山玉嶂低。","半夜星辰丹凤绕，千门冰雪紫驼嘶。","避人谏草閒曾检，爱客诗篇醉屡题。","我去扬州五湖月，春鸿偏忆禁垣西。"]},{"t":"张掖门留别曾以三缮部","f":"七言律诗","c":["燕市千杯送我归，中原交友似君稀。","易为易水悲歌泪，难把河梁落日衣。","霜草台边孤骑去，朔云天畔几鸿飞。","谁怜长乐听钟客，独向江淮忆禁闱。"]},{"t":"周子脩苏子川丁庸卿周汝砺孙文济孙文鼎项思尧黄汝会柴季通黄定父纪旭仁诸君枉饯席上留别","f":"七言律诗","c":["高阳宁得少吾徒，结客青萍日渐孤。","彯组尔应留汉署，下帷人自出江都。","他乡梦里思琼树，明月歌中倒玉壶。","别后迢迢怜尺素，不知双鲤到淮无。"]},{"t":"张掖门再别曾缮部","f":"七言律诗","c":["关前立马色苍苍，抗手还同汉署郎。","双阙风云分去路，千山冰雪照离觞。","蓟门赋后馀双鬓，碣石书归待八行。","别汝相思无远近，天涯一望九回肠。"]},{"t":"过河间郡","f":"七言律诗","c":["幽州甲士何翩翩，自许黄金召募年。","插羽东翻沧海日，鸣铙北扫塞垣烟。","路旁小儿能杀马，河间姹女工数钱。","不见听鸡刘越石，侠客中原空自怜。"]},{"t":"渡河入德州却寄慈仁和尚","f":"七言律诗","c":["鲁门一望水如渑，渐远长安隔五陵。","钜野旆旌苍树出，暮天楼橹白云升。","鸦归返照啼高冢，马饮寒流顾断冰。","行役驱驰飞锡远，题书心愧雁门僧。"]},{"t":"登岱二首 其一","f":"七言律诗","c":["天风飒飒起秦松，鸾鹤相随上岱宗。","石暗客窥千岁字，雪残僧扣万山钟。","翠华日月开虞狩，玉检云霞护汉封。","曾是仙人期六博，夜来还借二茅龙。"]},{"t":"登岱二首 其二","f":"七言律诗","c":["岁杪东游亦快哉，石闾高倚避风台。","射牛不用诸生议，牵狗疑逢老父来。","舄外波涛银阙涌，杯前齐鲁白云开。","谁能婚嫁迟栖岳，禽尚何年向此回。"]},{"t":"阙里谒孔庙","f":"七言律诗","c":["尼泗千年启閟宫，坛前冠佩讲时同。","凤衰歌后人何在，麟出书成道已穷。","鲁壁藏经残简积，汉祠祝史太牢崇。","东来邹峄观乡射，犹听金丝到庙中。"]},{"t":"谒孔林","f":"七言律诗","c":["世家何但表东州，梁木空摧万古愁。","鸟下山犹庐冢夕，叶彫林似奠楹秋。","岱云不向城边散，泗水长悬天上流。","落日缁帷延首地，松门风急下寒沟。"]},{"t":"衍圣公留宴","f":"七言律诗","c":["堂开曲阜带林霞，西第歌钟起暮鸦。","车服尚传秦博士，宫墙犹识鲁东家。","烟生宝鼎皆成篆，雪积琼枝半缀花。","岱岳诸峰明月色，相将终宴向庭斜。"]},{"t":"过薛城","f":"七言律诗","c":["公子倾身下士年，至今侠气尚翩翩。","三千客散荒秋草，七十城空锁夕烟。","长铗飘零收慷慨，高台歌舞惜婵娟。","不须更奏雍门曲，牧竖樵童满墓田。"]},{"t":"夜登徐州驿楼","f":"七言律诗","c":["汴泗交流重镇成，千家雉堞听涛声。","浊河月涌台边迥，衰草天连雪后平。","霸气只今销沛上，楚歌犹自满彭城。","汉家更欲沉玄璧，酾酒黄楼万古情。"]},{"t":"青口驿遇乡僧介公同登三祖山望灊皖天柱诸峰","f":"七言律诗","c":["地布黄金玉作岑，西来三祖古禅林。","山云半剪传衣色，海石空留听偈心。","涧水供筵经雪净，竹房清梵出烟深。","道人白鹤同僧去，天柱还随杖锡寻。"]},{"t":"闻黎职方惟敬已趋金陵予自黄梅渡江过浔阳不得相见","f":"七言律诗","c":["献岁东风彩鹢催，浔阳难待故人回。","独驱涛色三湖过，不见梅花五岭来。","持橐旧随鳷鹊观，挥毫今忆凤凰台。","樱桃未熟还江北，莫负金陵几百杯。"]},{"t":"江州城楼晚望","f":"七言律诗","c":["家在渔村有钓蓑，偶从簪弁失烟波。","怀人书札春鸿早，作客江湖夜雨多。","匡岳千峰云不散，浔阳九派路如何。","五噫岂似关东去，回首中原一放歌。"]},{"t":"瑞州官舍同黎比部晚酌净芳亭","f":"七言律诗","c":["征轺计日问长亭，筠上从君倒玉瓶。","宪府戟枝移竹院，官池波色上莎厅。","频瞻南峤云俱白，三渡西江草又青。","同得趋归家庆近，茅堂灯火带春星。"]},{"t":"燕京秋夜闻砧","f":"七言古诗","c":["丹凤城南夜正长，万家明月捣衣裳。","忽惊落叶频沾臆，不听悲笳亦断肠。","遮虏渐闻过马邑，拔营曾报破龙荒。","豫愁绵折天山下，那识弓胶瀚海旁。","书去再经燕草绿，梦飞不到塞云黄。","玉关纵待封侯入，祇得萧萧白发郎。"]},{"t":"秋夜登曾缮部省中楼同黎惟敬赋","f":"五言绝句","c":["骋望遥天云，迢迢带城阙。","关山一笛声，况是高楼月。"]},{"t":"赠曹山人幼兴南还","f":"五言绝句","c":["君看槐树陌，何似桃花源。","独有长安梦，相随还故园。"]},{"t":"张山人将游五岳过予寓舍为别二首 其一","f":"五言绝句","c":["暂揖市上鞭，一送云中辔。","归时五游成，示我青苔字。"]},{"t":"张山人将游五岳过予寓舍为别二首 其二","f":"五言绝句","c":["张公江海客，亦诵龙虎文。","他日相逢处，罗浮鹤是君。"]},{"t":"送人游岳州","f":"五言绝句","c":["离人愁独醒，湘草正青青。","忆上巴陵渡，春波满洞庭。"]},{"t":"刘子脩同往赵园看芍药马上作 其一","f":"五言绝句","c":["何代金谷园，斜连上林苑。","十里看花人，五陵紫骝远。"]},{"t":"刘子脩同往赵园看芍药马上作 其二","f":"五言绝句","c":["玉勒有佳期，一片锦云白。","谁将洛下春，誇向杨州客。"]},{"t":"新春曲寄子冲 其一","f":"五言绝句","c":["玉貌飒风沙，何人不忆家。","江南春未到，马上听琵琶。"]},{"t":"新春曲寄子冲 其二","f":"五言绝句","c":["曲中花半开，羯鼓莫频催。","芳草思公子，春从濮上来。"]},{"t":"新春曲寄子冲 其三","f":"五言绝句","c":["宜春连下苑，十里色葳蕤。","白马翩翩去，金鞭半欲垂。"]},{"t":"新春曲寄子冲 其四","f":"五言绝句","c":["徐生誇绝倡，醉杀五陵豪。","我醉何持赠，君王有赐袍。"]},{"t":"题友云卷","f":"五言绝句","c":["云来积金峰，影落朱阳馆。","先生不出山，窗中共舒卷。"]},{"t":"题董体仁玉几山房","f":"五言绝句","c":["斋居玉几侧，秋草下帷青。","弟子谁都讲，来传董氏经。"]},{"t":"赣州歌四首 其一","f":"七言绝句","c":["东闽南粤带郴西，岭北辕门号令齐。","鼓吹行边万馀里，风霆犹过汉山溪。"]},{"t":"赣州歌四首 其二","f":"七言绝句","c":["翠浪玉虹南斗间，庾关北走更千山。","大纛高牙秋色里，白云长对节楼闲。"]},{"t":"赣州歌四首 其三","f":"七言绝句","c":["郁孤台下江月光，白鹊楼前江水长。","何处边笳传塞曲，万家砧杵满城霜。"]},{"t":"赣州歌四首 其四","f":"七言绝句","c":["筹边军府有高楼，节制蛮方几十州。","赣水城头夜吹笛，梅花飞落楚门秋。"]},{"t":"小除夕至奉新","f":"七言绝句","c":["雪过青山马上看，故乡千里岁将残。","遥知祀灶比邻会，独念征人驿路寒。"]},{"t":"望玉笥山","f":"七言绝句","c":["群玉诸峰不可群，斗牛千里此中分。","荡胸渺渺飞鸿去，天畔遥看一片云。"]},{"t":"过石涧桥初入庐山","f":"七言绝句","c":["曲涧泠泠乱石中，红尘已隔几千重。","从今欲控仙人鹤，飞过匡庐第一峰。"]},{"t":"虎溪桥","f":"七言绝句","c":["虎啸中原天地间，白云犹得一溪闲。","溪前送客师应笑，何事柴桑亦出山。"]},{"t":"白莲社","f":"七言绝句","c":["净土莲曾几度开，游人今日有宗雷。","高僧若结云中社，谁更攒眉不肯来。"]},{"t":"善法堂","f":"七言绝句","c":["弥陀殿侧远公堂，忆昔开山古道场。","缁素三千来此会，苍茫禅海一津梁。"]},{"t":"讲经堂","f":"七言绝句","c":["东林曾疏涅槃疑，石木苍苍雪满池。","弟子何人更都讲，山猿犹似听经时。"]},{"t":"许州道中 其一","f":"七言绝句","c":["茅屋萧萧颍水斜，行人何处问曹家。","春深山下棠梨树，犹自千条缀雪花。"]},{"t":"许州道中 其二","f":"七言绝句","c":["许下长途片雪残，貂裘狐帽过春寒。","题诗誇向江南客，嬴得琼瑶马上看。"]},{"t":"过广武","f":"七言绝句","c":["广武山前云色开，千年楚汉已尘埃。","时无英雄有竖子，长啸秋风天际来。"]},{"t":"题邯郸吕仙祠","f":"七言绝句","c":["漳河西问主人餐，釜里黄梁醉后看。","闻道吕公曾一梦，自怜驱马过邯郸。"]},{"t":"赵州大石仙桥","f":"七言绝句","c":["何处仙人倚石阑，骑驴曾此向长安。","华清一笑远山后，应忆西南栈道寒。"]},{"t":"登保定城望西北诸关 其一","f":"七言绝句","c":["百里边城倒马关，白羊口外戍兵还。","恩深一剑封侯晚，已觉风沙老客颜。"]},{"t":"登保定城望西北诸关 其二","f":"七言绝句","c":["烽火星连战后云，庙堂悬爵待殊勋。","将军万里怀金印，明月胡笳夜夜闻。"]},{"t":"登保定城望西北诸关 其三","f":"七言绝句","c":["居庸关外虏降多，百万旌旗奏凯歌。","一望燕云今内地，紫骝嘶过白沟河。"]},{"t":"登保定城望西北诸关 其四","f":"七言绝句","c":["三辅星屯护帝京，渔阳上谷尽精兵。","汉家斥堠天山外，不用劳军细柳营。"]},{"t":"早过卢沟桥","f":"七言绝句","c":["客行万里见金台，晓渡卢沟霁色开。","听尽春鸿还策马，关门应笑弃繻来。"]},{"t":"广德寺禅堂观牡丹","f":"七言绝句","c":["黄花翠竹散清芬，又见华鬘一院云。","独坐翻经台畔石，几回天女异香闻。"]},{"t":"王仪甫索题黎惟敬画","f":"七言绝句","c":["绿柳晴波杳霭间，昆吾御宿直南山。","仙郎尚记看花处，宫锦曾披跨马还。"]},{"t":"题刘子脩画牡丹送吴子充还白下 其一","f":"七言绝句","c":["内苑繁花胜绮罗，五陵春色共经过。","君归独把金陵酒，一曲谁同玉树歌。"]},{"t":"题刘子脩画牡丹送吴子充还白下 其二","f":"七言绝句","c":["春深魏紫满雕阑，尔到江南尚未残。","独有长安骑马客，曲江亭上几回看。"]},{"t":"送罗美至宰云梦五首 其一","f":"七言绝句","c":["李白曾为七泽游，东窥云梦带昭丘。","竹枝歌罢巴童醉，月在西陵万树秋。"]},{"t":"送罗美至宰云梦五首 其二","f":"七言绝句","c":["孤城更在楚江西，涢口千山夕照低。","君去行春应露冕，不堪烟雨听猿啼。"]},{"t":"送罗美至宰云梦五首 其三","f":"七言绝句","c":["于菟何处梦中归，此地蒲骚旧垒非。","试向斗辛城上望，枫林江水白云飞。"]},{"t":"送罗美至宰云梦五首 其四","f":"七言绝句","c":["使君游猎苑云开，明月珠旗曳楚台。","不羡子虚誇作赋，相如还奏上林来。"]},{"t":"送罗美至宰云梦五首 其五","f":"七言绝句","c":["汉江东下洞庭寒，赋客登楼把酒看。","莫道烟波千万里，春鸿飞处是长安。"]},{"t":"送许充复赴滁州","f":"七言绝句","c":["一舸江淮水寺钟，看碑应到白云重。","风尘羡尔扶藜去，秋满琅琊七十峰。"]},{"t":"送胡宪使伯贤赴滇中六首 其一","f":"七言绝句","c":["万里中原一骑过，清秋饮马渡黄河。","不知何处登楼赋，衡岳峰头白雁多。"]},{"t":"送胡宪使伯贤赴滇中六首 其二","f":"七言绝句","c":["诏下楼船习水犀，昆明更在益州西。","非缘圣主贤臣颂，争遣王褒祀碧鸡。"]},{"t":"送胡宪使伯贤赴滇中六首 其三","f":"七言绝句","c":["叶榆河上赤枫秋，霜落苍山小队游。","骑吹翩翩迎汉使，诸蛮西拜五花楼。"]},{"t":"送胡宪使伯贤赴滇中六首 其四","f":"七言绝句","c":["岛夷曾畏伏波军，久见边尘断吐蕃。","白日烟消西洱海，青天云捲雪山门。"]},{"t":"送胡宪使伯贤赴滇中六首 其五","f":"七言绝句","c":["南中孟获七擒时，羽扇从容不用师。","铃阁治书逢使者，函封先寄爨王碑。"]},{"t":"送胡宪使伯贤赴滇中六首 其六","f":"七言绝句","c":["腰间宝剑七星开，何限中朝赠策来。","君上高峣还北望，白榆秋色满燕台。"]},{"t":"燕京迁居城南次韵答张鸿与伦绍周见讯 其一","f":"七言绝句","c":["碣石宫前偶卜居，都亭奏记未堪书。","上林亦有相如赋，五色云中望玉舆。"]},{"t":"燕京迁居城南次韵答张鸿与伦绍周见讯 其二","f":"七言绝句","c":["浮沉燕市结交新，击筑酣呼满四邻。","君看龙门谁奋袖，自怜不识汉平津。"]},{"t":"送梁判官之郁林","f":"七言绝句","c":["临蒸南去路悠哉，塞雁飞时海燕回。","一片郁林犹有石，政成还伴使君来。"]},{"t":"刘仲恭索题文休承西湖图","f":"七言绝句","c":["藕花风起绿波间，十里平湖十里山。","载酒寻僧谁可共，画船吹笛月中还。"]},{"t":"闻姚元白南还已过徐州","f":"七言绝句","c":["书寄彭城雁已还，春风先到秣陵关。","梦中不记黄楼上，万里天涯一片山。"]},{"t":"题陈士谦墨竹","f":"七言绝句","c":["词客当年有钓台，檀栾犹见夹池开。","玉箫曾共吹明月，何处双飞碧凤来。"]},{"t":"黎惟敬席上文休承有赠歌者戏和二首 其一","f":"七言绝句","c":["燕市悲歌酒易消，双声流响入云霄。","送君更唱江南曲，草绿吴洲第几桥。"]},{"t":"黎惟敬席上文休承有赠歌者戏和二首 其二","f":"七言绝句","c":["西第留欢更此宵，清诗题赠董娇娆。","锦袍明月江船上，谁共扬州听玉箫。"]},{"t":"张侍御按浙还京吴侍御见招同饮万金吾园中因病不赴 其一","f":"七言绝句","c":["红药花边遣骑迎，青丝空返独含情。","曲中一片西湖月，閒杀文园病马卿。"]},{"t":"张侍御按浙还京吴侍御见招同饮万金吾园中因病不赴 其二","f":"七言绝句","c":["好客将军陈孟公，门前时系五花骢。","歌钟不到书生耳，斗酒新丰明月中。"]},{"t":"韩虞部子成以诗招饮次韵戏答","f":"七言绝句","c":["马似游龙拂蓟台，笑予犹得狎群才。","韩婴自冠儒林学，莫唤谈诗匡鼎来。"]},{"t":"寄李伯承 其一","f":"七言绝句","c":["看花春尽蓟门杯，一出承明尚未回。","曾是词臣随玉辇，岂堪西望柏梁台。"]},{"t":"寄李伯承 其二","f":"七言绝句","c":["南谯父老拥旌游，杯底黄河百折流。","落日离骚君莫读，浮云那似楚江秋。"]},{"t":"寄李伯承 其三","f":"七言绝句","c":["风尘九折畏途多，濠上观鱼且自歌。","天末故人题尺素，漆园为吏意如何。"]},{"t":"寄李伯承 其四","f":"七言绝句","c":["君上秋风百尺台，白云片片乱鸿哀。","江潭此去三千里，那得瑶华远寄来。"]},{"t":"寄苏子冲","f":"七言绝句","c":["酒钱正待苏司业，三月水边多丽人。","君自曲江骑马过，那能不醉五陵春。"]},{"t":"雪中题林逋观梅图","f":"七言绝句","c":["徵君不出意何如，雪满孤山一草庐。","诗在水边篱落处，岂堪西上茂陵书。"]},{"t":"题孙参军荔枝练鹊","f":"七言绝句","c":["红云开实满林香，海鸟孤飞练带长。","粤客赋成西掖里，荔丹时节最思乡。"]},{"t":"胡仲一谈嘉州淩云寺之胜王叔承欣然赋诗便欲西游邀予同作四首 其一","f":"七言绝句","c":["巴渝千里望峨眉，风急蒲帆片片吹。","日暮嘉陈江上客，竹枝歌里蹋船儿。"]},{"t":"胡仲一谈嘉州淩云寺之胜王叔承欣然赋诗便欲西游邀予同作四首 其二","f":"七言绝句","c":["淩云楼阁半空悬，踯躅花深雨更然。","五百比丘趍讲席，人天会里尽成仙。"]},{"t":"胡仲一谈嘉州淩云寺之胜王叔承欣然赋诗便欲西游邀予同作四首 其三","f":"七言绝句","c":["嘉州无数好山名，雪下岷峨春水生。","曾共高僧谈出世，尸陀林在钵罗城。"]},{"t":"胡仲一谈嘉州淩云寺之胜王叔承欣然赋诗便欲西游邀予同作四首 其四","f":"七言绝句","c":["楚天猿啸断人肠，鱼腹白盐归客航。","我欲裁书寄三峡，不知何处棹相将。"]},{"t":"对雪柬沈山人懋学三首 其一","f":"七言绝句","c":["白发黄金未易成，何年揖别汉公卿。","翩翩东郭先生履，犹向长安雪上行。"]},{"t":"对雪柬沈山人懋学三首 其二","f":"七言绝句","c":["木落女儿湖水低，雪花飞过断桥西。","孤山山畔梅千树，曾见诗人一杖藜。"]},{"t":"对雪柬沈山人懋学三首 其三","f":"七言绝句","c":["风雪驴车且未还，暂留蓟子在人间。","开窗谁识挥毫意，画出江南万叠山。"]},{"t":"题元人唐子华捕鱼图二首 其一","f":"七言绝句","c":["漫郎家世在烟波，一落红尘失钓蓑。","回首芙蓉溪上艇，买鱼沽酒意如何。"]},{"t":"题元人唐子华捕鱼图二首 其二","f":"七言绝句","c":["悲歌弹铗欲何依，春鳜秋鲈幸自肥。","手把渔竿容易去，五湖烟月待人归。"]},{"t":"送张伯衮参军之塞上二首 其一","f":"七言绝句","c":["出关沙草渐萋萋，虎帐孤悬涿鹿西。","塞上题书须早寄，莫令投笔过摩笄。"]},{"t":"送张伯衮参军之塞上二首 其二","f":"七言绝句","c":["桑乾明月照琵琶，都护西行莫忆家。","千骑不闻刁斗击，铙歌归及上林花。"]},{"t":"和戴伯常种兰同魏顺甫赋 其一","f":"七言绝句","c":["赐沐郊园正早春，碧兰为佩尚堪纫。","明朝握向龙楼侧，不扈江篱似楚臣。"]},{"t":"和戴伯常种兰同魏顺甫赋 其二","f":"七言绝句","c":["楚人赋本似离骚，燕颔将军亦綵毫。","一自兰台陪宴后，十年香草忆江皋。"]},{"t":"留别刘比部仲恭二首 其一","f":"七言绝句","c":["客子当筵意气真，满天霜雪一沾巾。","千杯不醉襄陵酒，明日关河万里人。"]},{"t":"留别刘比部仲恭二首 其二","f":"七言绝句","c":["上党天低南北分，帝乡携手恋青云。","心期五岭春鸿雁，还把瑶华一寄君。"]},{"t":"泰山四首 其一 封禅坛","f":"七言绝句","c":["芝泥封石满天坛，燎玉无光月色寒。","七十二君何处去，白云空自绕阑干。"]},{"t":"泰山四首 其二 仙人桥","f":"七言绝句","c":["闻道青螺去复回，何年驱石过蓬莱。","我今岳顶餐灵气，更待安期海上来。"]},{"t":"泰山四首 其三 日观峰","f":"七言绝句","c":["一出金门奉紫泥，孤灯日观听仙鸡。","君看东海扶桑影，高照长安玉殿西。"]},{"t":"泰山四首 其四 观海楼","f":"七言绝句","c":["海雾冥冥远接天，蜃楼东与岳云连。","十洲只在三山外，不遣楼船更候仙。"]},{"t":"浮淮","f":"五言古诗","c":["南征浮淮水，行迈方余舟。","桐柏导西来，湍激从安流。","鸿濑下涡浦，高澨见马丘。","扬帆唱归风，击汰齐棹讴。","夕曜涌明月，熻爚蠙珠浮。","龟龙腾以嬉，鸨雁翩其游。","在昔省徐方，师旅戒万艘。","水军发谯城，舳舻泛悠悠。","俛仰忆往事，波骇今千秋。","曙色荡溟昧，商飙复飂飗。","朅来肃王程，耽赏非所谋。","咏言仲宣赋，渺矣怀九州。"]},{"t":"广陵行","f":"五言古诗","c":["赤日沦金镜，黄枢闇璿图。","兹邦据海甸，自昔繁丽区。","邗沟过山阳，夫差以驰驱。","九鼎未入泗，祭胙归勾吴。","汉宗有刘濞，拒谏干天诛。","非也治宫馆，思霸蔑硕儒。","枚生宅空岿，董相井亦芜。","迹往伤荆杞，时来念屠沽。","隋家代云季，南巡握灵符。","持楫下汴水，开门朝江都。","龙旗逼象纬，凤扆临星湖。","奏乐九曲池，飞萤满山隅。","儿童歌李花，高台夕欢娱。","当时堕簪珥，今人拾玑珠。","宝帐荒月观，锦帆散秋菰。","我行一洒泪，悲歌杂啼蛄。","翩翩游侠子，粲粲倾城姝。","借问东陵贵，何如青门夫。"]},{"t":"感遇六首 其一","f":"五言古诗","c":["高楼在西北，崔嵬青云端。","绮窗玉玲珑，阿阁椒与兰。","明月沧池东，列宿丽且繁。","中庭凉飙激，肃肃罗帷寒。","佳人眇天末，荒草霜露残。","徽音不可闻，哀丝讵能弹。","朝亦以悲酸，暮亦以汍澜。","妾有榜泄歌，谁为平生欢。"]},{"t":"感遇六首 其二","f":"五言古诗","c":["鸿鹄顾其羽，池上鸣趋跄。","四海求匹俦，独立每彷徨。","昔余从南来，薄游入燕京。","浮云夹车毂，明星照干将。","敛足声利区，矫翼翰墨场。","流览驱百代，狂澜浩纵横。","大雅忽在兹，中原幸相当。","披褐拂鞶厉，周旋翱以翔。","千载在一朝，离合宁可常。","邈哉二三子，念我双明珰。"]},{"t":"感遇六首 其三","f":"五言律诗","c":["改服承嘉惠，顾盻昭王台。","黄金竟安在，碣石浮云开。","邯郸一鼓瑟，易水风且哀。","燕赵悲歌人，忼慷怀归来。"]},{"t":"感遇六首 其四","f":"五言古诗","c":["东登泰山上，下有沧海流。","晞发餐日精，一望麟凤洲。","渺渺三神山，宫阙如云浮。","虞巡柴岱宗，肆觐东诸侯。","登封七十家，升中乃射牛。","燕齐扼腕谈，入海多宿留。","安期不可遇，羡门不可求。","肃然与石闾，日月今千秋。","吾将仍羽人，乘蹻于丹丘。"]},{"t":"感遇六首 其五","f":"五言古诗","c":["还顾望大河，北风水增波。","梁王召词臣，宾客来相过。","日暮登平台，积雪高嵯峨。","游子一长啸，更为蓬池歌。","蒯缑行自怜，古欢今如何。"]},{"t":"感遇六首 其六","f":"五言古诗","c":["长淮向南流，直过曲江侧。","子弟昔娱游，枚马来偃息。","伊余遘清时，滥荷公府辟。","承明别我友，肃穆广陵役。","躧步文学林，笔札墙下积。","月请有升斗，商歌出金石。","朝阳梧桐枝，矫矫凤凰翼。","七襄欲报君，思见君颜色。"]},{"t":"杨子江楼感秋作","f":"五言古诗","c":["江介秋以风，芜城更萧索。","丛薄陨其英，繁林纷且落。","清波何湛湛，露下警孤鹤。","蟋蟀吟荒庭，流萤照罗幕。","亭皋眺万里，淮楚引嵩洛。","关山鸿雁来，高楼夜严柝。","飞蓬一失路，曹耦非所托。","推毂谢金张，回车避桑霍。","徒勤载酒人，颇哂校书阁。","樗散幸自存，雌伏祇能乐。","微尚夙所秉，因之悟龙蠖。"]},{"t":"拟古四首 其一","f":"五言古诗","c":["窈窕芙蓉池，乃在西园侧。","池上双鸳鸯，并戏朝与夕。","别君已三载，弦望无消息。","寒温宁得知，何况见颜色。","踟蹰念离居，沉忧不能食。","愿因东南风，一送归飞翼。"]},{"t":"拟古四首 其二","f":"五言古诗","c":["行行东路长，去去西人远。","形影参以商，道路骥以蹇。","别指双星期，零露秋未返。","急景逝若飞，兰茝忽已晚。","曲房惊飙来，一夕三辗转。","揽衣不下堂，河汉自清浅。"]}]};